let LANG = 'ru';
try {
    const saved = localStorage.getItem('spellschess-lang');
    LANG = saved || (String(navigator.language || 'ru').toLowerCase().startsWith('ru') ? 'ru' : 'en');
} catch (e) { /* язык по умолчанию */ }
const CYR = /[А-Яа-яЁё]/;
let EN_RULES = null;
const escRe = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function tr(str) {
    if (LANG !== 'en' || typeof str !== 'string' || !CYR.test(str)) return str;
    if (EN[str] !== undefined) return EN[str];
    if (!EN_RULES) {
        EN_RULES = Object.keys(EN).sort((a, b) => b.length - a.length).map(k => {
            const pre = CYR.test(k[0]) ? '(?<![А-Яа-яЁё])' : '';
            const post = CYR.test(k[k.length - 1]) ? '(?![А-Яа-яЁё])' : '';
            return [new RegExp(pre + escRe(k) + post, 'g'), EN[k]];
        });
    }
    let out = str;
    for (const [re, to] of EN_RULES) out = out.replace(re, () => to);
    return out.replace(/(returns from [a-h][1-8]) on /g, '$1 to ');
}
const uiAlert = m => alert(tr(m));
const uiConfirm = m => confirm(tr(m));

// Перевод экрана: текстовые узлы и подсказки (title, placeholder); оригинал хранится, чтобы вернуть русский
const TR_ATTRS = ['title', 'placeholder'];
const noTr = n => { const el = n.nodeType === 1 ? n : n.parentElement; return !!(el && el.closest && el.closest('[data-notr]')); };

function translateNode(n) {
    if (LANG !== 'en' || !n) return;
    if (n.nodeType === 3) {
        if (CYR.test(n.nodeValue) && !noTr(n)) {
            const t = tr(n.nodeValue);
            if (t !== n.nodeValue) { n.__ru = n.nodeValue; n.nodeValue = t; }     // без лишних записей, иначе наблюдатель зациклится
        }
    } else if (n.nodeType === 1) {
        if (n.tagName === 'SCRIPT' || n.tagName === 'STYLE') return;
        TR_ATTRS.forEach(a => {
            const v = n.getAttribute(a);
            if (v && CYR.test(v) && !noTr(n)) {
                const t = tr(v);
                if (t !== v) { (n.__ruAttr = n.__ruAttr || {})[a] = v; n.setAttribute(a, t); }
            }
        });
        n.childNodes.forEach(translateNode);
    }
}

function restoreNode(n) {
    if (!n) return;
    if (n.nodeType === 3) { if (n.__ru !== undefined) { n.nodeValue = n.__ru; delete n.__ru; } }
    else if (n.nodeType === 1) {
        if (n.__ruAttr) { Object.keys(n.__ruAttr).forEach(a => n.setAttribute(a, n.__ruAttr[a])); delete n.__ruAttr; }
        n.childNodes.forEach(restoreNode);
    }
}

function setLang(l) {
    restoreNode(document.body);
    LANG = l;
    try { localStorage.setItem('spellschess-lang', l); } catch (e) { /* без сохранения */ }
    if (document.documentElement) document.documentElement.lang = l;
    ['langLobby', 'langSetup', 'btnLang'].forEach(id => { $('#' + id).textContent = l === 'ru' ? '🌐 English' : '🌐 Русский'; });
    buildSetup();
    renderThemePicker();
    renderChat();
    if (G) render();
    translateNode(document.body);
}

if (typeof MutationObserver !== 'undefined' && document.body) {
    new MutationObserver(recs => {
        if (LANG !== 'en') return;
        recs.forEach(r => {
            if (r.type === 'childList') r.addedNodes.forEach(translateNode);
            else if (r.type === 'characterData') translateNode(r.target);
            else if (r.type === 'attributes') translateNode(r.target);
        });
    }).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: TR_ATTRS });
}
['langLobby', 'langSetup', 'btnLang'].forEach(id => $('#' + id).addEventListener('click', () => setLang(LANG === 'ru' ? 'en' : 'ru')));

/* ---------- Свои модельки фигур: положите картинки в папку pieces (wK.png, bQ.png и т. д.) ---------- */
(function detectPieceImages() {
    if (typeof Image === 'undefined') return;
    const names = ['wK', 'wQ', 'wR', 'wB', 'wN', 'wP', 'bK', 'bQ', 'bR', 'bB', 'bN', 'bP'];
    const exts = ['png', 'svg', 'webp'];
    const tryExt = i => {
        if (i >= exts.length) return;
        const im = new Image();
        im.onload = () => {
            names.forEach(n => document.documentElement.style.setProperty('--img-' + n, `url("pieces/${n}.${exts[i]}")`));
            if (document.body) document.body.classList.add('img-pieces');
        };
        im.onerror = () => tryExt(i + 1);
        im.src = 'pieces/wK.' + exts[i];
    };
    tryExt(0);
})();

['donateLobby', 'donateSetup', 'donateGame'].forEach(id => {
    const a = $('#' + id);
    if (DONATE_URL && !window.Capacitor) { a.href = DONATE_URL; a.classList.remove('hidden'); }
});
applyTheme(themeId);
buildSetup();
setLang(LANG);

// ===== Мобильная версия: строка статуса, нижняя панель и выезжающее окно «меню / журнал / чат» =====
(function () {
    const g = id => document.getElementById(id);
    const app = g('app'), st = g('status'), hi = g('hint'), ms = g('mStatus'), mh = g('mHint');
    const end = g('btnEnd'), mEnd = g('mEnd'), chat = g('chat');
    if (!app || !ms || !mh || !mEnd) return;

    const sync = () => {
        if (ms.textContent !== st.textContent) ms.textContent = st.textContent;
        const cls = 'm-status ' + st.className.replace('status', '').trim();
        if (ms.className !== cls) ms.className = cls;
        if (mh.textContent !== hi.textContent) mh.textContent = hi.textContent;
        mEnd.classList.toggle('hidden', end.classList.contains('hidden'));
        mEnd.disabled = end.disabled;
    };
    const obs = new MutationObserver(sync);
    [st, hi].forEach(n => obs.observe(n, { childList: true, characterData: true, subtree: true, attributes: true }));
    obs.observe(end, { attributes: true });
    sync();

    const openSheet = target => {
        app.classList.add('sheet-open');
        setChatUnread(false);
        setTimeout(() => { if (target) target.scrollIntoView({ block: 'start' }); else g('mClose').scrollIntoView({ block: 'start' }); }, 30);
    };
    const closeSheet = () => app.classList.remove('sheet-open');

    g('mMenu').addEventListener('click', () => openSheet(null));
    g('mClose').addEventListener('click', closeSheet);
    mEnd.addEventListener('click', () => end.click());
    app.addEventListener('click', e => { if (e.target === app) closeSheet(); });      // тап по затемнению закрывает окно
    ['btnDraw', 'btnResign', 'btnNew'].forEach(id => g(id).addEventListener('click', closeSheet));
})();


// ===== Кнопки только для тех героев, что есть в партии =====
function syncHeroButtons() {
    if (!G) return;
    const has = h => G.hero.w === h || G.hero.b === h;
    const set = (id, on) => { const b = document.getElementById(id); if (b) b.classList.toggle('nohero', !on); };
    set('btnGhost', has('hypnotist'));                      // иллюзии Экстрасенса
    set('btnTraps', has('hunter') || has('jester'));        // капканы Охотника и скрытое Шута (кожура, колпак, предатель)
    set('btnInvis', has('samurai') || has('hypnotist') || has('magician'));    // невидимки Самурая и Экстрасенса («Ход — это ложь»)
    // «Завершить ход» (Архитектор) скрывает updateEndBtn()
}

// ===== Перемотка ходов: только просмотр, партию не меняет =====
const REW = { snaps: [], idx: -1, g: null, lastLen: -1, broken: false, fresh: false, undo: false };   // idx -1: показываем текущую позицию

function takeSnap() {
    if (!G || REW.broken || !G.log) return;
    if (REW.g !== G || G.log.length < REW.lastLen) {
        let keep = -1;
        if (REW.undo && REW.snaps.length) {            // Мисклик: оставляем всё до отменённых ходов
            const want = G.log.length - 1;             // длина журнала до записи про мисклик
            for (let i = REW.snaps.length - 1; i >= 0; i--) if (REW.snaps[i].log.length === want) { keep = i; break; }
        }
        if (keep >= 0) { REW.snaps.length = keep + 1; REW.lastLen = REW.snaps[keep].log.length; REW.idx = Math.min(REW.idx, keep); REW.g = G; }
        else { REW.snaps = []; REW.idx = -1; REW.g = G; REW.lastLen = -1; REW.fresh = false; }   // новая партия
        REW.undo = false;
    }
    if (G.log.length === REW.lastLen) return;
    if (REPLAY_REC) REPLAY.pfx.push(...(G.fx || []).map(x => ({ ...x })));      // эффекты на клетках (взрыв, воскрешение, дым) для повтора
    try {
        const { log, ...rest } = G;
        const snap = structuredClone(rest);
        snap.log = log.slice();
        snap.sel = null; snap.moves = []; snap.mode = null; snap.fx = [];
        if (REPLAY_REC) { snap.rfx = REPLAY.pfx; REPLAY.pfx = []; }
        REW.snaps.push(snap);
        REW.lastLen = G.log.length;
        if (REW.idx >= 0) REW.fresh = true;      // пока смотрели прошлое, в партии появился новый ход
    } catch (e) { REW.broken = true; }
}

const viewWrap = fn => function (...a) {
    const snap = REW.idx >= 0 ? REW.snaps[REW.idx] : null;
    if (snap && G !== snap) {
        const real = G;
        G = snap;
        try { return fn.apply(this, a); } finally { G = real; }
    }
    return fn.apply(this, a);
};
const _render = render;
render = function () {
    if (G) takeSnap();      // снимки делаем всегда, в том числе пока смотрим прошлое
    viewWrap(_render).call(this);
    syncHeroButtons();
    updateRewindUI();
};
renderPanels = viewWrap(renderPanels);
renderBoard = viewWrap(renderBoard);
renderStatus = viewWrap(renderStatus);
renderLog = viewWrap(renderLog);
updateEndBtn = viewWrap(updateEndBtn);

function rewindTo(i) {
    const last = REW.snaps.length - 1;
    if (last < 0) return;
    const cur = REW.idx < 0 ? last : REW.idx;
    i = Math.max(0, Math.min(last, i));
    const ev = REPLAY.on && i === cur + 1 && REPLAY.ev[i] ? REPLAY.ev[i] : null;      // шаг на один ход вперёд: показываем звуки и анимации этого хода
    let tomato = null;
    if (ev) {
        const tgt = i === last ? G : REW.snaps[i];
        tgt.fx = (REW.snaps[i].rfx || []).map(x => ({ ...x }));
        ev.forEach(e => {
            if (e.k === 'anim') { if (ANIM.board) ANIMQ.push({ ...e.a }); }
            else if (e.k === 'tomato' && ANIM.board) tomato = tomatoPrepare(e.col, e.en, e.key);
        });
    }
    REW.idx = i === last ? -1 : i;
    if (REW.idx < 0) REW.fresh = false;
    render();
    if (ev) {
        ev.forEach(e => {
            if (e.k === 'sfx') { if (e.delay > 0) setTimeout(() => sfx(e.key), e.delay * 1000); else sfx(e.key); }
            else if (e.k === 'banner') abilityBanner(e.key);
        });
        if (tomato) tomatoFly(tomato);
    }
}
function rewindStep(d) {
    const last = REW.snaps.length - 1;
    const cur = REW.idx < 0 ? last : REW.idx;
    rewindTo(cur + d);
}

function updateRewindUI() {
    const box = document.getElementById('rewind');
    if (!box) return;
    const n = REW.snaps.length, last = n - 1;
    const cur = REW.idx < 0 ? last : REW.idx;
    box.classList.toggle('hidden', REW.broken || n < 2);
    document.getElementById('app').classList.toggle('viewing', REW.idx >= 0);
    document.getElementById('rwLabel').textContent = Math.max(cur, 0) + ' / ' + Math.max(last, 0);
    document.getElementById('rwStart').disabled = cur <= 0;
    document.getElementById('rwPrev').disabled = cur <= 0;
    document.getElementById('rwNext').disabled = cur >= last;
    document.getElementById('rwEnd').disabled = cur >= last;
    document.getElementById('rwEnd').classList.toggle('glow', REW.fresh && REW.idx >= 0);      // подсветка кнопки «к текущей позиции»
}

document.getElementById('rwStart').addEventListener('click', () => rewindTo(0));
document.getElementById('rwPrev').addEventListener('click', () => rewindStep(-1));
document.getElementById('rwNext').addEventListener('click', () => rewindStep(1));
document.getElementById('rwEnd').addEventListener('click', () => rewindTo(REW.snaps.length - 1));

// Пока смотрим прошлое, доска и панели героев не реагируют на нажатия
document.addEventListener('click', e => {
    if (REW.idx >= 0 && e.target.closest && e.target.closest('#board, .panel, #btnEnd, #mEnd')) { e.stopPropagation(); e.preventDefault(); }
}, true);
document.addEventListener('keydown', e => {
    if (!G || document.getElementById('app').classList.contains('hidden')) return;
    const typing = e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA');
    if (typing) return;
    if (e.key === 'ArrowLeft') { rewindStep(-1); e.preventDefault(); }
    else if (e.key === 'ArrowRight') { rewindStep(1); e.preventDefault(); }
    else if (e.key === 'Escape' && REW.idx >= 0) { e.stopImmediatePropagation(); rewindTo(REW.snaps.length - 1); }
}, true);


// ===== Телефон: описание способности по долгому нажатию =====
(function () {
    let timer = null, tip = null, suppress = false, hideT = null;
    const hideTip = () => { if (tip) { tip.remove(); tip = null; } clearTimeout(hideT); };
    const showTip = btn => {
        hideTip();
        const nameEl = btn.querySelector('.ab-name');
        const title = btn.getAttribute('title') || '';
        const head = nameEl ? nameEl.textContent.trim() : '';
        tip = document.createElement('div');
        tip.className = 'ab-tip';
        tip.setAttribute('data-notr', '');
        tip.innerHTML = (head ? '<b></b><br>' : '') + '<span></span>';
        if (head) tip.querySelector('b').textContent = head;
        tip.querySelector('span').textContent = title;
        document.body.appendChild(tip);
        hideT = setTimeout(hideTip, 6000);
    };
    const buttonAt = (panel, x, y) => Array.from(panel.querySelectorAll('.ab, .passive')).find(b => {
        const r = b.getBoundingClientRect();
        return x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
    });
    document.addEventListener('pointerdown', e => {
        if (e.pointerType !== 'touch') return;
        const panel = e.target.closest && e.target.closest('.panel');
        if (!tip || !(e.target.closest && e.target.closest('.ab-tip'))) hideTip();
        if (!panel) return;
        const btn = buttonAt(panel, e.clientX, e.clientY);
        if (!btn) return;
        clearTimeout(timer);
        timer = setTimeout(() => { suppress = true; showTip(btn); if (navigator.vibrate) navigator.vibrate(15); }, 450);
    });
    const cancel = () => clearTimeout(timer);
    document.addEventListener('pointerup', () => { cancel(); if (suppress) setTimeout(() => { suppress = false; }, 400); });
    document.addEventListener('pointercancel', cancel);
    document.addEventListener('pointermove', e => { if (e.pointerType === 'touch' && Math.abs(e.movementX) + Math.abs(e.movementY) > 6) cancel(); });
    // после долгого нажатия отпускание не должно срабатывать как обычный клик
    document.addEventListener('click', e => { if (suppress) { e.stopPropagation(); e.preventDefault(); suppress = false; } }, true);
    document.addEventListener('contextmenu', e => { if (e.target.closest && e.target.closest('.panel')) e.preventDefault(); });
})();


// ===== Подтверждение хода кнопкой (включается кнопкой ✅, по умолчанию выключено) =====
const CONFIRM = { on: false, pend: null };
try { CONFIRM.on = localStorage.getItem('sc_confirm') === '1'; } catch (e) { }

// Клик по клетке «завершает» действие: ход фигуры или выбор цели способности (выбор своей фигуры для способности не в счёт)
function needsConfirm(r, c) {
    if (!G || G.over) return false;
    if (G.pairStep) return !!(G.sel && G.moves.some(m => m.tr === r && m.tc === c));
    if (G.mode) {
        const m = G.mode;
        if (STAGED.includes(m.type) && m.stage === 'piece') return false;
        return !!(m.cells && m.cells.some(x => x[0] === r && x[1] === c));
    }
    return !!(G.sel && G.moves.some(m => m.tr === r && m.tc === c));
}

function updateConfirmUI() {
    if (CONFIRM.pend && (!G || G.over || REW.idx >= 0 || !needsConfirm(CONFIRM.pend.r, CONFIRM.pend.c))) CONFIRM.pend = null;
    const btn = document.getElementById('btnConfirm');
    if (btn) { btn.classList.toggle('off', !CONFIRM.on); btn.title = CONFIRM.on ? 'Подтверждение хода кнопкой: включено' : 'Подтверждение хода кнопкой: выключено'; }
    const app = document.getElementById('app');
    app.classList.toggle('confirm-pending', !!CONFIRM.pend);
    document.querySelectorAll('#board .cell.pending').forEach(el => el.classList.remove('pending'));
    if (CONFIRM.pend) {
        const el = document.querySelector(`#board .cell[data-r="${CONFIRM.pend.r}"][data-c="${CONFIRM.pend.c}"]`);
        if (el) el.classList.add('pending');
    }
}
const _renderConfirm = render;
render = function () { _renderConfirm.call(this); updateConfirmUI(); };

document.getElementById('btnConfirm').addEventListener('click', () => {
    CONFIRM.on = !CONFIRM.on;
    try { localStorage.setItem('sc_confirm', CONFIRM.on ? '1' : '0'); } catch (e) { }
    CONFIRM.pend = null;
    if (G) render(); else updateConfirmUI();
});
document.getElementById('cfOk').addEventListener('click', () => {
    const p = CONFIRM.pend;
    CONFIRM.pend = null;
    if (!p || !G || G.over) { if (G) render(); return; }
    netDo({ t: 'cell', r: p.r, c: p.c });
});
document.getElementById('cfNo').addEventListener('click', () => { CONFIRM.pend = null; render(); });
document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && CONFIRM.pend) { e.stopImmediatePropagation(); CONFIRM.pend = null; render(); }
}, true);
updateConfirmUI();


// =====================================================================
//  ВРЕМЯ ПАРТИИ: выбор в лобби, шахматные часы, подбор соперника по времени
// =====================================================================
const L = (ru, en) => (LANG === 'en' ? en : ru);
const clampInt = (v, a, b) => Math.max(a, Math.min(b, parseInt(v, 10) || 0));
const MODES = { bullet: { name: 'Пуля', en: 'Bullet', min: 1 }, blitz: { name: 'Блиц', en: 'Blitz', min: 5 }, rapid: { name: 'Рапид', en: 'Rapid', min: 15 }, classic: { name: 'Классика', en: 'Classical', min: 30 } };
const modeName = k => (MODES[k] ? L(MODES[k].name, MODES[k].en) : '');
const PRESETS = { bullet: { min: 1, inc: 0 }, blitz: { min: 5, inc: 0 }, rapid: { min: 15, inc: 0 }, classic: { min: 30, inc: 0 }, none: { min: 0, inc: 0 } };
// Время всегда считается на каждого игрока: min — минут (0 = без лимита), inc — секунд добавки после каждого хода
const ROOMSET = { min: 15, inc: 0 }, LOCALSET = { min: 15, inc: 0 };
try { const s = JSON.parse(localStorage.getItem('sc_times') || '{}'); if (s.room) Object.assign(ROOMSET, s.room); if (s.local) Object.assign(LOCALSET, s.local); } catch (e) { }
[ROOMSET, LOCALSET].forEach(o => { o.min = clampInt(o.min, 0, 180); o.inc = clampInt(o.inc, 0, 60); });
const saveTimes = () => { try { localStorage.setItem('sc_times', JSON.stringify({ room: ROOMSET, local: LOCALSET })); } catch (e) { } };
const fmtTime = (min, inc) => (min > 0
    ? L(`${min} мин на игрока`, `${min} min per player`) + (inc > 0 ? L(` + ${inc} с за ход`, ` + ${inc} s per move`) : '')
    : L('без лимита времени', 'no time limit'));

// Выбор времени: пять готовых вариантов или своё время и добавка за ход
function timePicker(root, st, onChange) {
    const mk = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt !== undefined) e.textContent = txt; return e; };
    root.textContent = '';
    root.classList.add('time-pick');
    const seg = mk('div', 'tp-presets'), btns = {};
    [['bullet', 'Пуля', '1 мин'], ['blitz', 'Блиц', '5 мин'], ['rapid', 'Рапид', '15 мин'], ['classic', 'Классика', '30 мин'], ['none', 'Без времени', '']].forEach(([k, n, sub]) => {
        const b = mk('button'); b.dataset.p = k; b.append(mk('b', '', n)); if (sub) b.append(mk('span', '', sub));
        seg.appendChild(b); btns[k] = b;
    });
    const row = mk('div', 'tp-custom');
    const l1 = mk('label', '', 'Минут на игрока'), i1 = mk('input');
    const l2 = mk('label', '', 'Добавка за ход, сек'), i2 = mk('input');
    [[i1, 180], [i2, 60]].forEach(([inp, mx]) => { inp.type = 'number'; inp.min = 0; inp.max = mx; inp.inputMode = 'numeric'; });
    l1.appendChild(i1); l2.appendChild(i2); row.append(l1, l2);
    const sum = mk('div', 'tp-sum'); sum.setAttribute('data-notr', '');
    root.append(seg, row, sum);
    const paintLight = () => {
        const p = Object.keys(PRESETS).find(k => PRESETS[k].min === st.min && PRESETS[k].inc === st.inc);
        Object.entries(btns).forEach(([k, b]) => b.classList.toggle('on', k === p));
        sum.textContent = fmtTime(st.min, st.inc);
    };
    const paint = () => { i1.value = st.min; i2.value = st.inc; paintLight(); };
    seg.addEventListener('click', e => {
        const b = e.target.closest('button');
        if (!b) return;
        st.min = PRESETS[b.dataset.p].min; st.inc = PRESETS[b.dataset.p].inc;
        paint(); onChange();
    });
    i1.addEventListener('input', () => { st.min = clampInt(i1.value, 0, 180); paintLight(); onChange(); });
    i2.addEventListener('input', () => { st.inc = clampInt(i2.value, 0, 60); paintLight(); onChange(); });
    paint();
}

// После соединения хозяин сообщает гостю время, добавку и режим партии
function tcOnOpen() {
    if (NET.host) netSend({ t: 'tc', min: NET.tc || 0, inc: NET.inc || 0, rated: !!NET.rated, mode: NET.mode || null, fischer: !!NET.fischer, custom: !!NET.custom, hostColor: NET.hostColor || 'w' });
    updateSetupTc();
}
const _netRecvTc = netRecv;
netRecv = function (m) {
    if (m && m.t === 'tc') { if (!NET.host) { NET.tc = m.min | 0; NET.inc = m.inc | 0; NET.rated = !!m.rated; NET.mode = MODES[m.mode] ? m.mode : null; NET.fischer = !!m.fischer; NET.custom = !!m.custom; NET.hostColor = m.hostColor === 'b' ? 'b' : 'w'; NET.me = other(NET.hostColor); if (!$('#setup').classList.contains('hidden')) buildSetup(); updateSetupTc(); } return; }
    if (m && m.t === 'flag') { if (m.side === other(NET.me)) flagSide(m.side, !!m.opening); return; }
    _netRecvTc(m);
};
function curTc() {
    if (NET.on) return typeof NET.tc === 'number' ? NET.tc : null;     // null: ещё не определено
    return LOCALSET.min;
}
const curInc = () => (NET.on ? (NET.inc | 0) : LOCALSET.inc);
function updateSetupTc() {
    const el = document.getElementById('setupTc');
    if (!el) return;
    const tc = curTc();
    el.classList.remove('hidden');
    let txt = tc === null ? L('Время партии: определится, когда подключится соперник.', 'Game time: will be set when your opponent connects.') : L('Время партии: ', 'Game time: ') + fmtTime(tc, curInc()) + '.';
    if (NET.on && tc !== null) txt += NET.rated ? L(` Рейтинговая партия, режим «${modeName(NET.mode)}».`, ` Rated game, ${modeName(NET.mode)} mode.`) : L(' Дружеская партия: рейтинг не меняется.', ' Friendly game: rating does not change.');
    if (NET.on && NET.custom) txt += L(' Режим: своя доска из редактора.', ' Mode: custom board from the editor.');
    if (NET.on && NET.fischer) txt += L(' Режим: шахматы Фишера (случайная расстановка).', ' Mode: Fischer random chess.');
    el.textContent = txt;
}
const _openSetupTc = openSetup;
openSetup = function () { _openSetupTc.apply(this, arguments); updateSetupTc(); };

// ---------- часы ----------
let CLOCK = { on: false, left: { w: 0, b: 0 }, last: 0, grace: 0 };
function fmtClock(sec) {
    sec = Math.max(0, Math.ceil(sec));
    const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), x = sec % 60;
    const p = n => String(n).padStart(2, '0');
    return h ? `${h}:${p(m)}:${p(x)}` : `${p(m)}:${p(x)}`;
}
// Пока игрок не сделал свой первый ход, идёт особое время на первый ход, а основные часы стоят
function inOpening(side) {
    return !!(CLOCK.on && CLOCK.open && G && !G.over && !((G.done && G.done[side]) > 0));
}
const clockText = side => (inOpening(side) ? '♟ ' + fmtClock(CLOCK.open[side]) : fmtClock(CLOCK.left[side]));
function clockHTML(col) {
    if (!CLOCK.on) return '';
    return `<span class="clock${inOpening(col) ? ' opening' : ''}" data-clock="${col}" data-notr>${clockText(col)}</span>`;
}
function initClock() {
    const tc = curTc() || 0;
    CLOCK = { on: tc > 0, left: { w: tc * 60, b: tc * 60 }, open: { w: CONFIG.openingSeconds, b: CONFIG.openingSeconds }, inc: curInc(), prev: G ? G.turn : 'w', last: performance.now(), grace: 0 };
    if (G) render();
}
const _startGameTc = startGame;
startGame = function () { _startGameTc.apply(this, arguments); initClock(); };

function flagSide(side, opening) {
    if (!G || G.over) return;
    if (opening) {      // не успел сделать первый ход за особое время
        CLOCK.open[side] = 0;
        G.over = { winner: other(side), title: 'Нет первого хода', text: L(`${colorName(side)} не сделали первый ход за ${Math.round(CONFIG.openingSeconds / 60 * 10) / 10} мин. ${colorName(other(side))} побеждают.`, `${colorName(side)} did not make the first move in time. ${colorName(other(side))} win.`) };
        render(); showGameOver();
        return;
    }
    CLOCK.left[side] = 0;
    G.over = { winner: other(side), title: 'Время вышло', text: `${colorName(other(side))} побеждают по времени.` };
    render(); showGameOver();
}
function paintClocks() {
    document.querySelectorAll('.clock[data-clock]').forEach(el => {
        const side = el.dataset.clock, op = inOpening(side), t = op ? CLOCK.open[side] : CLOCK.left[side];
        const txt = clockText(side);
        if (el.textContent !== txt) el.textContent = txt;
        el.classList.toggle('running', !!G && !G.over && G.turn === side);
        el.classList.toggle('opening', op);
        el.classList.toggle('low', t < 30);
    });
}
setInterval(() => {
    const now = performance.now();
    const dt = (now - CLOCK.last) / 1000;
    CLOCK.last = now;
    if (!CLOCK.on || !G || G.over || document.getElementById('app').classList.contains('hidden')) return;
    const side = G.turn;
    const opening = inOpening(side);                      // до первого хода идёт особое время, основное стоит
    const pool = opening ? CLOCK.open : CLOCK.left;
    pool[side] = Math.max(0, pool[side] - dt);
    paintClocks();
    if (pool[side] > 0) { CLOCK.grace = 0; return; }
    if (!NET.on || side === NET.me) {                     // своё время вышло: сообщаем сопернику
        if (NET.on) netSend({ t: 'flag', side, opening });
        flagSide(side, opening);
    } else {                                              // время соперника: ждём его сообщения, иначе засчитываем сами
        if (!CLOCK.grace) CLOCK.grace = now + 5000;
        else if (now > CLOCK.grace) flagSide(side, opening);
    }
}, 200);
const _renderClock = render;
render = function () {
    // когда ход перешёл к другому, предыдущему игроку добавляется время за ход
    if (CLOCK.on && G && !G.over && CLOCK.prev && G.turn !== CLOCK.prev && G.done && G.done[CLOCK.prev] > 1) CLOCK.left[CLOCK.prev] += CLOCK.inc || 0;      // за первый ход добавки нет: он шёл на особом времени
    if (G && CLOCK.on) CLOCK.prev = G.turn;
    _renderClock.call(this); paintClocks();
    saveResume();      // запоминаем онлайн-партию, чтобы в неё можно было вернуться после закрытия приложения
};


// ===== Чат: на компьютере под правой рамкой героя, на телефоне внутри выезжающего меню =====
(function () {
    const g = id => document.getElementById(id);
    const chat = g('chat'), app = g('app'), log = g('log');
    if (!chat || !app || !log) return;
    const side = app.querySelector('.side-col'), logTitle = log.previousElementSibling;
    const mq = window.matchMedia('(max-width: 760px), (any-pointer: coarse) and (min-width: 761px) and (max-width: 1400px) and (min-height: 480px)');
    const place = () => {
        if (mq.matches) { if (chat.parentElement !== side) side.insertBefore(chat, logTitle); }
        else if (chat.parentElement !== app) app.insertBefore(chat, side);
    };
    if (mq.addEventListener) mq.addEventListener('change', place); else mq.addListener(place);
    place();
})();


// Внутри подбора целей и выбора клетки вражеская невидимка выглядит как свободная клетка
const _abilityCellsV = abilityCells;
abilityCells = function (key, col, t, first) {
    const prev = VIEWER;
    VIEWER = col;
    try { return JESTER_KEYS.includes(key) ? jesterCells(key, col) : MAGI_KEYS.includes(key) ? magiCells(key, col, first) : ENG_KEYS.includes(key) ? engCells(key, col) : _abilityCellsV.apply(this, arguments); } finally { VIEWER = prev; }
};
const _onModeCellV = onModeCell;
onModeCell = function () {
    const prev = VIEWER;
    VIEWER = G.turn;
    try { return _onModeCellV.apply(this, arguments); } finally { VIEWER = prev; }
};




// =====================================================================
//  ШУТ
// =====================================================================
// Предательством можно пользоваться только после определённого хода врага
const betrayReady = col => !!(G && G.done && (G.done[other(col)] || 0) >= CONFIG.betrayAfter);
const jesterSees = side => !!side && showTraps && (NET.on ? side === NET.me : side === G.turn);      // скрытые вещи Шута видит только он

// Фигура ходит как своя за Шута: на время подсчёта ходов её цвет подменяется
const asJester = (p, col, fn) => fn();      // предательской фигурой ходить нельзя: её можно только перевести на свою сторону
const _selectableMovesJ = selectableMoves;
selectableMoves = function (r, c) { return asJester(G.board[r][c], G.turn, () => _selectableMovesJ(r, c)); };

// Фигура в колпаке не рубит и не создаёт шахи
const _pseudoMovesJ = pseudoMoves;
pseudoMoves = function (b, r, c) {
    const mv = _pseudoMovesJ(b, r, c), p = b[r][c];
    if (!p || !(p.cap > 0)) return mv;
    return mv.filter(m => {
        if (m.ep) return false;
        const t = b[m.tr][m.tc];
        if (t && t.c !== p.c && !t.ghost) return false;
        return !givesCheck(b, m);
    });
};

const JESTER_KEYS = ['blunder', 'banana', 'jaws', 'tomato', 'pretense'];
function jesterCells(key, col) {
    const b = G.board, cells = [];
    if (key === 'blunder') {
        if (!safeAfter(cloneBoard(b), col)) return cells;      // под шахом колпак не спасает короля, а ход тратит: нельзя
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
            const p = b[r][c];
            if (p && p.c === col && !p.ghost && !kSafe(p) && p.t !== 'j' && !(p.cap > 0)) cells.push([r, c]);
        }
    } else if (key === 'banana') {
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
            if (isFreeCell(r, c)) cells.push([r, c]);      // чужая скрытая кожура или капкан не мешают: новая ляжет поверх
        }
    } else if (key === 'jaws') {
        ownThree(col).forEach(r => {
            for (let c = 0; c < N; c++) {
                if (!isEmptyCell(r, c)) continue;
                const nb = cloneBoard(b);
                nb[r][c] = { ...mk('j', col), moved: true };
                bananaSlideOnBoard(nb, r, c, col);      // поставленные на свою кожуру челюсти съедут: учитываем это
                if (safeAfter(nb, col)) cells.push([r, c]);
            }
        });
    } else if (key === 'tomato') {
        if (HEROES[G.hero[other(col)]].abilities.some(k => !(G.disabled[other(col)][k] > 0))) cells.push([0, 0]);      // цель выбирается кнопкой в панели врага
    } else if (key === 'pretense') {
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
            const p = b[r][c];
            if (p && p.c !== col && !p.ghost && !p.invis && (p.t === 'b' || p.t === 'n') && !p.betray) cells.push([r, c]);
        }
    }
    return cells;
}

// Предательство: можно ли сейчас перевести фигуру на свою сторону (ход потратится, король не должен остаться под шахом)
function canBetray(col, r, c) {
    if (G.over || G.bonus || G.pairStep || G.pendingPromo || (G.forced && G.forced.length) || G.archUsed) return false;
    const p = G.board[r][c];
    if (!p || p.betray !== col || p.c === col || !betrayReady(col)) return false;
    const nb = cloneBoard(G.board);
    nb[r][c].c = col;
    return safeAfter(nb, col);
}

function doBetray(r, c) {
    const col = G.turn, p = G.board[r][c];
    if (!p || !canBetray(col, r, c)) { G.sel = null; G.moves = []; render(); return; }
    p.c = col; delete p.betray;
    G.fx.push({ r, c, type: 'hypno' });
    sfx('hypno');
    G.last = null; G.sel = null; G.moves = []; G.mode = null; G.ep = null;
    addLog(col, `🃏 Предательство: ${pieceSym(p)} ${sqName(r, c)} переходит на сторону Шута`);
    endTurn();
}

// Притворство: перед первым ходом Шут обязан тайно выбрать предателя
function startPretenseIfNeeded(c) {
    if (!G.pretense || G.pretense[c] !== 'pending') return;
    const cells = jesterCells('pretense', c);
    if (!cells.length) { G.pretense[c] = 'done'; return; }
    G.sel = null; G.moves = [];
    G.mode = { type: 'pretense', locked: true, cells };
}

function placeBanana(from, to) {
    const col = G.turn, cdKey = (G.mode && G.mode.via) || 'banana';
    G.bananas = G.bananas.filter(x => !(x.r === from[0] && x.c === from[1]));      // одинаковые ловушки: действует последняя
    G.bananas.push({ r: from[0], c: from[1], owner: col, dir: [to[0] - from[0], to[1] - from[1]] });
    G.cd[col][cdKey] = cdOf(col, cdKey);
    G.lastAb[col] = 'banana';
    abilityBanner('banana');
    sfx('trap');
    addLog(col, '🍌 Банановая кожура: ловушка установлена (место скрыто, ход не потрачен)');
    G.mode = null; G.sel = null; G.moves = [];
    render();
}

// Фигура (не король), вставшая на кожуру, съезжает на соседнюю клетку и кожура исчезает
function sweepBananas() {
    if (!G.bananas || !G.bananas.length) return;
    G.bananas = G.bananas.filter(bn => {
        const p = G.board[bn.r][bn.c];
        if (!p || kSafe(p) || p.ghost) return true;
        if (p.warded > 0) {      // Очищение: фигура давит кожуру без последствий
            addLog('n', p.invis ? '✴ Невидимая фигура под Очищением уничтожает банановую кожуру' : `✴ ${pieceSym(p)} под Очищением уничтожает кожуру на ${sqName(bn.r, bn.c)}`);
            return false;
        }
        const tr = bn.r + bn.dir[0], tc = bn.c + bn.dir[1];
        const sq = sqName(bn.r, bn.c);
        sfx('trap');
        if (inb(tr, tc) && !G.board[tr][tc]) {
            G.board[tr][tc] = p;
            G.board[bn.r][bn.c] = null;
            p.prev = [bn.r, bn.c];
            if (!p.invis) G.fx.push({ r: tr, c: tc, type: 'land' });
            queueAnim({ k: 'slide', from: [bn.r, bn.c], to: [tr, tc] });
            addLog('n', p.invis ? '🍌 Невидимая фигура поскальзывается на банановой кожуре' : `🍌 ${pieceSym(p)} поскальзывается на кожуре на ${sq} и съезжает на ${sqName(tr, tc)}`);
        } else {
            addLog('n', p.invis ? '🍌 Невидимая фигура наступает на банановую кожуру' : `🍌 ${pieceSym(p)} наступает на кожуру на ${sq}, но съехать некуда`);
        }
        return false;
    });
}

// =====================================================================
//  ФОКУСНИК
// =====================================================================
const MAGI_KEYS = ['fog', 'hatch', 'hocus', 'assistant'];
let HATCH_TAIL = null;      // что делать после выбора люка (продолжение хода), в состояние партии не входит
const MAGI_MEMO = new Map();      // проверка «можно ли применить» тяжёлая, поэтому запоминаем её на время одного состояния партии

const fogAt = (r, c) => !!(G && G.fogs && G.fogs.some(f => f.r === r && f.c === c));

// Раскрыть записи журнала, скрытые за невидимой фигурой
function unhideLogs(p) {
    if (p.uid) G.log.forEach(e => { if (e.hid === p.uid) { e.text = e.real + ' 🥷'; delete e.hid; delete e.real; } });
}

// Фигуры (не короли) в дыму невидимы, вышедшие из дыма становятся видимыми
function syncFog() {
    if (!G || !G.board) return;
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
        const p = G.board[r][c];
        if (!p) continue;
        const inFog = fogAt(r, c) && !kSafe(p) && !p.ghost && p.t !== 'j' && !p.lie;
        if (inFog) {
            if (!p.invis && !p.fogSeen) { p.invis = true; p.fog = true; }
        } else if (p.fog) {
            delete p.fog; delete p.fogSeen;
            if (p.invis) { delete p.invis; unhideLogs(p); }
        }
    }
}

// Сценический туман: клетка и всё в двух шагах (по вертикали и горизонтали)
function doFog(r, c) {
    const col = G.turn, A = ABILITIES.fog;
    if (!G.fogs) G.fogs = [];
    for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {      // квадрат 3×3 вокруг выбранной клетки
        const rr = r + dr, cc = c + dc;
        if (!inb(rr, cc)) continue;
        const old = G.fogs.find(f => f.r === rr && f.c === cc);
        if (old) { old.left = CONFIG.fogTurns + 1; old.owner = col; }
        else G.fogs.push({ r: rr, c: cc, owner: col, left: CONFIG.fogTurns + 1 });
        G.fx.push({ r: rr, c: cc, type: 'smoke' });
    }
    sfx('poof');
    G.last = null;
    syncFog();
    finishAbility('fog', `${A.icon} ${A.name}: дым над ${sqName(r, c)} и рядом (ход не потрачен)`);
}

// Потайной люк: плитка на свободной клетке
function doHatch(r, c, first) {
    const A = ABILITIES.hatch;
    if (!G.hatches) G.hatches = [];
    if (!G.hatchUsed) G.hatchUsed = { w: false, b: false };
    G.hatchUsed[G.turn] = true;
    const cells = first ? [first, [r, c]] : [[r, c]];
    cells.forEach(([hr, hc]) => { G.hatches.push({ r: hr, c: hc, owner: G.turn }); G.fx.push({ r: hr, c: hc, type: 'cast' }); });
    sfx('trap');
    finishAbility('hatch', first ? `${A.icon} ${A.name}: два люка, ${sqName(first[0], first[1])} и ${sqName(r, c)}` : `${A.icon} ${A.name}: люк на ${sqName(r, c)}`);
}

// Свободные люки, из которых может вылезти фигура, упавшая в люк на (r, c)
// Люк открыт для выхода: пусто; там иллюзия (она не мешает и рассеется); или вражеская невидимка (игрок о ней не знает: выбор раскроет её и отменит ход)
function hatchCellOpen(r, c, p, b) {
    const q = (b || G.board)[r][c];
    if (!q) return true;
    if (q === p) return false;
    if (q.ghost) return true;      // иллюзия не мешает вылезти на её клетку (она рассеется), даже если выходит другая иллюзия
    return !!(p && q.invis && q.c !== p.c);
}
const hatchExits = (r, c, p) => (G.hatches || []).filter(h => !(h.r === r && h.c === c) && hatchCellOpen(h.r, h.c, p));
let HATCH_UNDO = null;      // состояние до хода на люк (нужно, если выбранный выход окажется занят невидимкой и ход придётся отменить)
let HATCH_PLAN = null;      // выбор выходов при создании иллюзии и в «Ходе — это ложь»

// Фигура провалилась в люк from и вылезла из люка to
// Эффекты появления, исчезновения и перемещения не выдают фигуру в тумане или невидимку (онлайн: их видит только владелец фигуры)
const FOG_HIDDEN_FX = ['ghost', 'poof', 'hypno', 'revive', 'raise', 'trap', 'shield', 'cast'];
function fxHidden(x, r, c) {
    if (!NET.on || !FOG_HIDDEN_FX.includes(x.type)) return false;
    const q = G.board[r][c];
    if (q && q.invis && !q.ghost) return q.c !== NET.me;
    return fogAt(r, c) && !(q && q.c === NET.me);
}

function hatchFall(from, to, pp) {
    const p = pp || G.board[from[0]][from[1]];      // pp: фигуру уже сняли с доски (две фигуры проваливаются одновременно)
    if (!p) return;
    if (!pp) G.board[from[0]][from[1]] = null;
    G.board[to[0]][to[1]] = p;
    p.prev = [from[0], from[1]];
    G.fx.push({ r: to[0], c: to[1], type: 'ghost' });
    const hid = p.invis || fogAt(from[0], from[1]) || fogAt(to[0], to[1]);
    if (!hid) { queueAnim({ k: 'hatch', from: [from[0], from[1]], to: [to[0], to[1]] }); sfx('poof'); }      // в тумане ни анимации, ни звука
    G.last = null;
    if (hid) addLog('n', '🪵 Фигура проваливается в потайной люк и вылезает из другого');
    else addLog('n', `🪵 ${pieceSym(p)} проваливается в люк на ${sqName(from[0], from[1])} и вылезает на ${sqName(to[0], to[1])}`);
    syncFog();
}

// Фигура (или иллюзия) приходит из люка from в люк to: иллюзия на выходе рассеивается, невидимка раскрывается, а ход отменяется. true: ход отменён
function hatchGo(from, to) {
    const p = G.board[from[0]][from[1]], q = G.board[to[0]][to[1]];
    if (q && q.invis && !q.ghost && p && q.c !== p.c) { hatchBump(to); return true; }
    if (q && q.ghost && p && q !== p) vanishGhost(to[0], to[1], 'из люка вылезла фигура');
    hatchFall(from, to);
    return false;
}
// Из люка попытались выйти на место невидимой фигуры: она раскрывается, ход не тратится (состояние возвращается к началу хода)
function hatchBump(to) {
    HATCH_TAIL = null;
    const u = HATCH_UNDO; HATCH_UNDO = null;
    if (u) {
        const log = G.log, n = u.logLen;
        Object.keys(G).forEach(k => { if (k !== 'log') delete G[k]; });
        Object.assign(G, structuredClone(u.state));
        G.log = log; G.log.length = n;
    }
    G.mode = null;
    revealPiece(to[0], to[1], 'из люка хотели выйти на её клетку');
    G.moves = G.sel ? selectableMoves(G.sel.r, G.sel.c) : [];
    render();
}

// После хода: фигура, вставшая на люк, проваливается (если есть свободный люк). true: ход продолжится после выбора игрока
function hatchTrigger(p, mv, cont) {
    if (!G.hatches || !G.hatches.length) return false;
    const q = G.board[mv.tr][mv.tc];
    if (q !== p || kSafe(p) || p.warded > 0) return false;
    if (!G.hatches.some(h => h.r === mv.tr && h.c === mv.tc)) return false;
    let exits = hatchExits(mv.tr, mv.tc, p);
    if (!exits.length) return false;
    const hx = hatchSafeExits(G.board, mv.tr, mv.tc, p.c);      // выйти можно только туда, где король в безопасности (если такие есть)
    if (hx && hx.safe.length) exits = hx.safe;
    if (exits.length === 1) return hatchGo([mv.tr, mv.tc], [exits[0].r, exits[0].c]);
    HATCH_TAIL = cont;
    G.sel = null; G.moves = [];
    G.mode = { type: 'hatchexit', locked: true, from: [mv.tr, mv.tc], cells: exits.map(h => [h.r, h.c]) };
    render();
    return true;
}

// Иллюзия и «Ход — это ложь» ходят двумя фигурами сразу: если обе (или одна) встали на люки, выходы выбираются ДО того, как что-то сдвинулось
// items: [{ p, to: [r, c], label }], первым идёт оригинал. cont(chosen): chosen[i] = [r, c] выхода для i-й фигуры или undefined. onBump(r, c): выбран выход с невидимкой
function hatchPlan(items, cont, onBump) {
    const falls = [];
    items.forEach((it, i) => {
        if (G.hatches && G.hatches.length && !kSafe(it.p) && !(it.p.warded > 0) && G.hatches.some(h => h.r === it.to[0] && h.c === it.to[1])) falls.push(i);
    });
    HATCH_PLAN = { items, falls, chosen: [], idx: 0, cont, onBump, via: G.mode && G.mode.via, from: items[0].from };      // via: способность вызвана через Зеркало
    hatchPlanNext();
}
function hatchPlanNext() {
    const P = HATCH_PLAN;
    while (P.idx < P.falls.length) {
        const i = P.falls[P.idx], it = P.items[i];
        // Оригинал и копия проваливаются одновременно: люк, куда упала другая фигура, освобождается, поэтому выйти можно и из него.
        // Нельзя выйти только из своего люка, из люка, где фигура остаётся стоять (король), и из уже выбранного
        const stay = P.items.filter((x, j) => !P.falls.includes(j)).map(x => x.to);
        const exits = (G.hatches || []).filter(h => {
            if (h.r === it.to[0] && h.c === it.to[1]) return false;
            if (stay.some(l => l[0] === h.r && l[1] === h.c)) return false;
            if (P.chosen.some(ch => ch && ch[0] === h.r && ch[1] === h.c)) return false;
            if (P.falls.some(j => P.items[j].to[0] === h.r && P.items[j].to[1] === h.c)) return true;      // туда упала другая фигура: люк освободится
            if (P.from && h.r === P.from[0] && h.c === P.from[1]) return true;      // клетку, с которой фигура ушла, она освободила
            return hatchCellOpen(h.r, h.c, it.p);
        });
        if (!exits.length) { P.idx++; continue; }
        if (exits.length === 1) { hatchPlanTake(exits[0].r, exits[0].c); if (!HATCH_PLAN) return; continue; }
        G.mode = { type: 'hatchexit', locked: true, plan: true, via: P.via, label: it.label, cells: exits.map(h => [h.r, h.c]) };
        render();
        return;
    }
    HATCH_PLAN = null;
    G.mode = P.via ? { type: 'hatchplan', via: P.via } : null;
    P.cont(P.chosen);
}
function hatchPlanTake(r, c) {
    const P = HATCH_PLAN, i = P.falls[P.idx];
    const q = G.board[r][c];
    if (q && q.invis && !q.ghost && q.c !== P.items[i].p.c) { HATCH_PLAN = null; G.mode = null; P.onBump(r, c); return; }
    P.chosen[i] = [r, c];
    P.idx++;
}
function hatchPlanPick(r, c) {
    hatchPlanTake(r, c);
    if (HATCH_PLAN) hatchPlanNext();
}
// Применяет выбранные выходы: фигура и иллюзия уже стоят на люках и появляются из выбранных одновременно
function hatchApplyPlan(items, chosen) {
    const mv = [];
    items.forEach((it, i) => {
        if (!chosen[i]) return;
        const at = pieceObjAt(it.p);
        if (at) mv.push({ p: it.p, from: at, to: chosen[i] });
    });
    if (!mv.length) return;
    mv.forEach(m => { G.board[m.from[0]][m.from[1]] = null; });      // сначала обе фигуры исчезают в люках...
    if (mv.length > 1 && rnd() < 0.5) mv.reverse();                  // ...порядок записи в журнале случайный: по нему не вычислить, где иллюзия
    mv.forEach(m => {                                                // ...и потом появляются из выбранных люков одновременно
        const q = G.board[m.to[0]][m.to[1]];
        if (q && q.ghost && q !== m.p) vanishGhost(m.to[0], m.to[1], 'из люка вылезла фигура');
        hatchFall(m.from, m.to, m.p);
    });
}
// Выбранный выход оказался занят невидимкой: способность отменяется целиком, ничего не потрачено
function hatchPlanBump(r, c) {
    G.mode = null; G.sel = null; G.moves = [];
    revealPiece(r, c, 'из люка хотели выйти на её клетку');
    render();
}

// Фокус-Покус: две фигуры в квадрате 5×5 вокруг первой
const hocusPiece = (p, col) => !!p && !kSafe(p) && !p.soul && !p.sup && !p.lie && !hiddenFor(p, col);
function hocusOk(a, b2, col) {
    const b = G.board, p = b[a[0]][a[1]], q = b[b2[0]][b2[1]];
    if (!hocusPiece(p, col) || !hocusPiece(q, col)) return false;
    if (p.ghost || q.ghost) {      // иллюзия среди целей: она просто рассеется
        const nb0 = cloneBoard(b);
        [a, b2].forEach(([rr, cc]) => { if (nb0[rr][cc].ghost) nb0[rr][cc] = null; });
        return safeAfter(nb0, col);
    }
    const promoRow = c => (c === 'w' ? 0 : N - 1);
    if ((p.t === 'p' && b2[0] === promoRow(p.c)) || (q.t === 'p' && a[0] === promoRow(q.c))) return false;      // пешка не должна оказаться на горизонтали превращения (на своей первой можно)
    const nb = cloneBoard(b);
    dropGhostOn(nb, a[0], a[1]); dropGhostOn(nb, b2[0], b2[1]);      // двойники этих фигур рассеются
    const pa = { ...nb[a[0]][a[1]] }, pb = { ...nb[b2[0]][b2[1]] };
    nb[a[0]][a[1]] = pb;
    nb[b2[0]][b2[1]] = pa;
    return safeAfter(nb, col);
}
function hocusCells(col, a, first) {
    const out = [];
    for (let dr = -2; dr <= 2; dr++) for (let dc = -2; dc <= 2; dc++) {
        const r = a[0] + dr, c = a[1] + dc;
        if (!inb(r, c) || (!dr && !dc)) continue;
        if (hocusOk(a, [r, c], col)) { out.push([r, c]); if (first) return out; }
    }
    return out;
}

// Ассистент: фигура может стать зайцем, если после этого ваш король в безопасности
function assistantOk(r, c, col) {
    const b = G.board, p = b[r][c];
    if (!p || kSafe(p) || p.t === 'j' || p.t === 'h' || p.t === 'u' || p.soul || p.sup || p.lie || hiddenFor(p, col)) return false;
    if (p.c !== col && !p.ghost && magicProof(b, r, c)) return false;
    const nb = cloneBoard(b);
    dropGhostOn(nb, r, c);
    nb[r][c] = { ...nb[r][c], t: 'h', x: undefined };
    return safeAfter(nb, col);
}

function magiCells(key, col, first) {
    const b = G.board;
    if (first && (key === 'hocus' || key === 'assistant')) {
        const mkey = [key, col, G.turnNo || 0, G.log.length, (G.fogs || []).length, (G.hatches || []).length, G.over ? 1 : 0].join('|');
        if (MAGI_MEMO.has(mkey)) return MAGI_MEMO.get(mkey);
        if (MAGI_MEMO.size > 40) MAGI_MEMO.clear();
        const res = magiCellsRaw(key, col, true);
        MAGI_MEMO.set(mkey, res);
        return res;
    }
    return magiCellsRaw(key, col, first);
}
function magiCellsRaw(key, col, first) {
    const b = G.board, cells = [];
    if (key === 'fog') {
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) cells.push([r, c]);
    } else if (key === 'hatch') {
        if (!safeAfter(cloneBoard(b), col)) return cells;      // под шахом плитка не спасает короля, а ход тратит
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (isFreeCell(r, c)) { cells.push([r, c]); if (first && cells.length >= 2) return cells; }
    } else if (key === 'hocus') {
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
            if (!hocusPiece(b[r][c], col)) continue;
            if (hocusCells(col, [r, c], true).length) { cells.push([r, c]); if (first) return cells; }
        }
    } else if (key === 'assistant') {
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (assistantOk(r, c, col)) { cells.push([r, c]); if (first) return cells; }
    }
    return cells;
}

function doHocus(a, b2) {
    const A = ABILITIES.hocus, bd = G.board;
    const p = bd[a[0]][a[1]], q = bd[b2[0]][b2[1]];
    const ghosts = [a, b2].filter(([r, c]) => bd[r][c].ghost);
    if (ghosts.length) {      // вражеская иллюзия выглядела настоящей фигурой
        ghosts.forEach(([r, c]) => vanishGhost(r, c, 'это была иллюзия', true));
        finishAbility('hocus', `${A.icon} ${A.name}: среди целей была иллюзия, она рассеялась`);
        return;
    }
    bd[a[0]][a[1]] = q;
    bd[b2[0]][b2[1]] = p;
    p.moved = true; q.moved = true;
    delete p.fogSeen; delete q.fogSeen;
    const hid = p.invis || q.invis || fogAt(a[0], a[1]) || fogAt(b2[0], b2[1]);      // невидимая фигура или туман: ни анимации, ни звука
    if (!hid) {
        G.fx.push({ r: a[0], c: a[1], type: 'poof' }, { r: b2[0], c: b2[1], type: 'poof' });
        queueAnim({ k: 'swap', a: [a[0], a[1]], b: [b2[0], b2[1]] });
        sfx('illusion');
    }
    G.last = null;
    finishAbility('hocus', hid
        ? `${A.icon} ${A.name}: две фигуры поменялись местами (в тумане)`
        : `${A.icon} ${A.name}: ${pieceSym(p)} ${sqName(a[0], a[1])} ⇄ ${pieceSym(q)} ${sqName(b2[0], b2[1])}`);
}

function doAssistant(r, c) {
    const col = G.turn, A = ABILITIES.assistant, p = G.board[r][c];
    if (p.ghost) {
        vanishGhost(r, c, 'это была иллюзия', true);
        finishAbility('assistant', `${A.icon} ${A.name} по ${sqName(r, c)}: цель оказалась иллюзией и рассеялась`);
        return;
    }
    const orig = pieceSym(p), origT = p.t;
    p.hare = { t: p.t, x: p.x ? [...p.x] : undefined, left: (p.orig || p.c) === col ? CONFIG.hareTurns + 1 : CONFIG.hareTurns, by: col };      // у своей фигуры +1: срок уменьшится ещё в конце хода, когда способность применена
    p.t = 'h'; delete p.x;
    const hid = p.invis || fogAt(r, c);      // невидимая фигура или туман: ни анимации, ни звука
    if (!hid) {
        if (ANIM.board) queueAnim({ k: 'hat', at: [r, c], piece: { c: p.c, t: origT } });
        else sfx('illusion');
    }
    G.last = null;
    finishAbility('assistant', hid
        ? `${A.icon} ${A.name}: фигура в тумане превращается в зайца на ${CONFIG.hareTurns} ${plural(CONFIG.hareTurns)}`
        : `${A.icon} ${A.name}: ${orig} на ${sqName(r, c)} превращается в зайца на ${CONFIG.hareTurns} ${plural(CONFIG.hareTurns)}`);
}

// Заяц снова становится фигурой
function revertHare(r, c, p) {
    const h = p.hare;
    delete p.hare;
    p.t = h.t;
    if (h.x && h.x.length) p.x = h.x;
    let note = '';
    if (p.t === 'p' && (r === 0 || r === N - 1)) { p.t = 'q'; note = ' (пешка дошла до края и стала ферзём)'; }
    G.fx.push({ r, c, type: 'poof' });
    addLog('n', p.invis ? '🐇 Заяц снова становится фигурой' : `🐇 Заяц на ${sqName(r, c)} снова становится фигурой: ${pieceSym(p)}${note}`);
}

/* =====================================================================
   ИНЖЕНЕР
   Сборка робота и сборка турели: планшет с зелёным ретро-экраном. Каждый нажатый квадрат идёт как обычное действие игрока (t: 'eng'),
   поэтому онлайн и в повторах всё считается одинаково. Робот: фигура типа 'x', её правила лежат в p.rob.
   Турель: неподвижная фигура типа 'u', её радиус лежит в p.tur.
   Направления в планшете считаются от своей стороны (вверх = вперёд), в p.rob и p.tur лежат готовые смещения [строка, столбец].
   ===================================================================== */
const ENG_KEYS = ['assemble', 'charger', 'turret', 'reprogram'];
const ENG_TAB_MODES = ['assemble', 'turret', 'reprogram'];
const ENG_DUMMY = { kind: 'boot', walk: [[1, 0]], atk: [], wr: 1, ar: 1 };      // пробный робот для проверки клеток появления
const ENG_MAX_JUMP = 8;                                                          // сколько клеток крыла можно выбрать всего

const engHas = (arr, d) => arr.some(x => x[0] === d[0] && x[1] === d[1]);
const engToggle = (arr, d) => { const k = arr.findIndex(x => x[0] === d[0] && x[1] === d[1]); if (k >= 0) arr.splice(k, 1); else arr.push([d[0], d[1]]); };
const engSign = col => (col === 'w' ? 1 : -1);
const engAbs = (col, d) => [d[0] * engSign(col), d[1] * engSign(col)];       // из «вид игрока» в доску (и обратно: знак тот же)
const turRows = col => (col === 'w' ? [N - 1, N - 2, N - 3] : [0, 1, 2]);

// Клетки: появление робота (две первые горизонтали), появление турели (три первые), плитка-зарядка (любая свободная),
// перепрограммирование (свои роботы и турели). Король остаётся в безопасности
function engCells(key, col) {
    const b = G.board, cells = [];
    if (key === 'assemble' || key === 'turret') {
        const rows = key === 'turret' ? turRows(col) : (col === 'w' ? [N - 1, N - 2] : [0, 1]);
        const sample = key === 'turret' ? { ...mk('u', col), moved: true, tur: { kind: 'instant', cells: [[1, 0]], seen: [] } } : { ...mk('x', col), moved: true, rob: ENG_DUMMY };
        rows.forEach(r => {
            if (r < 0 || r >= N) return;
            for (let c = 0; c < N; c++) {
                if (wallAt(r, c) || (G.board[r][c] && !(VIEWER && hiddenFor(G.board[r][c], VIEWER)))) continue;      // роботу и турели нужна клетка без фигур, плитки не мешают
                const nb = cloneBoard(b);
                nb[r][c] = { ...sample };
                if (safeAfter(nb, col)) cells.push([r, c]);
            }
        });
    } else if (key === 'charger') {
        if (!safeAfter(cloneBoard(b), col)) return cells;      // под шахом плитка не спасает короля, а ход тратит
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (isFreeCell(r, c)) cells.push([r, c]);
    } else if (key === 'reprogram') {
        for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
            const p = b[r][c];
            if (p && p.c === col && !p.orig && !p.ghost && ((p.t === 'x' && p.rob) || (p.t === 'u' && p.tur))) cells.push([r, c]);
        }
    }
    return cells;
}

// Направления ходьбы и атаки совпали: дальность усиливается у обеих сразу
const engSame = m => m.walk.length > 0 && m.walk.length === m.atk.length && m.walk.every(d => engHas(m.atk, d));
// Сколько перезарядки добавляет собранное к базовой
function engCost(m) {
    if (m.type === 'turret') return 2 * m.tc.length;
    if (m.kind === 'wing') return 3 + 2 * m.ja.length + m.jw.length;
    if (m.kind !== 'boot') return 0;
    return m.walk.length + m.atk.length + (m.wr - 1) * (engSame(m) ? 2 : 1);
}
// Готовые правила робота. Белые: вверх по экрану = к чёрным (строка −1); чёрные: наоборот
function engBuild(m, col) {
    const abs = d => engAbs(col, d);
    if (m.kind === 'wing') return { kind: 'wing', ja: m.ja.map(abs), jw: m.jw.map(abs) };
    return { kind: 'boot', walk: m.walk.map(abs), atk: m.atk.map(abs), wr: m.wr, ar: engSame(m) ? m.wr : 1 };
}

function engFinish(m) {
    if (m.rb) { if (engReproRobState(m).changed) doReproRobot(m); return; }      // перепрограммирование робота: ничего не менялось, планшет остаётся
    m.stage = 'spawn'; m.sel = null;
    m.cells = abilityCells(m.type, G.turn);
    if (!m.cells.length) { cancelAbilityMode(); return; }
    G.sel = null;
    render();
}

// Перепрограммирование турели: что изменилось и сколько это стоит
function engReproState(m) {
    const rp = m.rp;
    if (!rp) return { cost: 0, changed: false, valid: false };
    const key = d => d[0] + ',' + d[1];
    const diff = (a, b) => a.filter(d => !b.some(x => key(x) === key(d))).length;      // клеток в a, которых нет в b
    return { cost: 2 * diff(rp.tc, rp.old), changed: diff(rp.tc, rp.old) + diff(rp.old, rp.tc) > 0, valid: rp.tc.length >= 1 };
}
// Перепрограммирование робота: заново проходится сборка, прежний выбор остаётся. Платятся только новые клетки и направления
function engReproRobState(m) {
    const o = m.old, key = d => d[0] + ',' + d[1];
    const diff = (a, b) => a.filter(d => !b.some(x => key(x) === key(d))).length;
    const same = (a, b) => diff(a, b) === 0 && diff(b, a) === 0;
    if (m.kind === 'wing') return { cost: 2 * diff(m.ja, o.ja) + diff(m.jw, o.jw), changed: !(same(m.ja, o.ja) && same(m.jw, o.jw)) };
    return { cost: diff(m.walk, o.walk) + diff(m.atk, o.atk) + Math.max(0, m.wr - o.wr) * (engSame(m) ? 2 : 1), changed: !(same(m.walk, o.walk) && same(m.atk, o.atk) && m.wr === o.wr) };
}

function engInput(msg) {
    const m = G.mode;
    if (!m || !ENG_TAB_MODES.includes(m.type) || m.stage === 'spawn' || m.stage === 'piece' || !msg) return;
    const a = msg.a, v = msg.v, st = m.stage;
    const go = ns => { m.hist.push(st); m.stage = ns; m.sel = null; };
    const okD = (d, lim) => Array.isArray(d) && d.length === 2 && d.every(x => Number.isInteger(x) && Math.abs(x) <= lim) && (d[0] || d[1]);
    if (a === 'close') { cancelAbilityMode(); return; }
    if (a === 'back') {
        if (!m.hist.length) { cancelAbilityMode(); return; }
        m.stage = m.hist.pop(); m.sel = null;
        if (m.stage === 'piece') { m.cells = abilityCells('reprogram', G.turn); m.rp = null; m.target = null; m.rb = false; m.hist = []; }
        render();
        return;
    }
    if (m.type === 'turret') {
        if (a === 'pick') {
            if (st === 'tkind' && (v === 'instant' || v === 'artillery')) m.sel = v; else return;
        } else if (a === 'jump') {
            if (st !== 'tcells' || !okD(v, m.tk === 'instant' ? 1 : 2)) return;
            engToggle(m.tc, v);
        } else if (a === 'next') {
            if (st === 'tkind') { if (m.sel !== 'instant' && m.sel !== 'artillery') return; if (m.tk !== m.sel) m.tc = []; m.tk = m.sel; go('tcells'); }
            else if (st === 'tcells') { if (!m.tc.length) return; engFinish(m); return; }
            else return;
        } else return;
        render();
        return;
    }
    if (m.type === 'reprogram' && !m.rb) {      // перепрограммирование турели: радиус заново
        const rp = m.rp;
        if (st !== 'rp' || !rp) return;
        if (a === 'jump') {
            if (!okD(v, rp.tk === 'instant' ? 1 : 2)) return;
            engToggle(rp.tc, v);
        } else if (a === 'next') {
            const s2 = engReproState(m);
            if (!s2.valid || !s2.changed) return;
            doReprogram(m);
            return;
        } else return;
        render();
        return;
    }
    // ---- сборка робота ----
    if (a === 'pick') {
        if ((st === 'kind' && (v === 'boot' || v === 'wing')) || ((st === 'after' || st === 'wingafter') && (v === 'boot' || v === 'x'))) {
            if (st === 'wingafter' && v === 'boot' && m.ja.length >= ENG_MAX_JUMP) return;
            m.sel = v;
        } else return;
    } else if (a === 'dir') {
        if (!okD(v, 1)) return;
        if (st === 'walk') engToggle(m.walk, v); else if (st === 'atk') engToggle(m.atk, v); else return;
    } else if (a === 'jump') {
        if (!okD(v, 2)) return;
        if (st === 'wing') {
            const had = engHas(m.ja, v), inJw = engHas(m.jw, v);
            if (!had && !inJw && m.ja.length + m.jw.length >= ENG_MAX_JUMP) return;
            if (!had && inJw) { const k2 = m.jw.findIndex(x => x[0] === v[0] && x[1] === v[1]); m.jw.splice(k2, 1); }      // клетка из «только ходьба» становится «ходьба и атака»
            engToggle(m.ja, v);
        } else if (st === 'wingplus') {
            if (engHas(m.ja, v)) return;
            if (!engHas(m.jw, v) && m.ja.length + m.jw.length >= ENG_MAX_JUMP) return;
            engToggle(m.jw, v);
        } else return;
    } else if (a === 'range') {
        if (st !== 'range' || (v !== 1 && v !== -1)) return;
        m.wr = Math.max(1, Math.min(N - 1, m.wr + v));
    } else if (a === 'x2') {
        if (st !== 'walk' || !m.walk.length) return;
        m.atk = m.walk.map(d => [d[0], d[1]]);
        go('after');
    } else if (a === 'next') {
        if (st === 'kind') { if (m.sel !== 'boot' && m.sel !== 'wing') return; m.kind = m.sel; go(m.sel === 'boot' ? 'walk' : 'wing'); }
        else if (st === 'walk') go('atk');
        else if (st === 'atk') { if (m.walk.length + m.atk.length < 1) return; go('after'); }
        else if (st === 'after') {
            if (m.sel === 'boot') go('range');
            else if (m.sel === 'x') { if (!m.rb) m.wr = 1; engFinish(m); return; }
            else return;
        }
        else if (st === 'range') { engFinish(m); return; }
        else if (st === 'wing') { if (!m.ja.length) return; go('wingafter'); }
        else if (st === 'wingafter') {
            if (m.sel === 'boot') { if (m.ja.length >= ENG_MAX_JUMP) return; go('wingplus'); }
            else if (m.sel === 'x') { engFinish(m); return; }
            else return;
        }
        else if (st === 'wingplus') { engFinish(m); return; }
    } else return;
    render();
}

// Робот появляется на выбранной клетке; перезарядка = 3 + цена улучшений
function doAssemble(r, c) {
    const m = G.mode, col = G.turn, A = ABILITIES.assemble;
    const rob = engBuild(m, col);
    if (guardPlacement(col, r, c, nb => { nb[r][c] = { ...mk('x', col), moved: true, rob }; })) { cancelAbilityMode(); return; }
    const cost = engCost(m);
    G.board[r][c] = { ...mk('x', col), moved: true, rob };
    if (!G.engCost) G.engCost = { w: 0, b: 0, wt: 0, bt: 0, wr: 0, br: 0 };
    G.engCost[col] = cost;
    G.last = null;
    G.fx.push({ r, c, type: 'revive' });
    sfx('revive');
    finishAbility('assemble', `${A.icon} ${A.name}: робот (${rob.kind === 'wing' ? 'крыло' : 'сапог'}) появляется на ${sqName(r, c)}`);
}

// Турель появляется на выбранной клетке; перезарядка = 5 + 2 за каждую клетку радиуса
function doTurret(r, c) {
    const m = G.mode, col = G.turn, A = ABILITIES.turret;
    const tur = { kind: m.tk, cells: m.tc.map(d => engAbs(col, d)), seen: [] };
    if (guardPlacement(col, r, c, nb => { nb[r][c] = { ...mk('u', col), moved: true, tur }; })) { cancelAbilityMode(); return; }
    G.board[r][c] = { ...mk('u', col), moved: true, tur };
    turretSeen(r, c);
    if (!G.engCost) G.engCost = { w: 0, b: 0, wt: 0, bt: 0, wr: 0, br: 0 };
    G.engCost[col + 't'] = engCost(m);
    G.last = null;
    G.fx.push({ r, c, type: 'revive' });
    sfx('revive');
    finishAbility('turret', `${A.icon} ${A.name}: ${tur.kind === 'instant' ? 'мгновенная стрельба' : 'дальняя артиллерия'} на ${sqName(r, c)}`);
}

// Перепрограммирование турели: радиус заново, тратит ход
function doReprogram(m) {
    const col = G.turn, A = ABILITIES.reprogram;
    const [r, c] = m.target, p = G.board[r][c], s2 = engReproState(m), rp = m.rp;
    if (!p || !p.tur) { cancelAbilityMode(); return; }
    p.tur.cells = rp.tc.map(d => engAbs(col, d));
    turretSeen(r, c);
    if (!G.engCost) G.engCost = { w: 0, b: 0, wt: 0, bt: 0, wr: 0, br: 0 };
    G.engCost[col + 'r'] = s2.cost;
    G.fx.push({ r, c, type: 'cast' });
    sfx('cast');
    finishAbility('reprogram', `${A.icon} ${A.name}: турель на ${sqName(r, c)} перенастроена`);
}
// Перепрограммирование робота: правила собираются заново по тому же планшету, тратит ход
function doReproRobot(m) {
    const col = G.turn, A = ABILITIES.reprogram;
    const [r, c] = m.target, p = G.board[r][c], s2 = engReproRobState(m);
    if (!p || p.t !== 'x') { cancelAbilityMode(); return; }
    p.rob = engBuild(m, col);
    if (!G.engCost) G.engCost = { w: 0, b: 0, wt: 0, bt: 0, wr: 0, br: 0 };
    G.engCost[col + 'r'] = s2.cost;
    G.fx.push({ r, c, type: 'cast' });
    sfx('cast');
    finishAbility('reprogram', `${A.icon} ${A.name}: робот на ${sqName(r, c)} перестроен`);
}

// Плитка-зарядка
function doCharger(r, c) {
    const col = G.turn, A = ABILITIES.charger;
    if (!G.chargers) G.chargers = [];
    G.chargers.push({ r, c, owner: col });
    G.fx.push({ r, c, type: 'cast' });
    sfx('trap');
    G.last = null;
    finishAbility('charger', `${A.icon} ${A.name}: плитка на ${sqName(r, c)}`);
}

// Бесплатный ход: у робота есть заряд (он получает его, вставая на плитку-зарядку) и он ещё не ходил бесплатно в этот ход
const chargeFree = (p, r, c) => !!p && p.t === 'x' && p.chg > 0 && !p.ghost && p.c === G.turn && !p.orig && !(G.chargeUsed || []).includes(p.uid);
// Ход ставит шах сопернику? Бесплатным ходом шаховать нельзя: такой ход идёт как обычный и заряд не тратит
function engGivesCheck(mv) {
    const nb = cloneBoard(G.board);
    applyMove(nb, mv, 'q');
    return kingAttacked(nb, other(G.turn));
}

/* ---------- Турель: радиус, срабатывание, выстрел ---------- */
const turKey = (q, rr, cc) => (q.ghost ? 'g' + (q.pair || 0) + ':' + rr + ',' + cc : String(uidOf(q)));
// Враги, которые стоят в радиусе турели сейчас
function turEnemies(r, c, p) {
    const out = [];
    p.tur.cells.forEach(([dr, dc]) => {
        const rr = r + dr, cc = c + dc;
        if (rr < 0 || rr >= N || cc < 0 || cc >= N) return;
        const q = G.board[rr][cc];
        if (q && q.c !== p.c) out.push([rr, cc, q]);
    });
    return out;
}
// Запомнить, кто уже стоит в радиусе (они не считаются «новым появлением»)
function turretSeen(r, c) {
    const p = G.board[r][c];
    if (p && p.tur) p.tur.seen = turEnemies(r, c, p).map(([rr, cc, q]) => turKey(q, rr, cc));
}
// В конце каждого хода: мгновенная турель уничтожает врагов в радиусе, артиллерия готовит выстрел на новых
// Пуля турели: летит по прямой от турели к цели. Возвращает время полёта в секундах
function queueBullet(from, to, piece, dur) {
    if (!ANIM.board) return 0;
    const d = dur || clampN(0.22 + Math.hypot(from[0] - to[0], from[1] - to[1]) * 0.05, 0.28, 0.6);
    const pc = piece && !piece.invis && !piece.ghost ? { c: piece.c, t: piece.t } : null;
    queueAnim({ k: 'flight', kind: 'bullet', from: [from[0], from[1]], to: [to[0], to[1]], dur: d, piece: pc });
    return d;
}
function turretScan() {
    const list = [];
    G.board.forEach((row, r) => row.forEach((p, c) => { if (p && p.t === 'u' && p.tur && !p.ghost) list.push([r, c, p]); }));
    let died = false;
    list.forEach(([r, c, p]) => {
        if (G.board[r][c] !== p) return;      // турель уже уничтожена в этот же момент
        const near = turEnemies(r, c, p), here = sqName(r, c);
        if (p.tur.kind === 'instant') {
            const seenI = new Set(p.tur.seen || []);      // кто уже стоял в радиусе при появлении (или перенастройке) турели, того она не трогает
            near.forEach(([rr, cc, q]) => {
                if (G.board[rr][cc] !== q) return;
                if (seenI.has(turKey(q, rr, cc))) return;
                const sq = sqName(rr, cc);
                if (magicProof(G.board, rr, cc, p.c)) { if (!q.invis) addLog('n', `⚡ Турель на ${here} целится в ${sq}: цель неуязвима для магии`); return; }
                const fd = queueBullet([r, c], [rr, cc], q);      // пуля вылетает из турели
                G.fx.push({ r, c, type: 'zap' });                 // вспышка выстрела
                G.fx.push({ r: rr, c: cc, type: 'arrowhit', delay: fd });
                sfxLater('arrow', fd);
                if (q.ghost) { vanishGhost(rr, cc, 'выстрел турели'); addLog('n', `⚡ Турель на ${here} стреляет в ${sq}`); died = true; return; }
                const dp = guardSwap(rr, cc) || q;
                G.board[rr][cc] = null;
                toGrave(dp);
                addLog('n', `⚡ Турель на ${here} мгновенно уничтожает ${pieceSym(dp)} на ${sq}`);
                died = true;
            });
            turretSeen(r, c);
        } else {
            const seen = new Set(p.tur.seen || []);
            near.forEach(([rr, cc, q]) => {
                if (seen.has(turKey(q, rr, cc))) return;
                if (G.fire.some(f => f.kind === 'shell' && f.r === rr && f.c === cc && f.owner === p.c)) return;
                G.fire.push({ r: rr, c: cc, owner: p.c, kind: 'shell', wait: 1, tu: uidOf(p) });
                addLog('n', `🎯 Турель на ${here} наводится на ${sqName(rr, cc)}: выстрел через ход`);
            });
            turretSeen(r, c);
        }
    });
    if (died) { soulSync(); checkIllusions(); }
}

/* ---------- Эврика: один раз за бой аннулировать перезарядку способности ---------- */
const EUREKA_CD = 20;      // перезарядка самой Эврики: 20 своих ходов (тикает вместе с перезарядкой способностей)
const eurekaLeft = col => (G && G.eurekaCd && G.eurekaCd[col] > 0) ? G.eurekaCd[col] : 0;
const eurekaReady = col => !!G && G.hero[col] === 'engineer' && eurekaLeft(col) <= 0;
function doEureka(k) {
    const col = G.turn;
    if (G.over || G.mode || G.bonus || !eurekaReady(col) || !HEROES[G.hero[col]].abilities.includes(k) || !(G.cd[col][k] > 0)) return;
    G.cd[col][k] = 0;
    if (!G.eurekaCd) G.eurekaCd = { w: 0, b: 0 };
    G.eurekaCd[col] = EUREKA_CD;
    G.fx.push({ r: -1, c: -1, type: 'cast' });
    sfx('shield');
    addLog(col, `💡 Эврика! Перезарядка способности «${ABILITIES[k].name}» аннулирована`);
    render();
}
// Подтверждение: два зелёных квадрата, галочка и крестик
function eurekaAsk(k) {
    if (!G || !eurekaReady(G.turn) || !isActor()) return;
    let dlg = document.getElementById('eurekaDlg');
    if (!dlg) {
        dlg = document.createElement('div');
        dlg.id = 'eurekaDlg';
        dlg.className = 'eng-ov hidden';
        dlg.addEventListener('click', e => {
            const b = e.target.closest('[data-eu]');
            if (!b) return;
            dlg.classList.add('hidden');
            if (b.dataset.eu === 'yes') { SFX.engOk(); netDo({ t: 'eureka', k: dlg.dataset.k }); }
            else SFX.engBack();
        });
        document.body.appendChild(dlg);
    }
    dlg.dataset.k = k;
    dlg.innerHTML = `<div class="eng-tab"><div class="eng-screen"><div class="eng-inner">
        <div class="eng-head"><span class="eng-title">💡 ЭВРИКА</span></div>
        <div class="eng-body"><div class="eng-note ask">ОБНУЛИТЬ ПЕРЕЗАРЯДКУ СПОСОБНОСТИ «<b class="eu-name">${ABILITIES[k].name}</b>»? ПОСЛЕ ЭТОГО ЭВРИКА ПЕРЕЗАРЯЖАЕТСЯ 20 ХОДОВ.</div>
        <div class="eng-row"><button class="eng-sq big" data-eu="yes">${engPix('check')}<i>ДА</i></button><button class="eng-sq big" data-eu="no">${engPix('cross')}<i>НЕТ</i></button></div></div>
      </div></div></div>`;
    dlg.classList.remove('hidden');
    SFX.engSwitch();
}

/* ---------- Подсветка клеток робота и турели при нажатии ---------- */
let ENG_INFO = null;      // { r, c, stamp }: осмотр чужой (или любой, когда не ваш ход) фигуры-робота или турели
const engSpecial = p => !!p && !p.ghost && ((p.t === 'x' && p.rob) || (p.t === 'u' && p.tur));
// Клетки робота: m: ходит, c: рубит (ходьба и рубка по направлениям считаются с учётом стоящих на пути фигур)
function robMap(b, r, c) {
    const p = b[r][c], rb = robNow(p), out = new Map();
    const add = (rr, cc, k) => { const key = rr + ',' + cc; const o = out.get(key) || { m: false, c: false }; o[k] = true; out.set(key, o); };
    if (rb.kind === 'wing') {
        (rb.ja || []).forEach(([dr, dc]) => { const tc = wcol(p, c + dc); if (r + dr >= 0 && r + dr < N && tc >= 0) { add(r + dr, tc, 'm'); add(r + dr, tc, 'c'); } });
        (rb.jw || []).forEach(([dr, dc]) => { const tc = wcol(p, c + dc); if (r + dr >= 0 && r + dr < N && tc >= 0) add(r + dr, tc, 'm'); });
        return out;
    }
    (rb.walk || []).forEach(([dr, dc]) => rayWalk(b, r, c, dr, dc, (rr, cc, t, path) => {
        if (path.length >= rb.wr) return true;
        if (t && !t.ghost) return true;
        add(rr, cc, 'm');
        return false;
    }));
    (rb.atk || []).forEach(([dr, dc]) => rayWalk(b, r, c, dr, dc, (rr, cc, t, path) => {
        if (path.length >= rb.ar) return true;
        if (t && !t.ghost) { if (t.c !== p.c) add(rr, cc, 'c'); return true; }
        add(rr, cc, 'c');
        return false;
    }));
    return out;
}
function engPaintInfo() {
    const root = document.getElementById('board');
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('.cell.rbi-m,.cell.rbi-b,.cell.rbi-c,.cell.rbi-t,.cell.rbi-a').forEach(el => el.classList.remove('rbi-m', 'rbi-b', 'rbi-c', 'rbi-t', 'rbi-a'));
    root.querySelectorAll('.piece.charged').forEach(el => el.classList.remove('charged'));
    if (!G || G.over) return;
    // осматриваемая фигура: чужая (по нажатию) или выбранная своя
    let tgt = null;
    if (ENG_INFO) {
        const q = G.board[ENG_INFO.r][ENG_INFO.c];
        if (engSpecial(q) && ENG_INFO.stamp === G.log.length) tgt = [ENG_INFO.r, ENG_INFO.c]; else ENG_INFO = null;
    }
    if (!tgt && G.sel && !G.mode && engSpecial(G.board[G.sel.r][G.sel.c])) tgt = [G.sel.r, G.sel.c];
    const cellEl = (r, c) => root.querySelector(`.cell[data-r="${r}"][data-c="${c}"]`);
    if (tgt) {
        const [r, c] = tgt, p = G.board[r][c];
        if (p.t === 'x') {
            robMap(G.board, r, c).forEach((o, key) => {
                const [rr, cc] = key.split(',').map(Number), el = cellEl(rr, cc);
                if (el) el.classList.add(o.m && o.c ? 'rbi-b' : o.m ? 'rbi-m' : 'rbi-c');
            });
        } else {
            p.tur.cells.forEach(([dr, dc]) => { const rr = r + dr, cc = c + dc; if (rr < 0 || rr >= N || cc < 0 || cc >= N) return; const el = cellEl(rr, cc); if (el) el.classList.add(p.tur.kind === 'instant' ? 'rbi-t' : 'rbi-a'); });
        }
        const LEG = p.t === 'x'
            ? ['Робот: синие клетки: ходит, красные: ходит и рубит, жёлтые: только рубит.', 'Robot: blue squares: moves, red: moves and captures, yellow: captures only.']
            : p.tur.kind === 'instant'
                ? ['Турель: красные клетки: враг в них уничтожается сразу.', 'Turret: red squares: an enemy there is destroyed at once.']
                : ['Турель: жёлтые клетки: если в них появится враг, через ход туда прилетит выстрел.', 'Turret: yellow squares: if an enemy appears there, a shot lands on it after a turn.'];
        ['hint', 'mHint'].forEach(id => { const h = document.getElementById(id); if (h) h.textContent = L(LEG[0], LEG[1]); });
    }
    // заряженный робот: его ход бесплатный
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) { const q = G.board[r][c]; if (q && q.t === 'x' && q.chg > 0) { const el = cellEl(r, c), pe = el && el.querySelector('.piece'); if (pe) pe.classList.add('charged'); } }
    if (!G.mode && isActor() && G.sel && chargeFree(G.board[G.sel.r][G.sel.c], G.sel.r, G.sel.c)) ['hint', 'mHint'].forEach(id => { const h = document.getElementById(id); if (h) h.textContent = L('🔋 Робот заряжен: этот ход бесплатный (шаховать им нельзя), потом вы ещё сходите как обычно.', '🔋 The robot is charged: this move is free (it cannot give check), then you still make your normal move.'); });
}
// Нажатие на чужого (или, когда не ваш ход, любого) робота или турель: показать, куда они дотягиваются, ничего не отправляя сопернику
document.getElementById('board').addEventListener('click', e => {
    const cell = e.target.closest('.cell');
    if (!cell || !G || G.over || G.pendingPromo || REPLAY.on) return;
    const r = +cell.dataset.r, c = +cell.dataset.c, p = G.board[r][c];
    const me = NET.on ? NET.me : G.turn;
    const actor = isActor();
    const special = engSpecial(p) && !(p.invis && p.c !== me);
    if (ENG_MIN && G.mode && ENG_TAB_MODES.includes(G.mode.type) && G.mode.stage !== 'spawn' && G.mode.stage !== 'piece') {      // планшет свёрнут: доска только для осмотра, сборка не сбрасывается
        e.stopImmediatePropagation();
        if (special) ENG_INFO = (ENG_INFO && ENG_INFO.r === r && ENG_INFO.c === c) ? null : { r, c, stamp: G.log.length };
        else ENG_INFO = null;
        render();
        return;
    }
    const aimed = !!(G.mode && G.mode.cells && G.mode.cells.some(x => x[0] === r && x[1] === c)) || !!(G.sel && G.moves.some(m => m.tr === r && m.tc === c)) || !!G.pairStep;
    if (special && !aimed && (p.c !== me || !actor)) {
        e.stopImmediatePropagation();
        ENG_INFO = (ENG_INFO && ENG_INFO.r === r && ENG_INFO.c === c) ? null : { r, c, stamp: G.log.length };
        render();
        return;
    }
    ENG_INFO = null;
}, true);

/* ---------- Пиксельные картинки и экран планшета ---------- */
const ENG_SPR = {
    // пешка: маленькая голова, шея, широкое тело и основание
    pawn: ['...##...', '..####..', '..####..', '...##...', '..####..', '..####..', '.######.', '.######.', '########'],
    // меч: длинный клинок, широкая гарда, короткая рукоять (ниже собирается пешка с мечом)
    blade: ['..##..', '..##..', '..##..', '..##..', '..##..', '..##..', '..##..', '######', '######', '..##..', '..##..'],
    boot: ['.####.....', '.####.....', '.####.....', '.####.....', '.####.....', '.#######..', '.#########', '.#########', '.#########', '.#########'],
    wing: ['#.........', '##........', '###.......', '.####.....', '.######...', '..#######.', '...#######', '....######', '.....####.'],
    arrow: ['....#....', '...###...', '..#####..', '.#######.', '....#....', '....#....', '....#....', '....#....', '....#....'],
    plus: ['...#...', '...#...', '...#...', '#######', '...#...', '...#...', '...#...'],
    minus: ['.......', '.......', '.......', '#######', '.......', '.......', '.......'],
    bolt: ['.....###.', '....###..', '...###...', '..######.', '.....##..', '....##...', '...##....', '..#......', '.#.......'],
    target: ['...###...', '.##...##.', '.#..#..#.', '#...#...#', '#.#####.#', '#...#...#', '.#..#..#.', '.##...##.', '...###...'],
    tower: ['..####..', '.######.', '..####..', '..####..', '.######.', '.######.', '########', '########'],
    check: ['.........', '........#', '.......##', '......##.', '#....##..', '##..##...', '.####....', '..##.....', '...#.....'],
    cross: Array.from({ length: 9 }, (_, i) => Array.from({ length: 9 }, (_, j) => (Math.abs(i - j) <= 1 || Math.abs(i + j - 8) <= 1) ? '#' : '.').join(''))
};
// пешка с мечом: пешка внизу слева, меч справа
ENG_SPR.sword = ENG_SPR.blade.map((row, i) => {
    const off = ENG_SPR.blade.length - ENG_SPR.pawn.length;
    return (i >= off ? ENG_SPR.pawn[i - off] : '........') + '.' + row;
});
function engPix(name) {
    const g = ENG_SPR[name], w = g[0].length, h = g.length;
    let rects = '';
    g.forEach((row, y) => { for (let x = 0; x < w; x++) if (row[x] === '#') rects += `<rect x="${x}" y="${y}" width="1" height="1"/>`; });
    return `<svg class="eng-pix${w > h + 3 ? ' wide' : ''}" viewBox="0 0 ${w} ${h}" shape-rendering="crispEdges" fill="currentColor">${rects}</svg>`;
}

function engTabletHTML(m) {
    const st = m.stage, d3 = [-1, 0, 1], d5 = [-2, -1, 0, 1, 2];
    const kindNow = m.kind || m.sel;
    let title = '', body = '', note = '', ok = true, x2 = false, costLine = '', nextLabel = 'ПРОДОЛЖИТЬ ▶';
    const sq = (act, val, on, inner, label, dis) => `<button class="eng-sq big${on ? ' on' : ''}" data-eng="${act}" data-v="${val}" ${dis ? 'disabled' : ''}>${inner}<i>${label}</i></button>`;
    // сетка со стрелками (направления робота)
    const dirGrid = list => '<div class="eng-grid g3">' + d3.map(i => d3.map(j => {
        if (!i && !j) return `<div class="eng-sq static">${engPix(st === 'atk' ? 'sword' : 'pawn')}</div>`;
        const deg = Math.round(Math.atan2(j, -i) * 180 / Math.PI);
        return `<button class="eng-sq${engHas(list, [i, j]) ? ' on' : ''}" data-eng="dir" data-v="${i},${j}"><span class="eng-rot" style="transform:rotate(${deg}deg)">${engPix('arrow')}</span></button>`;
    }).join('')).join('') + '</div>';
    // сетка клеток 3×3 или 5×5: list: выбранные, lock: заблокированные (уже выбраны раньше), walk: цвет «только ходьба»
    const cellGrid = (n, list, lock, walk, centerSprite) => {
        const rng = n === 3 ? d3 : d5, full = (lock ? lock.length : 0) + list.length >= (n === 3 ? 8 : ENG_MAX_JUMP);
        return `<div class="eng-grid g${n}">` + rng.map(i => rng.map(j => {
            if (!i && !j) return `<div class="eng-sq static">${engPix(centerSprite)}</div>`;
            const inL = lock && engHas(lock, [i, j]), inS = engHas(list, [i, j]);
            const dis = inL || (n === 5 && walk && !inS && full);
            return `<button class="eng-sq${inS ? ' on' : ''}${inS && walk ? ' walk' : ''}${inL ? ' on lock' : ''}" data-eng="jump" data-v="${i},${j}" ${dis ? 'disabled' : ''}></button>`;
        }).join('')).join('') + '</div>';
    };
    if (m.type === 'turret') {
        costLine = `СБОРКА ТУРЕЛИ · КД: 5 + ${engCost(m)} = ${5 + engCost(m)}`;
        if (st === 'tkind') {
            title = 'ВЫБОР ТУРЕЛИ';
            body = '<div class="eng-row">' + sq('pick', 'instant', m.sel === 'instant', engPix('bolt'), 'МГНОВЕННАЯ<br>СТРЕЛЬБА') + sq('pick', 'artillery', m.sel === 'artillery', engPix('target'), 'ДАЛЬНЯЯ<br>АРТИЛЛЕРИЯ') + '</div>';
            note = 'МГНОВЕННАЯ: ВРАГ В РАДИУСЕ 3×3 УНИЧТОЖАЕТСЯ СРАЗУ. АРТИЛЛЕРИЯ: РАДИУС 5×5, ВЫСТРЕЛ ЧЕРЕЗ ХОД.';
            ok = m.sel === 'instant' || m.sel === 'artillery';
        } else {
            title = m.tk === 'instant' ? 'РАДИУС: МГНОВЕННАЯ СТРЕЛЬБА' : 'РАДИУС: АРТИЛЛЕРИЯ';
            body = cellGrid(m.tk === 'instant' ? 3 : 5, m.tc, null, false, 'tower');
            note = `КАЖДАЯ КЛЕТКА +2 КД. ВЫБРАНО ${m.tc.length}. НУЖНА ХОТЯ БЫ ОДНА.`;
            ok = m.tc.length >= 1;
        }
    } else if (m.type === 'reprogram' && !m.rb) {
        const rp = m.rp, s2 = engReproState(m);
        title = 'ПЕРЕПРОГРАММИРОВАНИЕ';
        nextLabel = 'ПРИМЕНИТЬ ▶';
        ok = s2.valid && s2.changed;
        costLine = `ПЕРЕПРОГРАММИРОВАНИЕ · КД: 1 + ${s2.cost} = ${1 + s2.cost}`;
        body = cellGrid(rp.tk === 'instant' ? 3 : 5, rp.tc, null, false, 'tower');
        note = 'РАДИУС ТУРЕЛИ ЗАНОВО. КАЖДАЯ НОВАЯ КЛЕТКА +2 КД.';
    } else {
        if (m.rb) { const rs = engReproRobState(m); costLine = `ПЕРЕПРОГРАММИРОВАНИЕ · КД: 1 + ${rs.cost} = ${1 + rs.cost}`; }
        else costLine = `СБОРКА РОБОТА · КД: 3 + ${engCost({ ...m, kind: kindNow })} = ${3 + engCost({ ...m, kind: kindNow })}`;
        if (st === 'kind') {
            title = 'ВЫБОР ФИГУРЫ';
            body = '<div class="eng-row">' + sq('pick', 'boot', m.sel === 'boot', engPix('boot'), 'САПОГ<br>+0 КД') + sq('pick', 'wing', m.sel === 'wing', engPix('wing'), 'КРЫЛО<br>+3 КД') + '</div>';
            note = 'САПОГ: ХОДИТ И РУБИТ, НЕ ПРЫГАЯ ЧЕРЕЗ ФИГУРЫ. КРЫЛО: ПРЫГАЕТ ПО КЛЕТКАМ.';
            ok = m.sel === 'boot' || m.sel === 'wing';
        } else if (st === 'walk') {
            title = 'НАПРАВЛЕНИЯ ХОДЬБЫ'; x2 = true;
            body = dirGrid(m.walk);
            note = 'КАЖДАЯ СТРЕЛКА +1 КД. ХОД НА КЛЕТКУ ВПЕРЁД.';
        } else if (st === 'atk') {
            title = 'НАПРАВЛЕНИЯ АТАКИ';
            body = dirGrid(m.atk);
            note = 'КАЖДАЯ СТРЕЛКА +1 КД. НУЖНО ВЫБРАТЬ ХОТЯ БЫ ОДНО НАПРАВЛЕНИЕ.';
            ok = m.walk.length + m.atk.length >= 1;
        } else if (st === 'after') {
            title = 'ЧТО ДАЛЬШЕ?';
            body = '<div class="eng-row">' + sq('pick', 'boot', m.sel === 'boot', engPix('boot'), 'ДАЛЬНОСТЬ') + sq('pick', 'x', m.sel === 'x', engPix('cross'), 'ГОТОВО') + '</div>';
            ok = m.sel === 'boot' || m.sel === 'x';
        } else if (st === 'range') {
            title = 'ДАЛЬНОСТЬ';
            body = `<div class="eng-row"><div class="eng-sq big static">${engPix('pawn')}</div><div class="eng-col"><button class="eng-sq mini" data-eng="range" data-v="1">${engPix('plus')}</button><div class="eng-sq big static">${engPix('boot')}<b class="eng-num">${m.wr}</b></div><button class="eng-sq mini" data-eng="range" data-v="-1">${engPix('minus')}</button></div></div>`;
            note = engSame(m) ? 'НАПРАВЛЕНИЯ СОВПАЛИ: ДАЛЬНОСТЬ ХОДЬБЫ И АТАКИ ВМЕСТЕ, КАЖДЫЙ ШАГ +2 КД.' : 'ДАЛЬНОСТЬ ХОДЬБЫ, КАЖДЫЙ ШАГ +1 КД.';
        } else if (st === 'wing') {
            title = 'ПРЫЖКИ: ХОД И АТАКА';
            body = cellGrid(5, m.ja, null, false, 'pawn');
            note = `КАЖДАЯ КЛЕТКА +2 КД. ВЫБРАНО ${m.ja.length} ИЗ ${ENG_MAX_JUMP}.`;
            ok = m.ja.length >= 1;
        } else if (st === 'wingafter') {
            title = 'ЧТО ДАЛЬШЕ?';
            body = '<div class="eng-row">' + sq('pick', 'boot', m.sel === 'boot', engPix('boot'), 'УСИЛИТЬ', m.ja.length >= ENG_MAX_JUMP) + sq('pick', 'x', m.sel === 'x', engPix('cross'), 'ГОТОВО') + '</div>';
            note = m.ja.length >= ENG_MAX_JUMP ? 'ВСЕ 8 КЛЕТОК УЖЕ ВЫБРАНЫ, УСИЛИТЬ НЕЛЬЗЯ.' : '';
            ok = m.sel === 'boot' || m.sel === 'x';
        } else if (st === 'wingplus') {
            title = 'УСИЛЕНИЕ: ТОЛЬКО ХОДЬБА';
            body = cellGrid(5, m.jw, m.ja, true, 'pawn');
            note = `КАЖДАЯ КЛЕТКА +1 КД. ВСЕГО КЛЕТОК ${m.ja.length + m.jw.length} ИЗ ${ENG_MAX_JUMP}.`;
        }
    }
    return `<div class="eng-tab"><button class="eng-close" data-eng="close" title="Закрыть планшет">✕</button><button class="eng-min" data-eng="min" title="Свернуть планшет">—</button>
      <div class="eng-screen"><div class="eng-inner">
        <div class="eng-head"><span class="eng-title">${title}</span>${x2 ? '<button class="eng-btn eng-x2" data-eng="x2" ' + (m.walk.length ? '' : 'disabled') + '>ПОДТВЕРДИТЬ ×2</button>' : ''}</div>
        <div class="eng-body">${body}</div>
        <div class="eng-note">${note}</div>
        <div class="eng-cost">${costLine}</div>
        <div class="eng-foot"><button class="eng-btn" data-eng="back">◀ НАЗАД</button><button class="eng-btn" data-eng="next" ${ok ? '' : 'disabled'}>${nextLabel}</button></div>
      </div></div></div>`;
}

/* ---------- Звуки планшета: ретро-пиксельные «пшик» и бипы (только у того, кто нажимает) ---------- */
function engNoise(d, v, delay = 0, hp = 3000) {
    if (!CONFIG.sound) return;
    try {
        actx = actx || new (window.AudioContext || window.webkitAudioContext)();
        const n = Math.max(1, Math.floor(actx.sampleRate * d)), buf = actx.createBuffer(1, n, actx.sampleRate), data = buf.getChannelData(0);
        for (let i = 0; i < n; i += 4) { const x = Math.random() * 2 - 1; for (let j = 0; j < 4 && i + j < n; j++) data[i + j] = x; }      // «пиксельный» шум: значение держится по 4 отсчёта
        const src = actx.createBufferSource(), g = actx.createGain(), f = actx.createBiquadFilter();
        f.type = 'highpass'; f.frequency.value = hp;
        const t = actx.currentTime + delay;
        g.gain.setValueAtTime(v, t);
        g.gain.exponentialRampToValueAtTime(0.0001, t + d);
        src.buffer = buf; src.connect(f); f.connect(g); g.connect(actx.destination);
        src.start(t);
    } catch (e) { /* звук не критичен */ }
}
Object.assign(SFX, {
    engClick: () => tone(1200, 0.025, 'square', 0.03),
    engPick: () => { tone(700, 0.04, 'square', 0.04); tone(1050, 0.05, 'square', 0.04, 0.04); },
    engOn: () => { tone(1000, 0.03, 'square', 0.035); tone(1500, 0.035, 'square', 0.03, 0.03); },
    engOff: () => { tone(1000, 0.03, 'square', 0.035); tone(600, 0.04, 'square', 0.03, 0.03); },
    engBack: () => { tone(800, 0.03, 'square', 0.035); tone(500, 0.05, 'square', 0.035, 0.03); },
    engSwitch: () => { engNoise(0.09, 0.05, 0, 2500);[1800, 900, 1400, 600].forEach((f, i) => tone(f, 0.02, 'square', 0.025, i * 0.02)); },
    engOk: () => [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.07, 'square', 0.035, i * 0.06)),
    engMin: () => { tone(900, 0.04, 'square', 0.03); tone(450, 0.06, 'square', 0.03, 0.04); },
    engMax: () => { tone(450, 0.04, 'square', 0.03); tone(900, 0.06, 'square', 0.03, 0.04); },
    raise: () => { tone(70, 0.5, 'sawtooth', 0.07); tone(110, 0.4, 'square', 0.04, 0.2);[150, 120, 170, 110, 140].forEach((f, i) => tone(f, 0.05, 'square', 0.025, 0.12 + i * 0.09)); engNoise(0.35, 0.03, 0.1, 600); }      // и земля сыплется
});

let ENG_POS = { x: 0, y: 0 };      // куда сдвинули планшет мышкой
let ENG_MIN = false;      // планшет свёрнут: на доску можно смотреть, ничего не сбрасывается
let ENG_LAST = null;      // какой экран планшета был показан в прошлый раз (для «глюка» при переходе)
function renderEngTablet() {
    let ov = document.getElementById('engTablet'), mini = document.getElementById('engMini');
    const m = G && G.mode;
    const show = !!(m && ENG_TAB_MODES.includes(m.type) && m.stage !== 'spawn' && m.stage !== 'piece' && !G.over && isActor() && !REPLAY.on && REW.idx < 0);
    if (!show) {
        if (ov) ov.classList.add('hidden');
        if (mini) mini.classList.add('hidden');
        if (ENG_LAST && m && ENG_TAB_MODES.includes(m.type) && m.stage === 'spawn' && isActor() && !REPLAY.on) SFX.engOk();      // сборка подтверждена
        ENG_MIN = false; ENG_LAST = null; ENG_POS = { x: 0, y: 0 };
        return;
    }
    if (!ov) {
        ov = document.createElement('div');
        ov.id = 'engTablet';
        ov.className = 'eng-ov';
        ov.addEventListener('click', e => {
            const b = e.target.closest('[data-eng]');
            if (!b || b.disabled) return;
            const act = b.dataset.eng;
            if (act === 'min') { SFX.engMin(); ENG_MIN = true; renderEngTablet(); return; }      // только у себя, соперник ничего не видит
            if (act === 'pick') SFX.engPick();
            else if (act === 'dir' || act === 'jump') (b.classList.contains('on') ? SFX.engOff : SFX.engOn)();
            else if (act === 'range') SFX.engOn();
            else if (act === 'back' || act === 'close') SFX.engBack();
            else SFX.engClick();
            let v = b.dataset.v;
            if (v !== undefined) { if (v.includes(',')) v = v.split(',').map(Number); else if (/^-?\d+$/.test(v)) v = Number(v); }
            netDo({ t: 'eng', a: act, v });
        });
        // на компьютере планшет можно таскать за серую рамку или заголовок, как окно
        ov.addEventListener('pointerdown', e => {
            if (e.pointerType === 'touch' || e.button > 0) return;
            const tab = e.target.closest('.eng-tab');
            if (!tab || e.target.closest('button') || !(e.target === tab || e.target.closest('.eng-head'))) return;
            const r0 = tab.getBoundingClientRect(), sx = e.clientX, sy = e.clientY, ox = ENG_POS.x, oy = ENG_POS.y;
            tab.setPointerCapture(e.pointerId);
            tab.classList.add('dragging');
            const mv = ev => {
                const nl = clampN(r0.left + ev.clientX - sx, 0, Math.max(0, innerWidth - r0.width)), nt = clampN(r0.top + ev.clientY - sy, 0, Math.max(0, innerHeight - r0.height));
                ENG_POS = { x: ox + nl - r0.left, y: oy + nt - r0.top };
                tab.style.transform = `translate(${ENG_POS.x}px,${ENG_POS.y}px)`;
            };
            const up = () => { tab.classList.remove('dragging'); tab.removeEventListener('pointermove', mv); tab.removeEventListener('pointerup', up); tab.removeEventListener('pointercancel', up); };
            tab.addEventListener('pointermove', mv);
            tab.addEventListener('pointerup', up);
            tab.addEventListener('pointercancel', up);
            e.preventDefault();
        });
        document.body.appendChild(ov);
    }
    if (!mini) {
        mini = document.createElement('button');
        mini.id = 'engMini';
        mini.className = 'eng-mini-btn hidden';
        mini.addEventListener('click', () => { SFX.engMax(); ENG_MIN = false; ENG_LAST = null; render(); });
        document.body.appendChild(mini);
    }
    const key = m.type + ':' + m.stage;
    if (ENG_MIN) {
        ov.classList.add('hidden');
        mini.textContent = '📟 ' + L('Планшет', 'Tablet');
        mini.classList.remove('hidden');
        ENG_LAST = key;
        return;
    }
    mini.classList.add('hidden');
    ov.innerHTML = engTabletHTML(m);
    ov.classList.remove('hidden');
    { const tb = ov.querySelector('.eng-tab'); if (tb && (ENG_POS.x || ENG_POS.y)) tb.style.transform = `translate(${ENG_POS.x}px,${ENG_POS.y}px)`; }
    if (key !== ENG_LAST) {      // переход между экранами: экран на микросекунду «глючит» и расплывается, как переключение камер
        const sc = ov.querySelector('.eng-inner');      // дрожит только содержимое, серая рамка и край экрана стоят на месте
        if (sc && ANIM.board !== false) sc.classList.add('glitch');      // при выключенных анимациях (🎬) экран не дрожит
        SFX.engSwitch();
    }
    ENG_LAST = key;
}
const _renderEngBase = render;
render = function () {
    _renderEngBase.apply(this, arguments);
    try { renderEngTablet(); } catch (e) { /* планшет не должен ломать партию */ }
    try { engPaintInfo(); } catch (e) { /* подсветка тоже */ }
};

// Выбор своего робота или турели для перепрограммирования (нажатие на клетку на доске)
function engPickRepro(r, c) {
    const m = G.mode, col = G.turn, p = G.board[r][c];
    if (!p || !m.cells.some(x => x[0] === r && x[1] === c)) return;
    const ui = d => engAbs(col, d), cp = arr => arr.map(d => [d[0], d[1]]);
    m.hist = ['piece']; m.target = [r, c]; m.sel = null; m.cells = [];
    if (p.t === 'u') {
        const t = cp(p.tur.cells.map(ui));
        m.rb = false; m.stage = 'rp'; m.rp = { kind: 'turret', tk: p.tur.kind, tc: cp(t), old: cp(t) };
    } else {
        m.rb = true; m.rp = null; m.kind = p.rob.kind;
        if (p.rob.kind === 'wing') { m.ja = cp(p.rob.ja.map(ui)); m.jw = cp(p.rob.jw.map(ui)); m.walk = []; m.atk = []; m.wr = 1; m.stage = 'wing'; }
        else { m.walk = cp(p.rob.walk.map(ui)); m.atk = cp(p.rob.atk.map(ui)); m.wr = p.rob.wr; m.ja = []; m.jw = []; m.stage = 'walk'; }
        m.old = { walk: cp(m.walk), atk: cp(m.atk), wr: m.wr, ja: cp(m.ja), jw: cp(m.jw) };      // что было до перепрограммирования
    }
    render();
}

/* =====================================================================
   АНИМАЦИИ СПОСОБНОСТЕЙ
   ===================================================================== */
// Полоска с названием способности: быстро влетает слева в центр доски, медленно плывёт, быстро улетает вправо
const BANNER_SKIP = ['lie'];      // секретные способности не показываем, чтобы не выдавать их применение
function abilityBanner(key) {
    if (REPLAY_REC && !BANNER_SKIP.includes(key)) { REPLAY_REC.push({ k: 'banner', key }); return; }
    try {
        if (typeof document === 'undefined' || !ANIM.banner || BANNER_SKIP.includes(key)) return;
        const A = ABILITIES[key] || PASSIVES[key], board = $('#board');
        if (!A || !board || !board.offsetWidth) return;
        document.querySelectorAll('.ab-banner-box').forEach(e => e.remove());
        const rect = board.getBoundingClientRect();
        const box = document.createElement('div');
        box.className = 'ab-banner-box';
        box.style.cssText = `left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px`;
        const strip = document.createElement('div');
        strip.className = 'ab-banner';
        strip.innerHTML = `<span class="abb-icon">${A.icon}</span><span class="abb-name">${A.name}</span>`;
        box.appendChild(strip);
        document.body.appendChild(box);
        const anim = strip.animate([
            { transform: 'translateX(-105%)', offset: 0, easing: 'cubic-bezier(.15,.85,.25,1)' },     // быстро влетает
            { transform: 'translateX(-3%)', offset: 0.14, easing: 'linear' },
            { transform: 'translateX(3%)', offset: 0.78, easing: 'cubic-bezier(.6,0,1,.7)' },         // медленно плывёт около секунды
            { transform: 'translateX(105%)', offset: 1 }                                                // быстро улетает вправо
        ], { duration: 1700, fill: 'both' });
        anim.onfinish = () => box.remove();
        setTimeout(() => box.remove(), 2600);
    } catch (e) { }
}

// Помидор: вылетает из панели Шута, падает на кнопку способности врага и размазывается по ней
function tomatoPrepare(col, en, k) {
    if (REPLAY_REC) return null;
    try {
        if (!ANIM.board) return null;
        const pan = document.querySelector('#panel-' + col);
        const src = pan && (pan.querySelector('.hero-icon') || pan);
        const btn = document.querySelector(`#panel-${en} [data-tomato="${k}"]`);
        if (!src || !btn) return null;
        const a = src.getBoundingClientRect(), b = btn.getBoundingClientRect();
        if (!a.width || !b.width) return null;
        return { x0: a.left + a.width / 2, y0: a.top + a.height / 2, x1: b.left + b.width / 2, y1: b.top + b.height / 2, b, en, k };
    } catch (e) { return null; }
}
function tomatoFly(f) {
    if (!f) return;
    try {
        const hold = document.querySelector(`#panel-${f.en} [data-ab="${f.k}"]`);
        if (hold) hold.classList.add('tomato-pending');       // пятно на кнопке появится, когда помидор долетит
        const t = document.createElement('div');
        t.className = 'tomato-fly';
        t.textContent = '🍅';
        document.body.appendChild(t);
        const at = (x, y, sc, rot) => `translate(${x}px,${y}px) translate(-50%,-50%) scale(${sc}) rotate(${rot}deg)`;
        const mx = (f.x0 + f.x1) / 2, my = Math.min(f.y0, f.y1) - 110;
        const anim = t.animate([
            { transform: at(f.x0, f.y0, 0.5, 0), offset: 0, easing: 'ease-out' },
            { transform: at(mx, my, 1.4, 300), offset: 0.5, easing: 'ease-in' },
            { transform: at(f.x1, f.y1, 1, 640), offset: 1 }
        ], { duration: 700, fill: 'forwards' });
        const land = () => {
            t.remove();
            if (hold && hold.isConnected) hold.classList.remove('tomato-pending');
            const sp = document.createElement('div');
            sp.className = 'tomato-splat';
            sp.style.cssText = `left:${f.b.left}px;top:${f.b.top}px;width:${f.b.width}px;height:${f.b.height}px`;
            document.body.appendChild(sp);
            setTimeout(() => sp.remove(), 2800);
        };
        anim.onfinish = land;
        setTimeout(() => { if (t.isConnected) land(); }, 1200);
    } catch (e) { }
}
// Своя картинка помидора (необязательно): pieces/tomato.png
(function () {
    if (typeof Image === 'undefined') return;
    const im = new Image();
    im.onload = () => { document.documentElement.style.setProperty('--img-tomato', 'url("pieces/tomato.png")'); if (document.body) document.body.classList.add('img-tomato'); };
    im.src = 'pieces/tomato.png';
})();

/* ---------- Анимации на доске: полёты, скольжение, дым, вознесение ---------- */
const cellEl = (r, c) => document.querySelector(`#board .cell[data-r="${r}"][data-c="${c}"]`);
const clampN = (v, a, b) => Math.max(a, Math.min(b, v));

// Поставить в очередь полёт снаряда к цели. Возвращает время полёта в секундах (0, если анимации выключены)
function queueFlight(owner, f, kind, piece) {
    if (!ANIM.board) return 0;
    const kp = findKing(G.board, owner);
    const dist = kp ? Math.hypot(kp[0] - f.r, kp[1] - f.c) : 6;
    const dur = clampN(0.35 + dist * 0.06, 0.45, 0.9) * (kind === 'arrow' ? 0.8 : 1);
    const pc = piece && !piece.invis && !piece.ghost ? { c: piece.c, t: piece.t } : null;
    queueAnim({ k: 'flight', kind, from: kp ? [kp[0], kp[1]] : null, to: [f.r, f.c], dur, piece: pc });
    return dur;
}

// Свист при скольжении на банане: «фууить»
function sfxWhistle() {
    if (!CONFIG.sound) return;
    try {
        actx = actx || new (window.AudioContext || window.webkitAudioContext)();
        const t = actx.currentTime, o = actx.createOscillator(), g = actx.createGain();
        o.type = 'sine';
        o.frequency.setValueAtTime(450, t);
        o.frequency.exponentialRampToValueAtTime(2300, t + 0.28);
        o.frequency.exponentialRampToValueAtTime(700, t + 0.66);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.07, t + 0.05);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 0.7);
        o.connect(g); g.connect(actx.destination);
        o.start(t); o.stop(t + 0.72);
    } catch (e) { }
}

// Спрятать настоящую фигуру на клетке на ms миллисекунд (пока по экрану летит её копия)
function hideCell(r, c, ms) {
    const h = { r, c, until: Date.now() + ms };
    ANIM_HIDE.push(h);
    const e = cellEl(r, c), pe = e && e.querySelector('.piece:not(.doomed)');
    if (pe) pe.classList.add('anim-hide');
    setTimeout(() => {
        const i = ANIM_HIDE.indexOf(h); if (i >= 0) ANIM_HIDE.splice(i, 1);
        const e2 = cellEl(r, c), p2 = e2 && e2.querySelector('.piece.anim-hide');
        if (p2) p2.classList.remove('anim-hide');
    }, ms);
}

// Копия фигуры поверх экрана на месте клетки (fixed), чтобы перерисовка доски её не стирала
function pieceClone(realPiece, cellRect) {
    const cl = realPiece.cloneNode(true);
    cl.classList.remove('pop', 'anim-hide', 'sel');
    cl.classList.add('anim-clone');
    cl.style.cssText = `position:fixed;left:${cellRect.left}px;top:${cellRect.top}px;width:${cellRect.width}px;height:${cellRect.height}px;z-index:90;margin:0;`;
    document.body.appendChild(cl);
    return cl;
}

function runAnimQueue() {
    if (REPLAY_REC) { ANIMQ.length = 0; return; }
    if (!ANIMQ.length) return;
    const q = ANIMQ.splice(0);
    if (!ANIM.board && !q.every(a => a.k === 'lateFx')) return;
    q.slice(-12).forEach(a => {
        try {
            if (a.k === 'lateFx') {
                setTimeout(() => {
                    const e = cellEl(a.r, a.c);
                    if (e) e.insertAdjacentHTML('beforeend', `<div class="fx fx-${a.type}"></div>`);
                    if (a.type === 'boom') { const b = $('#board'); b.classList.remove('shake'); void b.offsetWidth; b.classList.add('shake'); }
                }, a.delay * 1000);
            } else if (a.k === 'flight') {
                const te = cellEl(a.to[0], a.to[1]);
                if (!te) return;
                const tr = te.getBoundingClientRect(), br = $('#board').getBoundingClientRect();
                const x1 = tr.left + tr.width / 2, y1 = tr.top + tr.height / 2;
                let x0, y0;
                if (a.from) { const fe = cellEl(a.from[0], a.from[1]), fr = fe && fe.getBoundingClientRect(); x0 = fr ? fr.left + fr.width / 2 : x1; y0 = fr ? fr.top + fr.height / 2 : br.top - 40; }
                else { x0 = x1; y0 = br.top - 40; }
                if (Math.abs(x0 - x1) < 2 && Math.abs(y0 - y1) < 2) y0 = br.top - 40;
                // убитая фигура остаётся на клетке, пока не долетит снаряд
                if (a.piece && !te.querySelector('.piece')) {
                    const gp = document.createElement('div');
                    gp.className = `piece ${a.piece.c} t-${a.piece.t} doomed`;
                    gp.innerHTML = GLYPH[a.piece.t];
                    te.appendChild(gp);
                    setTimeout(() => gp.remove(), a.dur * 1000);
                }
                const pr = document.createElement('div');
                pr.className = 'proj proj-' + a.kind;
                document.body.appendChild(pr);
                const ang = Math.atan2(y1 - y0, x1 - x0) * 180 / Math.PI;
                const at = (x, y, sc, rot) => `translate(${x}px,${y}px) translate(-50%,-50%) rotate(${rot}deg) scale(${sc})`;
                let frames;
                if (a.kind === 'arrow' || a.kind === 'bullet') {
                    frames = [{ transform: at(x0, y0, 0.8, ang), offset: 0 }, { transform: at(x1, y1, 1, ang), offset: 1 }];
                } else {
                    const lift = Math.min(140, 40 + Math.hypot(x1 - x0, y1 - y0) * 0.25);
                    frames = [
                        { transform: at(x0, y0, 0.5, 0), offset: 0, easing: 'ease-out' },
                        { transform: at((x0 + x1) / 2, (y0 + y1) / 2 - lift, 1.15, 180), offset: 0.5, easing: 'ease-in' },
                        { transform: at(x1, y1, 1, 360), offset: 1 }
                    ];
                }
                const an = pr.animate(frames, { duration: a.dur * 1000, easing: a.kind === 'arrow' ? 'cubic-bezier(.3,0,.8,.6)' : 'linear', fill: 'forwards' });      // пуля летит ровно
                an.onfinish = () => pr.remove();
                setTimeout(() => pr.remove(), a.dur * 1000 + 400);
            } else if (a.k === 'slide') {
                const se = cellEl(a.from[0], a.from[1]), de = cellEl(a.to[0], a.to[1]);
                const real = de && de.querySelector('.piece');
                if (!se || !real) return;
                const sr = se.getBoundingClientRect(), dr = de.getBoundingClientRect();
                const dx = dr.left - sr.left, dy = dr.top - sr.top;
                const cl = pieceClone(real, sr);
                hideCell(a.to[0], a.to[1], 720);
                sfxWhistle();
                const an = cl.animate([
                    { transform: 'translate(0,0) rotate(0deg) scale(1)', offset: 0, easing: 'ease-out' },
                    { transform: `translate(${dx / 2}px,${dy / 2 - sr.height * 0.55}px) rotate(180deg) scale(1.3)`, offset: 0.5, easing: 'ease-in' },
                    { transform: `translate(${dx}px,${dy}px) rotate(360deg) scale(1)`, offset: 1 }
                ], { duration: 700, fill: 'forwards' });
                an.onfinish = () => cl.remove();
                setTimeout(() => cl.remove(), 1100);
            } else if (a.k === 'rescue') {
                const se = cellEl(a.from[0], a.from[1]), de = cellEl(a.to[0], a.to[1]);
                const real = de && de.querySelector('.piece');
                if (!se || !real) return;
                const sr = se.getBoundingClientRect();
                const cl = pieceClone(real, sr);
                hideCell(a.to[0], a.to[1], 700);
                const an = cl.animate([
                    { transform: 'translateY(0) scale(1)', opacity: 1, filter: 'brightness(1)', offset: 0 },
                    { transform: `translateY(${-sr.height * 1.6}px) scale(1.15)`, opacity: 0, filter: 'brightness(2.4) drop-shadow(0 0 12px #fff)', offset: 1 }
                ], { duration: 650, easing: 'ease-in', fill: 'forwards' });
                an.onfinish = () => cl.remove();
                setTimeout(() => cl.remove(), 1000);
                setTimeout(() => {      // потом плавно появляется на новом месте
                    const e2 = cellEl(a.to[0], a.to[1]), p2 = e2 && e2.querySelector('.piece');
                    if (p2) p2.animate([
                        { opacity: 0, transform: 'translateY(-40%) scale(0.7)', filter: 'brightness(2.4)' },
                        { opacity: 1, transform: 'none', filter: 'none' }
                    ], { duration: 550, easing: 'ease-out' });
                }, 700);
            } else if (a.k === 'hatch') {
                const se = cellEl(a.from[0], a.from[1]), de = cellEl(a.to[0], a.to[1]);
                const real = de && de.querySelector('.piece');
                if (!se || !real) return;
                const sr = se.getBoundingClientRect(), dr = de.getBoundingClientRect();
                hideCell(a.to[0], a.to[1], 950);
                const down = pieceClone(real, sr);
                const an1 = down.animate([
                    { transform: 'translateY(0) scale(1)', opacity: 1, offset: 0 },
                    { transform: `translateY(${sr.height * 0.35}px) scale(0.1)`, opacity: 0, offset: 1 }
                ], { duration: 450, easing: 'ease-in', fill: 'forwards' });
                an1.onfinish = () => down.remove();
                setTimeout(() => {
                    const up = pieceClone(real, dr);
                    const an2 = up.animate([
                        { transform: `translateY(${dr.height * 0.35}px) scale(0.1)`, opacity: 0, offset: 0 },
                        { transform: 'translateY(0) scale(1)', opacity: 1, offset: 1 }
                    ], { duration: 450, easing: 'ease-out', fill: 'forwards' });
                    an2.onfinish = () => up.remove();
                    setTimeout(() => up.remove(), 800);
                }, 480);
                setTimeout(() => down.remove(), 900);
            } else if (a.k === 'swap') {
                [[a.a, a.b, -1], [a.b, a.a, 1]].forEach(([x, y, sgn]) => {
                    const xe = cellEl(x[0], x[1]), ye = cellEl(y[0], y[1]);
                    const real = xe && xe.querySelector('.piece');
                    if (!xe || !ye || !real) return;
                    const xr = xe.getBoundingClientRect(), yr = ye.getBoundingClientRect();
                    const cl = pieceClone(real, yr);
                    hideCell(x[0], x[1], 700);
                    const dx = xr.left - yr.left, dy = xr.top - yr.top;
                    const an = cl.animate([
                        { transform: 'translate(0,0) scale(1)', offset: 0, easing: 'ease-out' },
                        { transform: `translate(${dx / 2}px,${dy / 2 + sgn * yr.height * 0.6}px) scale(1.2) rotate(${sgn * 20}deg)`, offset: 0.5, easing: 'ease-in' },
                        { transform: `translate(${dx}px,${dy}px) scale(1)`, offset: 1 }
                    ], { duration: 650, fill: 'forwards' });
                    an.onfinish = () => cl.remove();
                    setTimeout(() => cl.remove(), 1000);
                });
            } else if (a.k === 'hat') {
                // Шляпа плавно опускается и накрывает целую фигуру, короткая барабанная дробь, шляпа улетает вверх, под ней заяц
                const te = cellEl(a.at[0], a.at[1]);
                if (!te) return;
                const rect = te.getBoundingClientRect();
                const LIFT = 1250;      // через столько мс шляпа взлетает и заяц становится виден
                hideCell(a.at[0], a.at[1], LIFT);
                const gp = document.createElement('div');      // прежняя фигура целиком, без деформации
                gp.className = `piece ${a.piece.c} t-${a.piece.t} anim-clone`;
                gp.innerHTML = GLYPH[a.piece.t];
                gp.style.cssText = `position:fixed;left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px;z-index:90;margin:0;`;
                document.body.appendChild(gp);
                setTimeout(() => gp.remove(), LIFT);
                const hat = document.createElement('div');
                hat.className = 'magic-hat';
                // шляпа-колпак рисуется рисунком (не эмодзи), чтобы точно накрывать фигуру: ширина 1.3 клетки, по центру клетки
                const HW = rect.width * 1.3, HH = rect.height * 1.25;
                hat.innerHTML = '<svg viewBox="0 0 130 125" width="100%" height="100%" aria-hidden="true">'
                    + '<ellipse cx="65" cy="107" rx="62" ry="12" fill="#14101a"/>'
                    + '<path d="M17 20 Q17 8 65 8 Q113 8 113 20 L113 104 Q65 114 17 104 Z" fill="#1d1824"/>'
                    + '<ellipse cx="65" cy="20" rx="48" ry="9" fill="#2c2536"/>'
                    + '<path d="M17 80 L113 80 L113 96 Q65 106 17 96 Z" fill="#b3263a"/>'
                    + '</svg>';
                hat.style.cssText = `left:${rect.left + rect.width / 2 - HW / 2}px;top:${rect.top + rect.height / 2 - HH / 2}px;width:${HW}px;height:${HH}px;`;
                document.body.appendChild(hat);
                const up = -rect.height * 2.6;
                const shake = (off, rot, x) => ({ transform: `translateX(${x}px) rotate(${rot}deg)`, opacity: 1, offset: off });
                const an = hat.animate([
                    { transform: `translateY(${up}px) rotate(-14deg)`, opacity: 0, offset: 0, easing: 'ease-in' },
                    { transform: `translateY(${up * 0.8}px) rotate(-10deg)`, opacity: 1, offset: 0.05, easing: 'cubic-bezier(.3,0,.7,1)' },
                    { transform: 'translateY(0) rotate(0deg)', opacity: 1, offset: 0.24 },
                    shake(0.29, 3, 2), shake(0.33, -3, -2), shake(0.37, 3, 2), shake(0.41, -3, -2),
                    shake(0.45, 3, 2), shake(0.49, -3, -2), shake(0.53, 3, 2), shake(0.57, -3, -2),
                    { transform: 'translateY(0) rotate(0deg)', opacity: 1, offset: 0.625, easing: 'cubic-bezier(.5,0,.9,.5)' },
                    { transform: `translateY(${up * 1.4}px) rotate(16deg)`, opacity: 0, offset: 1 }
                ], { duration: 2000, fill: 'forwards' });
                an.onfinish = () => hat.remove();
                setTimeout(() => hat.remove(), 2400);
                setTimeout(() => sfx('drumroll'), 460);
                setTimeout(() => sfx('poof'), LIFT);
            }
        } catch (e) { }
    });
}

// Кнопки 📢 (объявления способностей) и 🎬 (анимации на доске)
function updateAnimUI() {
    const b1 = document.getElementById('btnBanner'), b2 = document.getElementById('btnAnim');
    if (b1) b1.classList.toggle('off', !ANIM.banner);
    if (b2) b2.classList.toggle('off', !ANIM.board);
}
const saveAnim = () => { try { localStorage.setItem('sc_anim', JSON.stringify(ANIM)); } catch (e) { } };
document.getElementById('btnBanner').addEventListener('click', () => { ANIM.banner = !ANIM.banner; saveAnim(); updateAnimUI(); });
document.getElementById('btnAnim').addEventListener('click', () => { ANIM.board = !ANIM.board; saveAnim(); updateAnimUI(); });
updateAnimUI();

// Красная обструкция: способность врага отключена на несколько его ходов
function doTomato(k) {
    if (!G.mode || G.mode.type !== 'tomato') return;
    const col = G.turn, en = other(col);
    if (!HEROES[G.hero[en]].abilities.includes(k)) return;
    if (G.disabled[en][k] > 0) return;      // в уже отключённую способность помидор не бросить
    const cdKey = G.mode.via || 'tomato';
    if (REPLAY_REC) REPLAY_REC.push({ k: 'tomato', col, en, key: k });
    const flight = tomatoPrepare(col, en, k);      // откуда и куда лететь (до перерисовки панелей)
    G.disabled[en][k] = CONFIG.tomatoTurns;
    G.cd[col][cdKey] = cdOf(col, cdKey);
    G.lastAb[col] = 'tomato';
    sfx('cast');
    abilityBanner('tomato');
    addLog(col, `🍅 Красная обструкция: способность «${ABILITIES[k].name}» врага отключена на ${CONFIG.tomatoTurns} ${plural(CONFIG.tomatoTurns)} (ход не потрачен)`);
    G.mode = null; G.sel = null; G.moves = [];
    render();      // ход не тратится
    tomatoFly(flight);
}

// Своя модель челюстей: pieces/jaws.png
(function () {
    if (typeof Image === 'undefined') return;
    const im = new Image();
    im.onload = () => { document.documentElement.style.setProperty('--img-jaws', 'url("pieces/jaws.png")'); if (document.body) document.body.classList.add('img-jaws'); };
    im.src = 'pieces/jaws.png';
})();

/* =====================================================================
   АККАУНТЫ (Supabase): вход, ник, рейтинг. Ключ ниже публичный (publishable).
   Ники и рейтинг хранятся в таблице profiles; менять рейтинг может только сервер.
   ===================================================================== */
const SUPA_URL = 'https://fuqopbjpxeugdvnlxanb.supabase.co';
const SUPA_KEY = 'sb_publishable_xVvPSDswx_P2D-kguqgznQ_5cjBAcMN';
let SB = null;
try { if (window.supabase && window.supabase.createClient) SB = window.supabase.createClient(SUPA_URL, SUPA_KEY); } catch (e) { SB = null; }
const ACC = { user: null, profile: null, needNick: false, loading: false };
let authMode = 'login';   // login | signup | nick
const NICK_RE = /^[\p{L}\p{N}_\- ]{3,16}$/u;
const authMsg = t => { $('#authMsg').textContent = t || ''; };

const peerText = () => (LANG === 'en' ? 'Opponent: ' : 'Соперник: ') + (NET.oppNick ? NET.oppNick + (NET.oppRating ? ' (⭐ ' + NET.oppRating + ')' : '') : (LANG === 'en' ? 'guest' : 'гость'));
function updatePeerLabel() {
    const el = $('#setupPeer');
    if (!el) return;
    const show = !!(NET.on && NET.peerKnown);
    el.classList.toggle('hidden', !show);
    el.classList.toggle('link', !!NET.oppId);
    if (show) el.textContent = peerText();
}
async function sendAuth() {
    if (!RELAY) return;      // токен отправляем только на наш сервер, никогда по PeerJS
    let token = '';
    try { if (SB) { const { data } = await SB.auth.getSession(); if (data && data.session) token = data.session.access_token; } } catch (e) { /* играем гостем */ }
    netSend({ t: 'auth', token });
}

function accRefresh() {
    const u = ACC.user, p = ACC.profile;
    const nm = $('#accName');
    nm.textContent = '';
    if (u) nm.append(avaNode(p && p.avatar), ' ' + (p ? p.nick : (u.email || '').split('@')[0]));
    nm.classList.toggle('hidden', !u);
    $('#accBtn').classList.toggle('hidden', !!u);
    $('#accOut').classList.toggle('hidden', !u);
    if (u && ACC.needNick && !p && $('#auth').classList.contains('hidden')) openAuth('nick');
}

async function loadProfile() {
    if (!SB || !ACC.user || ACC.loading) return;
    ACC.loading = true;
    const uid = ACC.user.id;
    const get = () => SB.from('profiles').select('nick,avatar').eq('id', uid).maybeSingle();
    try {
        let { data, error } = await get();
        if (error) throw error;
        if (!data) {                          // профиля ещё нет: пробуем ник, указанный при регистрации
            const want = ACC.user.user_metadata && ACC.user.user_metadata.nick;
            if (want) { const r = await SB.rpc('set_nick', { p_nick: want }); if (!r.error) { const g = await get(); data = g.data; } }
        }
        if (ACC.user && ACC.user.id === uid) { ACC.profile = data || null; ACC.needNick = !data; accRefresh(); }
    } catch (e) { /* без сети профиль не показываем, но и ник не просим */ }
    ACC.loading = false;
}

function openAuth(mode) {
    authMode = mode;
    const nick = mode === 'nick', signup = mode === 'signup', reset = mode === 'reset', newp = mode === 'newpass', cn = mode === 'changenick';
    $('#authTitle').textContent = cn ? 'Новый ник (1 🔮)' : nick ? 'Как вас называть?' : signup ? 'Регистрация' : reset ? 'Восстановление пароля' : newp ? 'Новый пароль' : 'Вход';
    $('#authGoogleBox').classList.toggle('hidden', nick || reset || newp || cn || !!window.Capacitor);   // в приложении вход через Google пока скрыт: Google не пускает во встроенный браузер
    $('#authEmail').classList.toggle('hidden', nick || newp || cn);
    $('#authPass').classList.toggle('hidden', nick || reset || cn);
    $('#authPass2').classList.toggle('hidden', !newp);
    $('#authNick').classList.toggle('hidden', !(nick || signup || cn));
    $('#authPass').autocomplete = (signup || newp) ? 'new-password' : 'current-password';
    $('#authPass').placeholder = newp ? L('Новый пароль (от 6 символов)', 'New password (6+ characters)') : L('Пароль (от 6 символов)', 'Password (6+ characters)');
    $('#authSubmit').textContent = cn ? 'Сменить ник за 🔮' : nick ? 'Сохранить ник' : signup ? 'Регистрация' : reset ? 'Отправить письмо' : newp ? 'Сохранить пароль' : 'Войти';
    $('#authSwitch').classList.toggle('hidden', nick || newp || cn);
    $('#authSwitch').textContent = signup ? 'Уже есть аккаунт? Войти' : reset ? 'Вспомнили пароль? Войти' : 'Нет аккаунта? Регистрация';
    $('#authForgot').classList.toggle('hidden', mode !== 'login');
    authMsg('');
    $('#auth').classList.remove('hidden');
}

function authError(err) {
    const m = String((err && err.message) || '');
    if (/no_orb/i.test(m)) return 'Для смены ника нужен 1 магический шар. Его дают после рейтинговой партии.';
    if (/reauthentication|reauth/i.test(m)) return 'Для смены пароля нужно войти заново. Выйдите и войдите снова или нажмите «Забыли пароль?».';
    if (/nick_taken/i.test(m)) return 'Этот ник уже занят, придумайте другой.';
    if (/bad_nick/i.test(m)) return 'Ник: 3–16 символов, буквы, цифры, пробел, _ и -.';
    if (/bad_avatar/i.test(m)) return 'Не удалось сменить аватар.';
    if (/not_authenticated/i.test(m)) return 'Нужен вход в аккаунт.';
    if (/invalid login/i.test(m)) return 'Неверная почта или пароль.';
    if (/already registered|already been registered/i.test(m)) return 'Эта почта уже зарегистрирована. Нажмите «Войти».';
    if (/not confirmed/i.test(m)) return 'Подтвердите почту по ссылке из письма, затем войдите.';
    if (/rate limit|too many/i.test(m)) return 'Слишком много попыток, подождите немного.';
    if (/at least 6/i.test(m)) return 'Пароль должен быть не короче 6 символов.';
    if (/different from the old|same as the old/i.test(m)) return 'Новый пароль должен отличаться от старого.';
    if (/session missing|expired|invalid.*token|otp/i.test(m)) return 'Ссылка устарела. Нажмите «Забыли пароль?» и запросите письмо заново.';
    return m || 'Не удалось выполнить вход. Попробуйте ещё раз.';
}

async function authSubmit() {
    if (!SB) { authMsg('Не загрузилась библиотека входа: проверьте интернет и обновите страницу.'); return; }
    const btn = $('#authSubmit');
    btn.disabled = true;
    try {
        if (authMode === 'nick') {
            const nick = $('#authNick').value.trim();
            if (!NICK_RE.test(nick)) { authMsg('Ник: 3–16 символов, буквы, цифры, пробел, _ и -.'); return; }
            const { error } = await SB.rpc('set_nick', { p_nick: nick });
            if (error) { authMsg(authError(error)); return; }
            ACC.needNick = false; ACC.loading = false;
            $('#auth').classList.add('hidden');
            await loadProfile();
            return;
        }
        if (authMode === 'changenick') {      // смена ника за 1 магический шар (всё проверяет и списывает сервер Supabase)
            const nick = $('#authNick').value.trim();
            if (!NICK_RE.test(nick)) { authMsg('Ник: 3–16 символов, буквы, цифры, пробел, _ и -.'); return; }
            if (ACC.profile && nick === ACC.profile.nick) { authMsg('Это ваш текущий ник.'); return; }
            if (!uiConfirm(`Сменить ник на «${nick}» за 1 магический шар? Шар будет потрачен.`)) return;
            const { error } = await SB.rpc('change_nick', { p_nick: nick });
            if (error) { authMsg(authError(error)); return; }
            $('#auth').classList.add('hidden');
            ACC.loading = false; await loadProfile(); await loadUnlocks();
            if (ACC.user) openProfile(ACC.user.id);
            return;
        }
        if (authMode === 'reset') {      // забыли пароль: письмо со ссылкой на новый пароль
            const mail = $('#authEmail').value.trim();
            if (!mail) { authMsg('Введите почту, на которую зарегистрирован аккаунт.'); return; }
            const { error } = await SB.auth.resetPasswordForEmail(mail, { redirectTo: location.origin + location.pathname });
            if (error) { authMsg(authError(error)); return; }
            authMsg('Если такая почта зарегистрирована, мы отправили письмо со ссылкой для нового пароля. Загляните и в «Спам».');
            return;
        }
        if (authMode === 'newpass') {      // пришли по ссылке из письма: задаём новый пароль
            const np = $('#authPass').value;
            if (np.length < 6) { authMsg('Пароль должен быть не короче 6 символов.'); return; }
            if (np !== $('#authPass2').value) { authMsg('Пароли не совпадают.'); return; }
            const { error } = await SB.auth.updateUser({ password: np });
            if (error) { authMsg(authError(error)); return; }
            $('#authPass').value = ''; $('#authPass2').value = '';
            $('#auth').classList.add('hidden');
            uiAlert('Пароль изменён.');
            return;
        }
        const email = $('#authEmail').value.trim(), pass = $('#authPass').value;
        if (!email || !pass) { authMsg('Введите почту и пароль.'); return; }
        if (authMode === 'signup') {
            const nick = $('#authNick').value.trim();
            if (!NICK_RE.test(nick)) { authMsg('Ник: 3–16 символов, буквы, цифры, пробел, _ и -.'); return; }
            if (pass.length < 6) { authMsg('Пароль должен быть не короче 6 символов.'); return; }
            const { data, error } = await SB.auth.signUp({ email, password: pass, options: { data: { nick }, emailRedirectTo: location.origin + location.pathname } });
            if (error) { authMsg(authError(error)); return; }
            if (data.session) $('#auth').classList.add('hidden');
            else authMsg('Письмо отправлено. Подтвердите почту по ссылке в письме и затем войдите.');
            return;
        }
        const { error } = await SB.auth.signInWithPassword({ email, password: pass });
        if (error) { authMsg(authError(error)); return; }
        $('#auth').classList.add('hidden');
    } catch (e) { authMsg('Не удалось выполнить вход. Попробуйте ещё раз.'); }
    finally { btn.disabled = false; }
}

const mkEl = (tag, cls, text, notr) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; if (notr) e.setAttribute('data-notr', ''); return e; };
const PLAYER_COLS = 'id,nick,avatar,wins,losses,draws,r_bullet,r_blitz,r_rapid,r_classic,g_bullet,g_blitz,g_rapid,g_classic';
let TOPMODE = 'blitz';

function renderPlayers(box, data) {
    box.textContent = '';
    if (!data.length) { box.textContent = 'Никого не нашли.'; return; }
    data.forEach((p, i) => {
        const row = mkEl('div', 'top-row link' + (ACC.user && ACC.user.id === p.id ? ' me' : ''));
        const n = mkEl('span', '', '', true);
        n.append(avaNode(p.avatar), ' ' + p.nick);
        row.append(mkEl('span', '', i + 1, true), n, mkEl('span', '', p['r_' + TOPMODE], true), mkEl('span', '', p['g_' + TOPMODE], true));
        row.addEventListener('click', () => openProfile(p.id));
        box.appendChild(row);
    });
}

async function openTop(query) {
    $('#top').classList.remove('hidden');
    document.querySelectorAll('#topTabs button').forEach(b => b.classList.toggle('on', b.dataset.mode === TOPMODE));
    const box = $('#topList');
    box.textContent = 'Загрузка...';
    if (!SB) { box.textContent = 'Не удалось загрузить рейтинг.'; return; }
    try {
        let q = SB.from('profiles').select(PLAYER_COLS).order('r_' + TOPMODE, { ascending: false }).limit(20);
        if (query) q = q.ilike('nick', '%' + query + '%'); else q = q.gt('g_' + TOPMODE, 0);
        const { data, error } = await q;
        if (error) throw error;
        if (!data.length && !query) { box.textContent = 'Пока никого нет.'; return; }
        renderPlayers(box, data);
    } catch (e) { box.textContent = 'Не удалось загрузить рейтинг.'; }
}
function findPlayers() { openTop($('#topSearch').value.trim().replace(/[%_,()*\\]/g, '')); }

/* ---------- Профиль игрока: статистика, график рейтинга, история партий ---------- */
// Аватар: либо смайлик, либо картинка-достижение вида «ach:beta» (картинка берётся из описания достижения)
function avaNode(avatar) {
    if (typeof avatar === 'string' && avatar.startsWith('ach:')) {
        const d = ACH[avatar.slice(4)];
        if (d && d.img) { const im = document.createElement('img'); im.src = d.img; im.alt = d.name; im.className = 'ava-img'; return im; }
    }
    return document.createTextNode(avatar && !String(avatar).startsWith('ach:') ? avatar : '👤');
}
const ACH = { beta: { name: 'Бета-тестер', desc: 'Участвовал в бета-тестировании SpellsChess', img: 'achievements/beta.png' } };
const heroLabel = id => (HEROES[id] ? HEROES[id].icon + ' ' + HEROES[id].name : '—');
const AVATARS = [...new Set([...Object.values(HEROES).map(h => h.icon), '😎', '😀', '😈', '🤖', '👽', '👻', '💀', '🤡', '🦊', '🐺', '🦁', '🐯', '🐼', '🐸', '🐵', '🦉', '🦅', '🐙', '🦇', '🐉', '🐲', '🦄', '🧙', '🧛', '🧟', '🥷', '🧝', '🧞', '🎭', '🎩', '👑', '🎲', '♟️', '🏆', '💎', '🔮', '🪄', '🗡️', '🛡️', '🏹', '🔥', '❄️', '⚡', '🌙', '☀️', '🌈', '🍀', '🍕', '🍩', '🚀', '🛸', '🎯', '🧿'])];

async function openProfile(uid, selMode) {
    if (!SB || !/^[0-9a-f-]{36}$/i.test(uid || '')) return;
    $('#prof').classList.remove('hidden');
    const gl = $('#profGames');
    $('#profNick').textContent = '…'; $('#profAva').textContent = ''; $('#profSub').textContent = '';
    $('#profStats').textContent = ''; $('#profGraph').innerHTML = '';
    $('#profAvaPick').classList.add('hidden'); $('#profAvaBtn').classList.add('hidden');
    $('#profDelBtn').classList.add('hidden'); $('#profBlockBtn').classList.add('hidden'); $('#profNickBtn').classList.add('hidden'); $('#profPassBtn').classList.add('hidden');
    gl.textContent = 'Загрузка...';
    try {
        const pr = await SB.from('profiles').select(PLAYER_COLS + ',created_at').eq('id', uid).maybeSingle();
        if (pr.error) throw pr.error;
        const p = pr.data;
        if (!p) { $('#profNick').textContent = ''; gl.textContent = 'Игрок не найден.'; return; }
        const gm = await SB.from('games').select('id,white,black,result,created_at,white_hero,black_hero,white_delta,black_delta,reason,moves,rated,seed,mode')
            .or(`white.eq.${uid},black.eq.${uid}`).order('created_at', { ascending: false }).limit(30);
        if (gm.error) throw gm.error;
        const games = gm.data || [];
        const oppIds = [...new Set(games.map(g => (g.white === uid ? g.black : g.white)))];
        const names = {};
        if (oppIds.length) { const o = await SB.from('profiles').select('id,nick,avatar').in('id', oppIds); (o.data || []).forEach(x => { names[x.id] = x; }); }

        $('#profNick').textContent = p.nick;
        $('#profAva').textContent = '';
        $('#profAva').appendChild(avaNode(p.avatar));
        $('#profSub').textContent = p.created_at ? (LANG === 'en' ? 'Joined ' : 'На сайте с ') + new Date(p.created_at).toLocaleDateString() : '';
        const mine = ACC.user && ACC.user.id === uid;
        $('#profAvaBtn').classList.toggle('hidden', !mine);
        PROF.uid = uid;
        $('#profDelBtn').classList.toggle('hidden', !mine);
        $('#profNickBtn').classList.toggle('hidden', !mine); $('#profPassBtn').classList.toggle('hidden', !mine);
        $('#profBlockBtn').classList.toggle('hidden', !!mine);
        $('#profBlockBtn').textContent = isBlocked(uid) ? '✅ Разблокировать' : '🚫 Заблокировать';

        // Достижения
        const achBox = $('#profAch'); achBox.textContent = ''; $('#profAchH').classList.add('hidden');
        try {
            const ar = await SB.from('user_achievements').select('ach').eq('user_id', uid);
            (ar.data || []).forEach(x => {
                const d = ACH[x.ach];
                if (!d) return;
                const bx = mkEl('div', 'ach');
                bx.title = d.name + ' — ' + d.desc;
                const im = document.createElement('img');
                im.src = d.img; im.alt = d.name;
                bx.append(im, mkEl('span', '', d.name));
                achBox.appendChild(bx);
                $('#profAchH').classList.remove('hidden');
            });
        } catch (e) { /* достижения необязательны */ }

        // Рейтинги: у каждого режима свой; нажатие на режим показывает его график
        const keys = Object.keys(MODES);
        const sel = (selMode && MODES[selMode]) ? selMode : keys.slice().sort((a, b) => p['g_' + b] - p['g_' + a])[0] && p['g_' + keys.slice().sort((a, b) => p['g_' + b] - p['g_' + a])[0]] > 0 ? keys.slice().sort((a, b) => p['g_' + b] - p['g_' + a])[0] : 'blitz';
        const stats = $('#profStats');
        keys.forEach(k => {
            const d = mkEl('div', 'stat-box mode-box' + (k === sel ? ' sel' : ''));
            d.append(mkEl('b', '', p['r_' + k], true), mkEl('span', '', modeName(k) + ' · ' + p['g_' + k], true));
            d.addEventListener('click', () => openProfile(uid, k));
            stats.appendChild(d);
        });
        const total = p.wins + p.losses + p.draws;
        const heroCount = {};
        games.forEach(g => { const hid = g.white === uid ? g.white_hero : g.black_hero; if (hid) heroCount[hid] = (heroCount[hid] || 0) + 1; });
        const fav = Object.keys(heroCount).sort((a, b) => heroCount[b] - heroCount[a])[0];
        const box = (label, val, notr) => { const d = mkEl('div', 'stat-box'); d.append(mkEl('b', '', val, notr), mkEl('span', '', label)); return d; };
        stats.append(box('Партий', total, true), box('Побед %', total ? Math.round(100 * p.wins / total) + '%' : '—', true), box('Любимый герой', fav ? heroLabel(fav) : '—'));

        // График выбранного режима: идём от текущего значения назад по изменениям
        const deltaOf = g => (g.white === uid ? g.white_delta : g.black_delta) || 0;
        const ratings = [p['r_' + sel]];
        games.filter(g => g.mode === sel).forEach(g => { ratings.unshift(ratings[0] - deltaOf(g)); });
        if (ratings.length > 1) {
            const lo = Math.min(...ratings), hi = Math.max(...ratings), span = Math.max(hi - lo, 10);
            const pts = ratings.map((v, i) => `${(i / (ratings.length - 1)) * 292 + 4},${62 - ((v - lo) / span) * 54 + 4}`).join(' ');
            $('#profGraph').innerHTML = `<polyline points="${pts}"/>`;
        }

        // История партий
        gl.textContent = '';
        if (!games.length) gl.textContent = 'Партий пока нет.';
        games.forEach(g => {
            const my = g.white === uid, oppId = my ? g.black : g.white, opp = names[oppId];
            const res = g.result === 'd' ? 'd' : ((g.result === 'w') === my ? 'w' : 'l');
            const d = my ? g.white_delta : g.black_delta;
            const row = mkEl('div', 'game-row ' + res);
            const oppEl = mkEl('span', 'opp-link', '', true);
            if (opp) oppEl.append(avaNode(opp.avatar), ' ' + opp.nick); else oppEl.textContent = '?';
            oppEl.addEventListener('click', () => openProfile(oppId));
            row.append(
                mkEl('span', '', new Date(g.created_at).toLocaleDateString(), true),
                oppEl,
                mkEl('span', 'badge', res === 'w' ? 'Победа' : res === 'l' ? 'Поражение' : 'Ничья'),
                mkEl('span', 'delta', d == null ? '' : (d > 0 ? '+' : '') + d, true)
            );
            const sub = mkEl('span', 'game-sub');
            sub.append(mkEl('span', '', heroLabel(my ? g.white_hero : g.black_hero) + ' vs ' + heroLabel(my ? g.black_hero : g.white_hero)));
            if (g.mode) sub.append(mkEl('span', '', ' · ' + modeName(g.mode), true));
            else if (g.rated === false) sub.append(mkEl('span', 'tag-friendly', ' · Дружеская'));
            if (g.reason) sub.append(mkEl('span', '', ' · ' + g.reason));
            if (g.moves) sub.append(mkEl('span', '', ' · ' + g.moves + (LANG === 'en' ? ' moves' : ' ходов'), true));
            if (g.seed != null) {
                const wn = my ? p.nick : (opp ? opp.nick : '?'), bn = my ? (opp ? opp.nick : '?') : p.nick;
                const rb = mkEl('button', 'small-btn rp-btn', '▶ Повтор');
                rb.addEventListener('click', () => watchReplay(g.id, wn + ' ⚔ ' + bn));
                sub.append(rb);
            }
            row.appendChild(sub);
            gl.appendChild(row);
        });
    } catch (e) { gl.textContent = 'Не удалось загрузить профиль.'; }
}

async function openAvatarPick() {
    const box = $('#profAvaPick');
    if (!box.classList.contains('hidden')) { box.classList.add('hidden'); return; }
    box.textContent = '';
    // картинки-достижения, которые есть у игрока (любое достижение с картинкой подходит автоматически)
    let owned = [];
    try {
        const r = await SB.from('user_achievements').select('ach').eq('user_id', ACC.user.id);
        owned = (r.data || []).map(x => x.ach).filter(a => ACH[a] && ACH[a].img).map(a => 'ach:' + a);
    } catch (e) { /* останутся только смайлики */ }
    [...owned, ...AVATARS].forEach(a => {
        const b = document.createElement('button');
        b.setAttribute('data-notr', '');
        b.appendChild(avaNode(a));
        if (a.startsWith('ach:')) { b.classList.add('ava-ach'); b.title = ACH[a.slice(4)].name; }
        b.addEventListener('click', async () => {
            const { error } = await SB.rpc('set_avatar', { p_avatar: a });
            if (error) { uiAlert(authError(error)); return; }
            ACC.loading = false; await loadProfile();
            if (ACC.user) openProfile(ACC.user.id);
        });
        box.appendChild(b);
    });
    box.classList.remove('hidden');
}

