{
    const standalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || navigator.standalone;
    if (/iphone|ipad|ipod/i.test(navigator.userAgent) && !standalone && !window.Capacitor) $('#iosHint').classList.remove('hidden');
    if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol) && !window.Capacitor) navigator.serviceWorker.register('sw.js').catch(() => { });
}

/* =====================================================================
   РЕДАКТОР ДОСКИ (режим «своя доска»)
   Фигуры хранятся строками: заглавные буквы белые фигуры, строчные чёрные, точка пустая клетка.
   Плитки хранятся списком: { k: вид, r, c, o: владелец, d: направление, id: пара портала, s: знак генератора }.
   ===================================================================== */
const BOARD_SLOTS = 10;
const ED_CH = '.KQRBNPJXkqrbnpjx';      // X/x: роботы Инженера (правила лежат в cfg.robs)
//      // J/j: заводные челюсти без таймера жизни
const CLASSIC_ROWS = ['rnbqkbnr', 'pppppppp', '........', '........', '........', '........', 'PPPPPPPP', 'RNBQKBNR'];
const chColor = ch => (ch === ch.toUpperCase() ? 'w' : 'b');
const swapCase = ch => (ch === ch.toUpperCase() ? ch.toLowerCase() : ch.toUpperCase());
const ROOMBOARD = { mode: 'classic', cfg: null }, LOCALBOARD = { mode: 'classic', cfg: null };
const ROOMCOLOR = { v: 'r' };      // цвет хозяина комнаты: 'w', 'b' или 'r' (случайный, по умолчанию)
try { const sc = localStorage.getItem('sc_roomcolor'); if (sc === 'w' || sc === 'b' || sc === 'r') ROOMCOLOR.v = sc; } catch (e) { }

const TILE_KINDS = ['wall', 'conv', 'portal', 'gen', 'virus', 'vine', 'ritual', 'hatch', 'trap', 'lure', 'banana', 'burn', 'hog', 'fog', 'charger'];
const TILE_DIRS = { '-1,0': '⬆', '1,0': '⬇', '0,-1': '⬅', '0,1': '➡' };
// Что показывается в панели плиток. own: у плитки есть владелец; dir: нужно направление; pair: пара портала
const TILE_PALETTE = [
    { id: 'wall', k: 'wall', ico: '🧱', ru: 'Стена', en: 'Wall' },
    { id: 'conv', k: 'conv', ico: '➡', ru: 'Конвейер', en: 'Conveyor', own: true, dir: true },
    { id: 'portal', k: 'portal', ico: '🌀', ru: 'Портал (пара)', en: 'Portal (pair)', own: true, pair: true },
    { id: 'gen+', k: 'gen', s: '+', ico: '＋', ru: 'Генератор +', en: 'Generator +', own: true },
    { id: 'gen-', k: 'gen', s: '-', ico: '－', ru: 'Генератор −', en: 'Generator −', own: true },
    { id: 'virus', k: 'virus', ico: '☣️', ru: 'Заражённая плитка', en: 'Infected tile', own: true },
    { id: 'vine', k: 'vine', ico: '🌿', ru: 'Лоза', en: 'Vine', own: true },
    { id: 'ritual', k: 'ritual', ico: '🕯️', ru: 'Ритуал', en: 'Ritual', own: true, neu: true },
    { id: 'hatch', k: 'hatch', ico: '🪵', ru: 'Потайной люк', en: 'Trapdoor', own: true },
    { id: 'trap', k: 'trap', ico: '🪤', ru: 'Капкан', en: 'Snare', own: true, neu: true },
    { id: 'lure', k: 'lure', ico: '🎣', ru: 'Приманка', en: 'Lure', own: true, neu: true },
    { id: 'banana', k: 'banana', ico: '🍌', ru: 'Банан', en: 'Banana', own: true, neu: true, dir: true },
    { id: 'burn', k: 'burn', ico: '🔥', ru: 'Горящая клетка', en: 'Burning square', own: true },
    { id: 'hog', k: 'hog', ico: '⏳', ru: 'Ход сурка', en: 'Groundhog tile', own: true },
    { id: 'charger', k: 'charger', ico: '🔋', ru: 'Плитка-зарядка', en: 'Charger tile', own: true },
    { id: 'fog', k: 'fog', ico: '🌫️', ru: 'Дым (поверх всего)', en: 'Smoke (over anything)', own: true }
];

// Проверка и приведение доски к единому виду (годится и для данных от соперника)
const MAX_N = 16;      // самый большой размер доски
function normCfg(x) {
    if (!x || !Array.isArray(x.rows) || x.rows.length < 8 || x.rows.length > MAX_N) return null;
    const sz = x.rows.length;
    const rows = [], n = { w: 0, b: 0, kw: 0, kb: 0 };
    for (let r = 0; r < sz; r++) {
        const row = x.rows[r];
        if (typeof row !== 'string' || row.length !== sz) return null;
        for (let c = 0; c < sz; c++) {
            const ch = row[c];
            if (!ED_CH.includes(ch)) return null;
            if ((ch === 'P' || ch === 'p') && (r === 0 || r === sz - 1)) return null;
            if (ch === '.') continue;
            const sd = chColor(ch);
            n[sd]++;
            if (ch.toLowerCase() === 'k') n['k' + sd]++;
        }
        rows.push(row);
    }
    if (!n.w || !n.b) return null;
    const tiles = [], base = new Set(), fogs = new Set(), pairs = {};
    for (const t of (Array.isArray(x.tiles) ? x.tiles.slice(0, 200) : [])) {
        if (!t || !TILE_KINDS.includes(t.k) || !Number.isInteger(t.r) || !Number.isInteger(t.c) || t.r < 0 || t.r >= sz || t.c < 0 || t.c >= sz) return null;
        const key = t.r + ',' + t.c, o = t.o === 'b' ? 'b' : (t.o === 'n' && ['ritual', 'trap', 'lure', 'banana'].includes(t.k)) ? 'n' : 'w', nt = { k: t.k, r: t.r, c: t.c, o };
        if (t.k === 'fog') { if (fogs.has(key)) return null; fogs.add(key); tiles.push(nt); continue; }
        if (base.has(key)) return null;
        base.add(key);
        if (t.k === 'wall' && rows[t.r][t.c] !== '.') return null;
        if (t.k === 'conv' || t.k === 'banana') {
            if (!Array.isArray(t.d) || !TILE_DIRS[t.d.join(',')]) return null;
            nt.d = [t.d[0], t.d[1]];
        }
        if (t.k === 'gen') { if (t.s !== '+' && t.s !== '-') return null; nt.s = t.s; }
        if (t.k === 'portal') {
            if (!Number.isInteger(t.id) || t.id < 1 || t.id > 4) return null;
            nt.id = t.id; nt.o = t.id <= 2 ? 'w' : 'b';
            pairs[t.id] = (pairs[t.id] || 0) + 1;
        }
        tiles.push(nt);
    }
    if (Object.values(pairs).some(v => v !== 2)) return null;      // у портала должна быть ровно одна пара
    const robs = [], robKey = new Set();
    for (const o of (Array.isArray(x.robs) ? x.robs.slice(0, 100) : [])) {
        if (!o || !Number.isInteger(o.r) || !Number.isInteger(o.c) || o.r < 0 || o.r >= sz || o.c < 0 || o.c >= sz) return null;
        if (!'Xx'.includes(rows[o.r][o.c])) return null;
        const key = o.r + ',' + o.c;
        if (robKey.has(key)) return null;
        robKey.add(key);
        const rb = normRob(o.rob, sz);
        if (!rb) return null;
        robs.push({ r: o.r, c: o.c, rob: rb });
    }
    for (let r = 0; r < sz; r++) for (let c = 0; c < sz; c++) if ('Xx'.includes(rows[r][c]) && !robKey.has(r + ',' + c)) return null;      // у каждого робота должны быть правила
    const win = {};
    ['w', 'b'].forEach(sd => {
        const k = n['k' + sd];
        win[sd] = k === 0 ? 'all' : (x.win && x.win[sd] === 'all' ? 'all' : 'mate');
    });
    return { v: 2, size: sz, plain: !!x.plain, name: String(x.name || '').slice(0, 20), rows, tiles, robs, win };
}
// Правила робота из редактора (или от соперника): строгая проверка
function normRob(rb, sz) {
    if (!rb || typeof rb !== 'object') return null;
    const dirs = (a, lim, max) => {
        if (!Array.isArray(a) || a.length > max) return null;
        const out = [], seen = new Set();
        for (const d of a) {
            if (!Array.isArray(d) || d.length !== 2 || !d.every(v => Number.isInteger(v) && Math.abs(v) <= lim) || (!d[0] && !d[1])) return null;
            const k = d[0] + ',' + d[1];
            if (seen.has(k)) return null;
            seen.add(k); out.push([d[0], d[1]]);
        }
        return out;
    };
    if (rb.kind === 'wing') {
        const ja = dirs(rb.ja, 2, ENG_MAX_JUMP), jw = dirs(rb.jw, 2, ENG_MAX_JUMP);
        if (!ja || !jw || !ja.length || ja.length + jw.length > ENG_MAX_JUMP) return null;
        if (jw.some(d => ja.some(e => e[0] === d[0] && e[1] === d[1]))) return null;
        return { kind: 'wing', ja, jw };
    }
    if (rb.kind === 'boot') {
        const walk = dirs(rb.walk, 1, 8), atk = dirs(rb.atk, 1, 8);
        if (!walk || !atk || walk.length + atk.length < 1) return null;
        if (!Number.isInteger(rb.wr) || rb.wr < 1 || rb.wr > sz - 1 || !Number.isInteger(rb.ar) || rb.ar < 1 || rb.ar > sz - 1) return null;
        return { kind: 'boot', walk, atk, wr: rb.wr, ar: rb.ar };
    }
    return null;
}

function boardFromCfg(cfg) {
    return cfg.rows.map((row, r) => [...row].map((ch, c) => {
        if (ch === '.') return null;
        const col = chColor(ch), t = ch.toLowerCase(), p = mk(t, col), home = col === 'w' ? cfg.rows.length - 1 : 0, std = cfg.rows.length === 8;      // рокировка только на доске 8×8
        if (t === 'k') p.moved = !(std && r === home && c === 4);                     // рокировка возможна, только если король и ладья на своих местах
        if (t === 'r') p.moved = !(std && r === home && (c === 0 || c === 7));
        if (t === 'j') { p.moved = true; p.life = Infinity; }      // челюсти из редактора живут всю партию
        if (t === 'x') { p.moved = true; const o = (cfg.robs || []).find(q => q.r === r && q.c === c); if (o) p.rob = JSON.parse(JSON.stringify(o.rob)); }      // робот Инженера со своими правилами
        return p;
    }));
}

// Расставляет плитки из редактора по состоянию партии
function installTiles(g, cfg) {
    let maxId = 0;
    (cfg.tiles || []).forEach(t => {
        const b = { r: t.r, c: t.c, owner: t.o };
        switch (t.k) {
            case 'wall': g.walls.push({ r: t.r, c: t.c }); break;
            case 'conv': g.conv.push({ ...b, dir: [...t.d] }); break;
            case 'portal': g.portals.push({ ...b, id: t.id }); maxId = Math.max(maxId, t.id); break;
            case 'gen': g.gens.push({ ...b, sign: t.s }); break;
            case 'virus': g.virus.push(b); break;
            case 'vine': g.vines.push({ ...b, left: Infinity }); break;
            case 'ritual': g.rituals.push(b); break;
            case 'hatch': g.hatches.push(b); break;
            case 'trap': g.traps.push(b); break;
            case 'lure': g.lureCells.push(b); break;
            case 'banana': g.bananas.push({ ...b, dir: [...t.d] }); break;
            case 'burn': g.burn.push({ ...b, life: Infinity }); break;
            case 'hog': g.hogs.push({ ...b, exempt: null, visible: true }); break;
            case 'fog': g.fogs.push({ ...b, left: Infinity }); break;
            case 'charger': if (!g.chargers) g.chargers = []; g.chargers.push({ r: t.r, c: t.c, owner: t.o }); break;
        }
    });
    if (maxId) g.nextPortal = maxId + 1;
}

function loadSlots() {
    let a = [];
    try { a = JSON.parse(localStorage.getItem('sc_boards') || '[]'); } catch (e) { }
    return Array.from({ length: BOARD_SLOTS }, (_, i) => normCfg(a[i]));
}
function saveSlots(list) { try { localStorage.setItem('sc_boards', JSON.stringify(list)); } catch (e) { } }
const cfgPieceCount = cfg => cfg.rows.join('').replace(/\./g, '').length;
const cfgTileCount = cfg => (cfg.tiles || []).length;

// ---------- состояние редактора ----------
const ED = { n: 8, plain: false, rows: null, tiles: [], robs: [], tool: 'P', tab: 'pieces', tileId: 'wall', opt: { o: 'w', d: [1, 0], pair: 1 }, mirror: 0, slot: 0, win: { w: null, b: null }, onPick: null, msg: '', slots: [] };
const edSideName = sd => (sd === 'w' ? L('белых', 'White') : L('чёрных', 'Black'));
const edBaseAt = (r, c) => ED.tiles.find(t => t.r === r && t.c === c && t.k !== 'fog');
const edFogAt = (r, c) => ED.tiles.find(t => t.r === r && t.c === c && t.k === 'fog');

function edCounts() {
    const n = { w: { n: 0, k: 0 }, b: { n: 0, k: 0 } };
    ED.rows.forEach(row => row.forEach(ch => {
        if (ch === '.') return;
        const sd = chColor(ch);
        n[sd].n++;
        if (ch.toLowerCase() === 'k') n[sd].k++;
    }));
    return n;
}
function edCfg() {
    const cnt = edCounts(), win = {};
    ['w', 'b'].forEach(sd => { win[sd] = cnt[sd].k === 0 ? 'all' : (ED.win[sd] === 'all' ? 'all' : 'mate'); });
    return { v: 2, size: ED.n, plain: !!ED.plain, name: $('#edName').value.trim().slice(0, 20), rows: ED.rows.map(r => r.join('')), tiles: ED.tiles.map(t => ({ ...t, d: t.d ? [...t.d] : undefined })), robs: ED.robs.map(o => ({ r: o.r, c: o.c, rob: JSON.parse(JSON.stringify(o.rob)) })), win };
}

function edOpen(onPick, cfg) {
    const base = cfg || { rows: CLASSIC_ROWS, tiles: [], win: { w: null, b: null }, name: '' };
    ED.n = base.rows.length;
    ED.plain = !!base.plain;
    ED.rows = base.rows.map(r => [...r]);
    ED.tiles = (base.tiles || []).map(t => ({ ...t, d: t.d ? [...t.d] : undefined }));
    ED.robs = (base.robs || []).map(o => ({ r: o.r, c: o.c, rob: JSON.parse(JSON.stringify(o.rob)) }));
    ED.win = { w: null, b: null };
    const cnt = edCounts();
    ['w', 'b'].forEach(sd => { if (cnt[sd].k >= 1 && base.win && base.win[sd]) ED.win[sd] = base.win[sd]; });
    ED.onPick = onPick; ED.msg = ''; ED.slots = loadSlots();
    $('#edName').value = base.name || '';
    $('#editor').classList.remove('hidden');
    edRender();
}

// Значок плитки в клетке редактора (те же классы, что и в игре)
function edTileHtml(t) {
    const own = (t.o === 'b' ? ' ed-b' : '');
    switch (t.k) {
        case 'wall': return '<div class="wall-mark"></div>';
        case 'conv': return `<div class="conv-mark">${TILE_DIRS[t.d.join(',')]}</div><span class="ed-own ${t.o}"></span>`;
        case 'portal': return `<div class="portal-mark pm${(t.o === 'w' ? 0 : 2) + t.id % 2}"><span>⇄</span></div><span class="ed-own ${t.o}"></span>`;
        case 'gen': return `<div class="tile-mark gen-mark ${t.s === '+' ? 'plus' : 'minus'}">${t.s === '+' ? '＋' : '－'}</div><span class="ed-own ${t.o}"></span>`;
        case 'virus': return `<div class="tile-mark virus-mark">☣️</div><span class="ed-own ${t.o}"></span>`;
        case 'vine': return `<div class="tile-mark vine-mark">🌿<i class="vine-t">∞</i></div><span class="ed-own ${t.o}"></span>`;
        case 'ritual': return `<div class="tile-mark ritual-mark${t.o === 'b' ? ' enemy' : t.o === 'n' ? ' neutral' : ''}">🕯️</div><span class="ed-own ${t.o}"></span>`;
        case 'hatch': return `<div class="tile-mark hatch-mark"><span></span></div><span class="ed-own ${t.o}"></span>`;
        case 'trap': return `<div class="trap-mark">🪤</div><span class="ed-own ${t.o}"></span>`;
        case 'lure': return `<div class="lure-mark">🎣</div><span class="ed-own ${t.o}"></span>`;
        case 'banana': return `<div class="tile-mark banana-mark">🍌<i>${TILE_DIRS[t.d.join(',')]}</i></div><span class="ed-own ${t.o}"></span>`;
        case 'burn': return `<div class="burn-mark"><span>🔥</span><i>∞</i></div><span class="ed-own ${t.o}"></span>`;
        case 'hog': return `<div class="tile-mark hog-mark">⏳</div><span class="ed-own ${t.o}"></span>`;
        case 'fog': return `<div class="fog-mark"></div><span class="ed-own ${t.o}"></span>`;
        case 'charger': return `<div class="tile-mark charger-mark ${t.o}"><span>⚡</span></div><span class="ed-own ${t.o}"></span>`;
    }
    return '';
}

// Смена размера доски: верх и низ расстановки остаются у своих краёв, по горизонтали всё центрируется
function edResize(nn) {
    if (nn === ED.n) return;
    const o = ED.n, half = Math.floor(Math.min(o, nn) / 2), off = Math.floor((nn - o) / 2);
    const mapR = r => (r < half ? r : (r >= nn - half ? r - (nn - o) : -1));
    const rows = Array.from({ length: nn }, () => Array(nn).fill('.'));
    for (let r = 0; r < nn; r++) for (let c = 0; c < nn; c++) {
        const or = mapR(r), oc = c - off;
        if (or >= 0 && or < o && oc >= 0 && oc < o) rows[r][c] = ED.rows[or][oc];
    }
    const inv = r => { for (let q = 0; q < nn; q++) if (mapR(q) === r) return q; return -1; };
    const tiles = [];
    ED.tiles.forEach(t => { const nr = inv(t.r), nc = t.c + off; if (nr >= 0 && nc >= 0 && nc < nn) tiles.push({ ...t, r: nr, c: nc, d: t.d ? [...t.d] : undefined }); });
    const robs = [];
    ED.robs.forEach(o => { const nr = inv(o.r), nc = o.c + off; if (nr >= 0 && nc >= 0 && nc < nn) robs.push({ r: nr, c: nc, rob: o.rob }); });
    ED.n = nn; ED.rows = rows; ED.tiles = tiles; ED.robs = robs; ED.msg = ''; edFixWin(); edRender();
}
function edRender() {
    for (let r = 0; r < ED.n; r++) for (let c = 0; c < ED.n; c++) if ('Xx'.includes(ED.rows[r][c]) && !ED.robs.some(o => o.r === r && o.c === c)) ED.rows[r][c] = '.';      // робот без правил не бывает
    ED.robs = ED.robs.filter(o => ED.rows[o.r] && 'Xx'.includes(ED.rows[o.r][o.c]));
    $('#edBoard').style.setProperty('--en', ED.n);
    $('#edPlain').checked = !!ED.plain;
    $('#edSize').innerHTML = [8, 10, 12, 14, 16].map(v => `<button data-sz="${v}" class="${ED.n === v ? 'on' : ''}">${v}×${v}</button>`).join('');
    // доска
    let h = '';
    for (let r = 0; r < ED.n; r++) for (let c = 0; c < ED.n; c++) {
        const ch = ED.rows[r][c];
        h += `<div class="cell ${(r + c) % 2 ? 'dark' : 'light'}" data-r="${r}" data-c="${c}">`;
        if (c === 0) h += `<span class="coord rank">${ED.n - r}</span>`;
        if (r === ED.n - 1) h += `<span class="coord file">${FILES[c]}</span>`;
        const bt = edBaseAt(r, c);
        if (bt) h += edTileHtml(bt);
        if (ch !== '.') h += `<div class="piece ${chColor(ch)} t-${ch.toLowerCase()}">${GLYPH[ch.toLowerCase()]}${'Xx'.includes(ch) ? `<span class="ed-rb">${(ED.robs.find(o => o.r === r && o.c === c) || { rob: {} }).rob.kind === 'wing' ? '🪽' : '👢'}</span>` : ''}</div>`;
        const ft = edFogAt(r, c);
        if (ft) h += edTileHtml(ft);
        h += '</div>';
    }
    $('#edBoard').innerHTML = h;
    // вкладки
    $('.ed-tabs').querySelectorAll('button').forEach(b => b.classList.toggle('on', b.dataset.tab === ED.tab));
    $('#edPalette').classList.toggle('hidden', ED.tab !== 'pieces');
    $('#edTilePanel').classList.toggle('hidden', ED.tab !== 'tiles');
    // фигуры для расстановки
    const nm = { k: L('король', 'king'), q: L('ферзь', 'queen'), r: L('ладья', 'rook'), b: L('слон', 'bishop'), n: L('конь', 'knight'), p: L('пешка', 'pawn'), j: L('заводные челюсти (без таймера)', 'windup jaws (no timer)'), x: L('робот Инженера (настраивается на планшете, нажмите на робота на доске, чтобы перенастроить)', 'Engineer robot (set up on a tablet; click a robot on the board to reconfigure)') };
    let p = '';
    ['K', 'Q', 'R', 'B', 'N', 'P', 'J', 'X', 'k', 'q', 'r', 'b', 'n', 'p', 'j', 'x'].forEach(ch => {
        p += `<button class="ed-tool${ED.tab === 'pieces' && ED.tool === ch ? ' on' : ''}" data-tool="${ch}" title="${(chColor(ch) === 'w' ? L('Белая ', 'White ') : L('Чёрная ', 'Black ')) + nm[ch.toLowerCase()]}">${pImg(chColor(ch), ch.toLowerCase())}</button>`;
    });
    p += `<button class="ed-tool erase${ED.tool === '.' ? ' on' : ''}" data-tool="." title="${L('Ластик: сначала убирает дым, потом фигуру, потом плитку', 'Eraser: removes smoke first, then the piece, then the tile')}">✖</button>`;
    $('#edPalette').innerHTML = p;
    // плитки
    const cur = TILE_PALETTE.find(x => x.id === ED.tileId);
    let tp = TILE_PALETTE.map(x => `<button class="ed-tile${ED.tab === 'tiles' && ED.tileId === x.id ? ' on' : ''}" data-tile="${x.id}" title="${L(x.ru, x.en)}"><span>${x.ico}</span><b>${L(x.ru, x.en)}</b></button>`).join('');
    tp += `<button class="ed-tile erase${ED.tool === '.' ? ' on' : ''}" data-tool="." title="${L('Ластик', 'Eraser')}"><span>✖</span><b>${L('Ластик', 'Eraser')}</b></button>`;
    $('#edTiles').innerHTML = tp;
    let op = '';
    if (cur.own && !cur.pair) op += `<div class="ed-optrow"><span>${L('Владелец:', 'Owner:')}</span>` + (cur.neu ? ['w', 'b', 'n'] : ['w', 'b']).map(o => `<button class="${(ED.opt.o === 'n' && !cur.neu ? 'w' : ED.opt.o) === o ? 'on' : ''}" data-o="${o}">${o === 'w' ? L('⬜ Белые', '⬜ White') : o === 'b' ? L('⬛ Чёрные', '⬛ Black') : L('⚪ Нейтральная', '⚪ Neutral')}</button>`).join('') + '</div>';
    if (cur.dir) op += `<div class="ed-optrow"><span>${L('Направление:', 'Direction:')}</span>` + Object.entries(TILE_DIRS).map(([k, a]) => `<button class="${ED.opt.d.join(',') === k ? 'on' : ''}" data-d="${k}">${a}</button>`).join('') + '</div>';
    if (cur.pair) {
        op += `<div class="ed-optrow"><span>${L('Пара:', 'Pair:')}</span>` + [1, 2, 3, 4].map(i => `<button class="${ED.opt.pair === i ? 'on' : ''}" data-pair="${i}">${i <= 2 ? '⬜' : '⬛'}${i <= 2 ? i : i - 2}</button>`).join('') + '</div>';
        op += `<div class="ed-hint">${L('Порталы ставятся по два на пару (⬜ белых и ⬛ чёрных пар по две). На порталы зеркало не действует.', 'Portals come two to a pair (two ⬜ white and two ⬛ black pairs). Mirror does not affect portals.')}</div>`;
    }
    $('#edTileOpts').innerHTML = op;
    $('#edMirror').querySelectorAll('button').forEach(b => b.classList.toggle('on', +b.dataset.m === ED.mirror));
    // слоты
    $('#edSlots').innerHTML = ED.slots.map((cfg, i) => `<button class="ed-slot${ED.slot === i ? ' on' : ''}" data-slot="${i}"><b>${L('Слот', 'Slot')} ${i + 1}</b><span>${cfg ? ((cfg.name || L('без названия', 'untitled')).replace(/</g, '&lt;') + ' · ' + cfgPieceCount(cfg) + (cfgTileCount(cfg) ? ' + ' + cfgTileCount(cfg) : '')) : L('пусто', 'empty')}</span></button>`).join('');
    // условия победы
    const cnt = edCounts();
    let w = '', need = false;
    ['w', 'b'].forEach(sd => {
        const who = sd === 'w' ? L('Белых', 'White') : L('Чёрных', 'Black'), k = cnt[sd].k;
        if (k >= 1) {
            const cur = ED.win[sd] === 'all' ? 'all' : 'mate';
            w += `<div>${L(`Чтобы победить ${who} (королей: ${k}):`, `To beat ${who} (${k} ${k === 1 ? 'king' : 'kings'}):`)}</div>`
                + `<label><input type="radio" name="edwin-${sd}" data-win="${sd}" value="mate"${cur === 'mate' ? ' checked' : ''}>${k === 1 ? L('поставить мат королю', 'checkmate the king') : L('поставить мат хотя бы одному королю', 'checkmate at least one king')}</label>`
                + `<label><input type="radio" name="edwin-${sd}" data-win="${sd}" value="all"${cur === 'all' ? ' checked' : ''}>${L('срубить все их фигуры (короли тоже рубятся и уязвимы для магии)', 'capture all of their pieces (kings can be captured and are open to magic)')}</label>`;
        } else {
            w += `<div>${L(`У ${who} нет королей: чтобы победить, нужно срубить все их фигуры.`, `${who} has no kings: to win, capture all of their pieces.`)}</div>`;
        }
    });
    $('#edWin').innerHTML = w;
    $('#edWin').classList.toggle('need', need);
    $('#edMsg').textContent = ED.msg;
}

// Клетки с учётом зеркала. Возвращает [r, c, flipV, flipH]
function edMirrorCells(r, c) {
    const t = [[r, c, false, false]];
    if (ED.mirror >= 1) t.push([ED.n - 1 - r, c, true, false]);          // по вертикали: сверху вниз, цвет и владелец меняются
    if (ED.mirror >= 2) { t.push([r, ED.n - 1 - c, false, true]); t.push([ED.n - 1 - r, ED.n - 1 - c, true, true]); }
    return t;
}
function edFixWin() { const cnt = edCounts();['w', 'b'].forEach(sd => { if (cnt[sd].k < 1) ED.win[sd] = null; }); }

// Поставить фигуру (или убрать) с учётом зеркала
function edPlace(r, c) {
    let ch = ED.tool;
    if (ch === '.') return edErase(r, c);
    if (ch === 'X' || ch === 'x') {      // робот: сначала планшет, потом он встаёт на доску
        const wl = edBaseAt(r, c);
        if (wl && wl.k === 'wall') { ED.msg = L('На стене фигуру ставить нельзя: сначала уберите стену.', 'A piece cannot stand on a wall: remove the wall first.'); edRender(); return; }
        edRobOpen(r, c, chColor(ch));
        return;
    }
    if (ED.rows[r][c] === ch) ch = '.';          // повторное нажатие той же фигурой убирает её
    const t = edMirrorCells(r, c).map(([tr, tc, fv]) => [tr, tc, fv ? swapCase(ch) : ch]);
    if ((ch === 'P' || ch === 'p') && t.some(x => x[0] === 0 || x[0] === ED.n - 1)) {
        ED.msg = L('Пешку нельзя ставить на первую и последнюю горизонталь.', 'A pawn cannot be placed on the first or last rank.');
        edRender(); return;
    }
    if (ch !== '.' && t.some(([tr, tc]) => { const b = edBaseAt(tr, tc); return b && b.k === 'wall'; })) {
        ED.msg = L('На стене фигуру ставить нельзя: сначала уберите стену.', 'A piece cannot stand on a wall: remove the wall first.');
        edRender(); return;
    }
    t.forEach(([tr, tc, tch]) => { ED.rows[tr][tc] = tch; });
    ED.msg = '';
    edFixWin();
    edRender();
}

// Ластик: сначала дым, потом фигура, потом плитка
function edErase(r, c) {
    edMirrorCells(r, c).forEach(([tr, tc]) => {
        const f = edFogAt(tr, tc);
        if (f) { ED.tiles = ED.tiles.filter(x => x !== f); return; }
        if (ED.rows[tr][tc] !== '.') { ED.rows[tr][tc] = '.'; return; }
        const b = edBaseAt(tr, tc);
        if (b) ED.tiles = ED.tiles.filter(x => x !== b);
    });
    ED.msg = '';
    edFixWin();
    edRender();
}

// Плитка с учётом отражения
function edTileFor(item, r, c, fv, fh) {
    const flip = o => (fv ? (o === 'w' ? 'b' : o === 'b' ? 'w' : o) : o);
    const t = { k: item.k, r, c, o: item.pair ? (ED.opt.pair <= 2 ? 'w' : 'b') : (item.own ? flip(ED.opt.o === 'n' && !item.neu ? 'w' : ED.opt.o) : 'w') };
    if (item.dir) { const [dr, dc] = ED.opt.d; t.d = [fv ? -dr : dr, fh ? -dc : dc]; }
    if (item.s) t.s = item.s;
    if (item.pair) t.id = ED.opt.pair;
    return t;
}
function edPlaceTile(r, c) {
    const item = TILE_PALETTE.find(x => x.id === ED.tileId);
    const cells = item.pair ? [[r, c, false, false]] : edMirrorCells(r, c);
    const same = (a, b) => a && a.k === b.k && a.o === b.o && a.s === b.s && a.id === b.id && (a.d || []).join() === (b.d || []).join();
    // нажатие на ту же плитку с теми же настройками убирает её
    const first = edTileFor(item, r, c, false, false), there = item.k === 'fog' ? edFogAt(r, c) : edBaseAt(r, c);
    const removing = same(there, first);
    for (const [tr, tc, fv, fh] of cells) {
        const t = edTileFor(item, tr, tc, fv, fh);
        if (item.k === 'fog') {
            ED.tiles = ED.tiles.filter(x => !(x.r === tr && x.c === tc && x.k === 'fog'));
            if (!removing) ED.tiles.push(t);
            continue;
        }
        if (t.k === 'wall' && !removing && ED.rows[tr][tc] !== '.') { ED.msg = L('На клетке стоит фигура: стену ставить нельзя.', 'There is a piece on that square: a wall cannot be placed.'); edRender(); return; }
        if (t.k === 'portal' && !removing && ED.tiles.filter(x => x.k === 'portal' && x.id === t.id && !(x.r === tr && x.c === tc)).length >= 2) {
            ED.msg = L('У этой пары уже два портала. Уберите лишний или выберите другую пару.', 'This pair already has two portals. Remove one or choose another pair.'); edRender(); return;
        }
        ED.tiles = ED.tiles.filter(x => !(x.r === tr && x.c === tc && x.k !== 'fog'));
        if (!removing) ED.tiles.push(t);
    }
    ED.msg = '';
    edRender();
}

// Можно ли сохранить и играть: возвращает текст проблемы или ''
function edValidate() {
    const cnt = edCounts();
    if (!cnt.w.n || !cnt.b.n) return L('У каждой стороны должна быть хотя бы одна фигура.', 'Each side needs at least one piece.');
    for (const sd of ['w', 'b']) {
    }
    const pairs = {};
    ED.tiles.filter(t => t.k === 'portal').forEach(t => { pairs[t.id] = (pairs[t.id] || 0) + 1; });
    for (const id of Object.keys(pairs)) {
        if (pairs[id] !== 2) return L('У каждого портала должна быть пара: поставьте второй или уберите лишний.', 'Every portal needs a partner: place the second one or remove the extra.');
    }
    const cfg = edCfg(), saved = G, savedN = N;
    let bad = '';
    try {
        N = ED.n;
        G = newState(boardFromCfg(cfg), cfg.plain ? { w: 'none', b: 'none' } : { w: 'paladin', b: 'paladin' }, cfg.win);
        installTiles(G, cfg);
        for (const sd of ['w', 'b']) {
            if (!allMode(sd) && kingAttacked(G.board, sd)) { bad = L(`Королю ${edSideName(sd)} грозит шах: так сохранить нельзя.`, `The ${edSideName(sd)} king is in check: this cannot be saved.`); break; }
        }
        if (!bad && !anyLegalMove(G.board, 'w')) bad = L('У белых нет ни одного хода: партия закончилась бы сразу.', 'White has no legal moves: the game would end at once.');
    } catch (e) { bad = L('Не удалось проверить доску.', 'Could not check the board.'); }
    finally { G = saved; N = savedN; }
    return bad;
}

// ---------- события ----------
$('#edBoard').addEventListener('click', e => {
    const cell = e.target.closest('.cell');
    if (!cell) return;
    const r = +cell.dataset.r, c = +cell.dataset.c;
    if (ED.tool === '.') edErase(r, c);
    else if (ED.tab === 'pieces' && 'Xx'.includes(ED.rows[r][c])) edRobOpen(r, c, chColor(ED.rows[r][c]));      // нажатие на робота: перенастроить
    else if (ED.tab === 'tiles') edPlaceTile(r, c);
    else edPlace(r, c);
});
$('#edBoard').addEventListener('contextmenu', e => {          // правая кнопка мыши убирает (сначала дым, потом фигуру, потом плитку)
    const cell = e.target.closest('.cell');
    if (!cell) return;
    e.preventDefault();
    edErase(+cell.dataset.r, +cell.dataset.c);
});
$('.ed-tabs').addEventListener('click', e => {
    const b = e.target.closest('[data-tab]');
    if (!b) return;
    ED.tab = b.dataset.tab;
    if (ED.tab === 'pieces' && !'KQRBNPJXkqrbnpjx.'.includes(ED.tool)) ED.tool = 'P';
    if (ED.tab === 'tiles' && ED.tool !== '.') ED.tool = 'T';
    edRender();
});
$('#edPalette').addEventListener('click', e => { const b = e.target.closest('[data-tool]'); if (b) { ED.tool = b.dataset.tool; edRender(); } });
$('#edTiles').addEventListener('click', e => {
    const er = e.target.closest('[data-tool]');
    if (er) { ED.tool = '.'; edRender(); return; }
    const b = e.target.closest('[data-tile]');
    if (b) { ED.tileId = b.dataset.tile; ED.tool = 'T'; edRender(); }
});
$('#edTileOpts').addEventListener('click', e => {
    const b = e.target.closest('button');
    if (!b) return;
    if (b.dataset.o) ED.opt.o = b.dataset.o;
    if (b.dataset.d) ED.opt.d = b.dataset.d.split(',').map(Number);
    if (b.dataset.pair) ED.opt.pair = +b.dataset.pair;
    edRender();
});
$('#edMirror').addEventListener('click', e => { const b = e.target.closest('[data-m]'); if (b) { ED.mirror = +b.dataset.m; edRender(); } });
$('#edSlots').addEventListener('click', e => { const b = e.target.closest('[data-slot]'); if (b) { ED.slot = +b.dataset.slot; ED.msg = ''; edRender(); } });
$('#edPlain').addEventListener('change', e => { ED.plain = e.target.checked; });
$('#edSize').addEventListener('click', e => { const b = e.target.closest('[data-sz]'); if (b) edResize(+b.dataset.sz); });
$('#edWin').addEventListener('change', e => { const i = e.target.closest('[data-win]'); if (i) { ED.win[i.dataset.win] = i.value; ED.msg = ''; edRender(); } });
$('#edClassic').addEventListener('click', () => { ED.n = 8; ED.rows = CLASSIC_ROWS.map(r => [...r]); ED.tiles = []; ED.robs = []; ED.win = { w: null, b: null }; ED.msg = ''; edRender(); });
$('#edClear').addEventListener('click', () => { ED.rows = Array.from({ length: ED.n }, () => Array(ED.n).fill('.')); ED.tiles = []; ED.robs = []; ED.win = { w: null, b: null }; ED.msg = ''; edRender(); });
$('#edSave').addEventListener('click', () => {
    const bad = edValidate();
    if (bad) { ED.msg = bad; edRender(); return; }
    const cfg = normCfg(edCfg());
    if (!cfg) { ED.msg = L('Эту доску сохранить нельзя.', 'This board cannot be saved.'); edRender(); return; }
    ED.slots[ED.slot] = cfg;
    saveSlots(ED.slots);
    ED.msg = L(`Сохранено в слот ${ED.slot + 1}.`, `Saved to slot ${ED.slot + 1}.`);
    edRender();
});
$('#edLoad').addEventListener('click', () => {
    const cfg = ED.slots[ED.slot];
    if (!cfg) { ED.msg = L('Этот слот пуст.', 'This slot is empty.'); edRender(); return; }
    ED.n = cfg.rows.length;
    ED.plain = !!cfg.plain;
    ED.rows = cfg.rows.map(r => [...r]);
    ED.tiles = (cfg.tiles || []).map(t => ({ ...t, d: t.d ? [...t.d] : undefined }));
    ED.robs = (cfg.robs || []).map(o => ({ r: o.r, c: o.c, rob: JSON.parse(JSON.stringify(o.rob)) }));
    ED.win = { w: null, b: null };
    const cnt = edCounts();
    ['w', 'b'].forEach(sd => { if (cnt[sd].k >= 1) ED.win[sd] = cfg.win[sd]; });
    $('#edName').value = cfg.name || '';
    ED.msg = L(`Загружен слот ${ED.slot + 1}.`, `Loaded slot ${ED.slot + 1}.`);
    edRender();
});
$('#edDel').addEventListener('click', () => {
    ED.slots[ED.slot] = null;
    saveSlots(ED.slots);
    ED.msg = L(`Слот ${ED.slot + 1} очищен.`, `Slot ${ED.slot + 1} emptied.`);
    edRender();
});
$('#edUse').addEventListener('click', () => {
    const bad = edValidate();
    if (bad) { ED.msg = bad; edRender(); return; }
    const cfg = normCfg(edCfg());
    if (!cfg) { ED.msg = L('Эту доску использовать нельзя.', 'This board cannot be used.'); edRender(); return; }
    $('#editor').classList.add('hidden');
    if (ED.onPick) ED.onPick(cfg);
});
$('#edClose').addEventListener('click', () => $('#editor').classList.add('hidden'));

/* ---------- Роботы в редакторе: тот же планшет Инженера, но без перезарядки и без партии ---------- */
let EDROB = null;      // { r, c, col, m, last }
function edRobMode(col, rob) {
    const sg = engSign(col), view = d => [d[0] * sg, d[1] * sg];      // из «вида игрока» в доску и обратно: знак тот же
    const m = { type: 'assemble', stage: 'kind', kind: null, sel: null, walk: [], atk: [], ja: [], jw: [], wr: 1, hist: [], rb: false, ed: true };
    if (rob) {
        m.kind = rob.kind; m.sel = rob.kind; m.rb = true;      // уже стоящий робот: прежний выбор остаётся, его можно изменить
        if (rob.kind === 'wing') { m.ja = rob.ja.map(view); m.jw = rob.jw.map(view); } else { m.walk = rob.walk.map(view); m.atk = rob.atk.map(view); m.wr = rob.wr; }
        m.old = { kind: m.kind, walk: m.walk.map(d => [...d]), atk: m.atk.map(d => [...d]), ja: m.ja.map(d => [...d]), jw: m.jw.map(d => [...d]), wr: m.wr };
    }
    return m;
}
function edRobOpen(r, c, col) {
    const cur = ED.robs.find(o => o.r === r && o.c === c);
    EDROB = { r, c, col, m: edRobMode(col, cur && ED.rows[r][c] === (col === 'w' ? 'X' : 'x') ? cur.rob : null), last: null };
    edRobDraw();
}
function edRobDraw() {
    let ov = document.getElementById('edRobTab');
    if (!ov) {
        ov = document.createElement('div');
        ov.id = 'edRobTab';
        ov.className = 'eng-ov hidden';
        ov.style.zIndex = 4000;
        ov.addEventListener('click', e => {
            const b = e.target.closest('[data-eng]');
            if (!b || b.disabled || !EDROB) return;
            const act = b.dataset.eng;
            if (act === 'pick') SFX.engPick();
            else if (act === 'dir' || act === 'jump') (b.classList.contains('on') ? SFX.engOff : SFX.engOn)();
            else if (act === 'range') SFX.engOn();
            else if (act === 'back' || act === 'close') SFX.engBack();
            else SFX.engClick();
            let v = b.dataset.v;
            if (v !== undefined) { if (v.includes(',')) v = v.split(',').map(Number); else if (/^-?\d+$/.test(v)) v = Number(v); }
            edRobInput(act, v);
        });
        document.body.appendChild(ov);
    }
    if (!EDROB) { ov.classList.add('hidden'); return; }
    ov.innerHTML = engTabletHTML(EDROB.m)
        .replace(/<div class="eng-cost">[\s\S]*?<\/div>/, `<div class="eng-cost">${L('РЕДАКТОР ДОСКИ: ' + (EDROB.col === 'w' ? 'БЕЛЫЙ РОБОТ' : 'ЧЁРНЫЙ РОБОТ'), 'BOARD EDITOR: ' + (EDROB.col === 'w' ? 'WHITE ROBOT' : 'BLACK ROBOT'))}</div>`)
        .replace(/<button class="eng-min"[^>]*>[^<]*<\/button>/, '');
    ov.classList.remove('hidden');
    const key = EDROB.m.stage;
    if (key !== EDROB.last) {
        const sc = ov.querySelector('.eng-inner');
        if (sc && EDROB.last !== null && ANIM.board !== false) sc.classList.add('glitch');      // при выключенных анимациях экран не дрожит
        if (EDROB.last !== null) SFX.engSwitch();
    }
    EDROB.last = key;
}
function edRobInput(a, v) {
    const m = EDROB.m, st = m.stage;
    const go = ns => { m.hist.push(st); m.stage = ns; m.sel = null; };
    const okD = (d, lim) => Array.isArray(d) && d.length === 2 && d.every(x => Number.isInteger(x) && Math.abs(x) <= lim) && (d[0] || d[1]);
    if (a === 'close') { EDROB = null; edRobDraw(); return; }
    if (a === 'back') {
        if (!m.hist.length) { EDROB = null; edRobDraw(); return; }
        m.stage = m.hist.pop(); m.sel = null; edRobDraw(); return;
    }
    if (a === 'pick') {
        if ((st === 'kind' && (v === 'boot' || v === 'wing')) || ((st === 'after' || st === 'wingafter') && (v === 'boot' || v === 'x'))) {
            if (st === 'wingafter' && v === 'boot' && m.ja.length >= ENG_MAX_JUMP) return;
            m.sel = v;
        } else return;
    } else if (a === 'dir') {
        if (!okD(v, 1)) return;
        if (st === 'walk') engToggle(m.walk, v); else if (st === 'atk') engToggle(m.atk, v); else return;
    } else if (a === 'jump') {
        if (!okD(v, 2)) return;
        if (st === 'wing') {
            const had = engHas(m.ja, v), inJw = engHas(m.jw, v);
            if (!had && !inJw && m.ja.length + m.jw.length >= ENG_MAX_JUMP) return;
            if (!had && inJw) { const k2 = m.jw.findIndex(x => x[0] === v[0] && x[1] === v[1]); m.jw.splice(k2, 1); }
            engToggle(m.ja, v);
        } else if (st === 'wingplus') {
            if (engHas(m.ja, v)) return;
            if (!engHas(m.jw, v) && m.ja.length + m.jw.length >= ENG_MAX_JUMP) return;
            engToggle(m.jw, v);
        } else return;
    } else if (a === 'range') {
        if (st !== 'range' || (v !== 1 && v !== -1)) return;
        m.wr = Math.max(1, Math.min(ED.n - 1, m.wr + v));
    } else if (a === 'x2') {
        if (st !== 'walk' || !m.walk.length) return;
        m.atk = m.walk.map(d => [d[0], d[1]]);
        go('after');
    } else if (a === 'next') {
        if (st === 'kind') { if (m.sel !== 'boot' && m.sel !== 'wing') return; m.kind = m.sel; go(m.sel === 'boot' ? 'walk' : 'wing'); }
        else if (st === 'walk') go('atk');
        else if (st === 'atk') { if (m.walk.length + m.atk.length < 1) return; go('after'); }
        else if (st === 'after') {
            if (m.sel === 'boot') go('range');
            else if (m.sel === 'x') { if (!m.rb) m.wr = 1; edRobFinish(); return; }
            else return;
        }
        else if (st === 'range') { edRobFinish(); return; }
        else if (st === 'wing') { if (!m.ja.length) return; go('wingafter'); }
        else if (st === 'wingafter') {
            if (m.sel === 'boot') { if (m.ja.length >= ENG_MAX_JUMP) return; go('wingplus'); }
            else if (m.sel === 'x') { edRobFinish(); return; }
            else return;
        }
        else if (st === 'wingplus') { edRobFinish(); return; }
    } else return;
    edRobDraw();
}
// Планшет закрыт галочкой: робот встаёт на доску (с учётом зеркала: копии отражаются)
function edRobFinish() {
    const { r, c, col, m } = EDROB;
    const base = engBuild(m, col), cells = edMirrorCells(r, c);
    if (cells.some(([tr, tc]) => { const b = edBaseAt(tr, tc); return b && b.k === 'wall'; })) {
        ED.msg = L('На стене фигуру ставить нельзя: сначала уберите стену.', 'A piece cannot stand on a wall: remove the wall first.');
        EDROB = null; edRobDraw(); edRender(); return;
    }
    const refl = (d, fv, fh) => [fv ? -d[0] : d[0], fh ? -d[1] : d[1]];
    cells.forEach(([tr, tc, fv, fh]) => {
        const cc = fv ? other(col) : col;
        const rob = base.kind === 'wing'
            ? { kind: 'wing', ja: base.ja.map(d => refl(d, fv, fh)), jw: base.jw.map(d => refl(d, fv, fh)) }
            : { kind: 'boot', walk: base.walk.map(d => refl(d, fv, fh)), atk: base.atk.map(d => refl(d, fv, fh)), wr: base.wr, ar: base.ar };
        ED.rows[tr][tc] = cc === 'w' ? 'X' : 'x';
        ED.robs = ED.robs.filter(o => !(o.r === tr && o.c === tc));
        ED.robs.push({ r: tr, c: tc, rob });
    });
    EDROB = null; ED.msg = ''; edFixWin(); edRobDraw(); edRender();
    SFX.engOk();
}

// ---------- выбор доски в комнатах и на одном экране ----------
function boardPicker(root, st, allowFischer) {
    root.textContent = '';
    root.classList.add('bd-pick');
    const modes = [['classic', L('Обычные шахматы', 'Classic chess')]];
    if (allowFischer) modes.push(['fischer', L('🎲 Шахматы Фишера', '🎲 Fischer random')]);
    modes.push(['custom', L('🧩 Своя доска', '🧩 Custom board')]);
    const seg = mkEl('div', 'bd-seg'), btns = {};
    modes.forEach(([k, name]) => { const b = mkEl('button', '', name, true); b.type = 'button'; seg.appendChild(b); btns[k] = b; });
    const info = mkEl('div', 'bd-info', '', true);
    const edit = mkEl('button', 'small-btn', L('✏️ Редактор доски', '✏️ Board editor'), true);
    edit.type = 'button';
    root.append(mkEl('b', '', L('Доска для партии', 'Board for the game'), true), seg, info, edit);
    const paint = () => {
        Object.entries(btns).forEach(([k, b]) => b.classList.toggle('on', k === st.mode));
        edit.classList.toggle('hidden', st.mode !== 'custom');
        info.classList.toggle('hidden', st.mode === 'classic');
        if (st.mode === 'fischer') info.textContent = L('Фигуры на первой и последней горизонталях расставляются случайно, у обеих сторон одинаково. Рокировка по правилам Chess960: король встаёт на g или c, ладья на f или d (нажмите на ладью или на клетку короля).', 'Pieces on the first and last ranks are placed randomly, the same for both sides. Chess960 castling: the king goes to g or c, the rook to f or d (tap the rook or the king target square).');
        else if (st.mode === 'custom') info.textContent = st.cfg ? L(`Выбрана доска: ${st.cfg.name || 'без названия'} (фигур: ${cfgPieceCount(st.cfg)}${cfgTileCount(st.cfg) ? ', плиток: ' + cfgTileCount(st.cfg) : ''}).`, `Selected board: ${st.cfg.name || 'untitled'} (${cfgPieceCount(st.cfg)} pieces${cfgTileCount(st.cfg) ? ', ' + cfgTileCount(st.cfg) + ' tiles' : ''}).`) : L('Доска не выбрана: откройте редактор, соберите или загрузите доску и нажмите «Использовать эту доску».', 'No board selected: open the editor, build or load a board and press “Use this board”.');
    };
    Object.entries(btns).forEach(([k, b]) => b.addEventListener('click', () => { st.mode = k; paint(); }));
    edit.addEventListener('click', () => edOpen(cfg => { st.cfg = cfg; paint(); }, st.cfg));
    paint();
}

function colorPicker(root, st) {
    root.textContent = '';
    root.classList.add('bd-pick');
    const seg = mkEl('div', 'bd-seg'), btns = {};
    [['w', L('⬜ Белые', '⬜ White')], ['b', L('⬛ Чёрные', '⬛ Black')], ['r', L('🎲 Случайно', '🎲 Random')]].forEach(([k, name]) => {
        const b = mkEl('button', '', name, true); b.type = 'button'; seg.appendChild(b); btns[k] = b;
        b.addEventListener('click', () => { st.v = k; paint(); try { localStorage.setItem('sc_roomcolor', k); } catch (e) { } });
    });
    root.append(mkEl('b', '', L('Ваши фигуры', 'Your pieces'), true), seg);
    const paint = () => Object.entries(btns).forEach(([k, b]) => b.classList.toggle('on', k === st.v));
    paint();
}


/* =====================================================================
   ВОЗВРАТ В ОНЛАЙН-ПАРТИЮ
   Пока идёт партия, браузер запоминает комнату. Если приложение закрылось или страница перезагрузилась (например, на телефоне),
   при следующем открытии игра заново собирает партию из записи ходов на сервере и возвращает игрока на то же место.
   Если соперник за это время пропал на минуту, ему засчитывается поражение (это решает сервер).
   ===================================================================== */
const RESUME_KEY = 'sc_resume';
let _resumeSavedAt = 0;
function clearResume() { try { localStorage.removeItem(RESUME_KEY); } catch (e) { } }
function saveResume() {
    if (!NET.on || !G || G.over || REPLAY.on || !NET.conn || !NET.conn.info || !NET.conn.info.sid) return;
    const now = Date.now();
    if (now - _resumeSavedAt < 1500) return;
    _resumeSavedAt = now;
    try {
        localStorage.setItem(RESUME_KEY, JSON.stringify({
            v: 1, ts: now, room: NET.conn.info.code, role: NET.conn.info.role, sid: NET.conn.info.sid,
            me: NET.me, hostColor: NET.hostColor || 'w', tc: NET.tc || 0, inc: NET.inc || 0, rated: !!NET.rated, mode: NET.mode || null, custom: !!NET.custom,
            clock: CLOCK && CLOCK.on ? { left: { ...CLOCK.left }, open: { ...CLOCK.open } } : null
        }));
    } catch (e) { }
}

async function tryResume() {
    let sv = null;
    try { sv = JSON.parse(localStorage.getItem(RESUME_KEY) || 'null'); } catch (e) { }
    if (!sv) return;
    if (sv.v !== 1 || !sv.room || !sv.sid || Date.now() - sv.ts > 10 * 60 * 1000) { clearResume(); return; }
    for (let i = 0; !RELAY_CHECKED && i < 120; i++) await sleep(500);      // сервер на бесплатном Render просыпается до минуты
    if (!RELAY || G) return;
    let st = null;
    try { const r = await fetch(API + `/state?room=${sv.room}&role=${sv.role}&sid=${sv.sid}`); if (r.ok) st = await r.json(); } catch (e) { }
    if (!st || !st.start || !Array.isArray(st.inputs)) { clearResume(); return; }
    ['lobby', 'setup', 'prof', 'top', 'auth', 'coll', 'rooms', 'local', 'gameover', 'promo', 'editor', 'report'].forEach(id => { const el = $('#' + id); if (el) el.classList.add('hidden'); });
    NET.on = true; NET.host = sv.role === 'host'; NET.hostColor = sv.hostColor; NET.me = sv.me;
    NET.tc = sv.tc; NET.inc = sv.inc; NET.rated = !!sv.rated; NET.mode = MODES[sv.mode] ? sv.mode : null; NET.custom = !!sv.custom; NET.fischer = false;
    NET.lost = false; NET.oppLeft = false; NET.resumed = true;
    const conn = relayConn(sv.room, sv.role, null, { sid: sv.sid, last: st.seq });      // те же sid и номер последнего сообщения: сервер доставит пропущенное
    conn.open = true;
    attachConn(conn);
    const m = st.start;
    selectedHeroes = { ...m.heroes }; _seed = m.seed; CUSTOM = normCfg(m.custom);
    startGame();
    // партия заново проигрывается в памяти без звуков и анимаций (так же, как повтор)
    const animWas = { ...ANIM };
    ANIM.board = true; ANIM.banner = true;
    REPLAY_REC = [];
    NET.on = false;
    try {
        for (const inp of st.inputs) {
            if (!G || G.over) break;
            if (inp && inp.t === 'cfg') continue;
            try { applyInput(inp); } catch (e) { break; }
            REPLAY_REC = [];
        }
    } finally {
        NET.on = true;
        REPLAY_REC = null;
        Object.assign(ANIM, animWas);
        ANIMQ.length = 0; ANIM_HIDE.length = 0;
        if (G) G.fx = [];
    }
    NET.resumed = false;
    if (!G) { clearResume(); return; }
    if (st.result && !G.over) {      // пока вас не было, партия закончилась (сдача, время, отключение)
        G.over = st.result === 'd' ? { winner: null, title: 'Ничья', text: 'Партия окончена вничью.' } : { winner: st.result, title: st.result === NET.me ? 'Победа' : 'Поражение', text: `${colorName(st.result)} побеждают.` };
    }
    if (G.over) { G.repSent = true; render(); showGameOver(); clearResume(); return; }
    if (sv.clock && CLOCK.on) {      // часы: то, что было записано, минус время, пока вас не было
        CLOCK.left = { ...sv.clock.left }; CLOCK.open = { ...sv.clock.open };
        const away = Math.max(0, (Date.now() - sv.ts) / 1000), pool = inOpening(G.turn) ? CLOCK.open : CLOCK.left;
        pool[G.turn] = Math.max(1, pool[G.turn] - away);
        CLOCK.last = performance.now(); CLOCK.prev = G.turn;
    }
    sendAuth();
    render();
}
// На замороженную фигуру нельзя накинуть ни бафф, ни дебафф: способности по одной фигуре её не выбирают
const FROZEN_BLOCK = ['shield', 'rescue', 'guardian', 'purify', 'bumpuku', 'phase', 'fukashi', 'superposition', 'scream', 'hypnosis', 'confusion', 'assistant', 'hocus', 'soulmates', 'lie', 'illusion', 'blunder', 'frankenstein'];
const _abilityCellsFrozen = abilityCells;
abilityCells = function (key) {
    const res = _abilityCellsFrozen.apply(this, arguments);
    if (!FROZEN_BLOCK.includes(key) || !Array.isArray(res) || !G) return res;
    const ok = ([r, c]) => { const q = G.board[r] && G.board[r][c]; return !(q && q.frozen > 0); };
    const out = res.filter(ok);
    if (res.show) out.show = res.show.filter(ok);
    return out;
};

// ===== Перетаскивание фигуры на клетку (мышью и пальцем). Обычные клики работают как раньше =====
(function () {
    const board = document.getElementById('board');
    if (!board) return;
    let d = null, swallow = false;
    const stop = () => {
        if (d && d.ghost) d.ghost.remove();
        board.querySelectorAll('.drag-src').forEach(x => x.classList.remove('drag-src'));
        document.body.classList.remove('piece-drag');
        d = null;
    };
    const place = (g, x, y) => { g.style.left = x + 'px'; g.style.top = y + 'px'; };
    board.addEventListener('pointerdown', e => {
        if (d || (e.pointerType === 'mouse' && e.button !== 0)) return;
        const cell = e.target.closest('.cell');
        if (!cell || !G || G.over || G.pendingPromo || REPLAY.on || REW.idx >= 0) return;
        const r = +cell.dataset.r, c = +cell.dataset.c, p = G.board[r] && G.board[r][c];
        if (!p || p.c !== G.turn || (NET.on && (NET.lost || !isActor()))) return;      // тащить можно только свою фигуру в свой ход
        d = { id: e.pointerId, r, c, x0: e.clientX, y0: e.clientY, on: false, ghost: null };
    });
    document.addEventListener('pointermove', e => {
        if (!d || e.pointerId !== d.id) return;
        if (!d.on) {
            if (Math.abs(e.clientX - d.x0) + Math.abs(e.clientY - d.y0) < 10) return;
            if (!G || G.over || G.mode) { stop(); return; }      // во время способностей перетаскивание не нужно
            const same = G.sel && G.sel.r === d.r && G.sel.c === d.c;
            if (!same) {
                if (G.sel) netDo({ t: 'esc' });
                CONFIRM.pend = null;
                netDo({ t: 'cell', r: d.r, c: d.c });
            }
            if (!G.sel || G.sel.r !== d.r || G.sel.c !== d.c) { stop(); return; }      // выбрать эту фигуру нельзя
            const src = board.querySelector(`.cell[data-r="${d.r}"][data-c="${d.c}"] .piece`);
            if (!src) { stop(); return; }
            const sz = src.getBoundingClientRect(), g = src.cloneNode(true);
            g.classList.add('drag-ghost');
            g.style.width = sz.width + 'px'; g.style.height = sz.height + 'px';
            document.body.appendChild(g);
            src.classList.add('drag-src');
            d.ghost = g; d.on = true; d.w = sz.width; d.h = sz.height;
            document.body.classList.add('piece-drag');
            try { board.setPointerCapture(e.pointerId); } catch (x) { }
        }
        place(d.ghost, e.clientX - d.w / 2, e.clientY - d.h * 0.8);      // фигура чуть выше пальца, чтобы её было видно
        e.preventDefault();
        const el = document.elementFromPoint(e.clientX, e.clientY), cell = el && el.closest ? el.closest('#board .cell') : null;
        board.querySelectorAll('.drag-over').forEach(x => x.classList.remove('drag-over'));
        if (cell) cell.classList.add('drag-over');
    }, { passive: false });
    const finish = (e, drop) => {
        if (!d || e.pointerId !== d.id) return;
        const was = d.on;
        let cell = null;
        if (was && drop) { const el = document.elementFromPoint(e.clientX, e.clientY); cell = el && el.closest ? el.closest('#board .cell') : null; }
        board.querySelectorAll('.drag-over').forEach(x => x.classList.remove('drag-over'));
        const from = d;
        stop();
        if (was) {
            swallow = true; setTimeout(() => { swallow = false; }, 350);      // клик после перетаскивания игнорируем
            if (cell) {
                const r = +cell.dataset.r, c = +cell.dataset.c;
                if (r !== from.r || c !== from.c) boardCellAct(r, c);      // отпустили на другой клетке: как обычное нажатие на неё
            }
        }
    };
    document.addEventListener('pointerup', e => finish(e, true));
    document.addEventListener('pointercancel', e => finish(e, false));
    document.addEventListener('click', e => { if (swallow) { e.stopPropagation(); e.preventDefault(); swallow = false; } }, true);
    board.addEventListener('dragstart', e => e.preventDefault());
})();

